(window.GIM_TS=window.GIM_TS||{})["Sukkah.2"]={"from":48,"a":[["\u0003משום ר' שילא אמרו: חתן פטור\u0004 מקריאת שמע \u0003והשושבינין וכל בני החופה חייבין.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005];\u0006 \u0003אמר ר' חנניא בן עקביא: כותבי ספרים\u0004 (ספרי תורה) \u0003תפילין ומזוזות, הן\u0004 עצמן \u0003ותגריהן\u0004 הסוחרים המוכרים אותם \u0003ותגרי תגריהן\u0004 הקונים מן הסוחרים הראשונים ומוכרים אותם לאחרים \u0003וכל העוסקין במלאכת שמים, לאתויי\u0004 \u0005[להוסיף]\u0006 בכלל אלה אף \u0003מוכרי תכלת\u0004 לציצית — \u0003פטורין מקריאת שמע ומן התפלה ומן התפילין ומכל\u0004 ה\u0003מצות האמורות בתורה,\u0004 בזמן שהם עוסקים במלאכה זו, \u0003לקיים\u0004 את \u0003דברי ר' יוסי הגלילי, שהיה ר' יוסי הגלילי אומר: העוסק במצוה פטור מן המצוה.\u0004","לענין סוכה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הולכי דרכים\u0004 ההולכים \u0003ביום\u0004 — \u0003פטורין מן הסוכה ביום, וחייבין בלילה. הולכי דרכים בלילה\u0004 — \u0003פטורין מן הסוכה בלילה וחייבין ביום. הולכי דרכים\u0004 הן \u0003ביום ו\u0004הן \u0003בלילה\u0004 — \u0003פטורין מן הסוכה בין ביום ובין בלילה.\u0004 וה\u0003הולכין לדבר מצוה\u0004 — \u0003פטורין בין ביום ובין בלילה,\u0004 אפילו שאינם הולכים בלילה, משום שהם עוסקים במצוותם. מסופר: \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003רב חסדא ורבה בר רב הונא כי הוו עיילי בשבתא דריגלא לבי ריש גלותא\u0004 \u0005[כאשר היו באים בשבת הרגל לבית ראש הגולה],\u0006 לשמוע את דרשת הרגל של ראש הגולה, \u0003הוו גנו ארקתא דסורא\u0004 \u0005[היו ישנים על שפת\u0006 נהר \u0005סורא]\u0006 ולא בסוכה, \u0003אמרי\u0004 \u0005[היו אומרים]:\u0006 \u0003אנן\u0004 \u0005[אנחנו]\u0006 \u0003שלוחי מצוה אנן\u0004 \u0005[אנחנו]\u0006 \u0003ופטורין\u0004 אנו ממצות סוכה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שומרי העיר ביום\u0004 — \u0003פטורין מן הסוכה ביום וחייבין בלילה, שומרי העיר בלילה\u0004 — \u0003פטורין מן הסוכה בלילה וחייבין ביום. שומרי העיר בין ביום ובין בלילה\u0004 — \u0003פטורין מן הסוכה בין ביום ובין בלילה.\u0004","\u0003שומרי גנות ופרדסים\u0004 — \u0003פטורים\u0004 מן הסוכה \u0003בין ביום ובין בלילה.\u0004 ושואלים: שומרי גנות אלה \u0003ליעבדי\u0004 \u0005[שיעשו]\u0006 \u0003סוכה התם\u0004 \u0005[שם]\u0006 במקום ששומרים בו \u0003וליתבו\u0004 \u0005[וישבו]\u0006 ומדוע יפטרו מן הסוכה? \u0003אביי אמר:\u0004 טעם הדבר הוא משום שנאמר \u0003\"\u0004בסוכות \u0003תשבו\"\u0004 (ויקרא כג, מב) ואמרו חכמים כי \"תשבו\" משמעו — \u0003כעין תדורו,\u0004 כעין דירתכם הקבועה. וכיון שאין השומר יכול להכין במקום השמירה סוכה הראויה לדירה גמורה על כל אביזריה — אין המצוה חלה עליו.","\u0003רבא אמר: פרצה קוראה לגנב.\u0004 שאם קבע לו השומר סוכה לישיבתו ידעו הגנבים שהשומר נמצא בצידו האחד של השדה ויפרצו במקום אחר. וכשאין מחייבים את השומר בסוכה, אין יוצרים \"פירצה\" כזו בשמירה. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מהו\u0006 ההבדל המעשי \u0005ביניהם]\u0006 בין שני הטעמים הללו? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהם]\u0006 \u0003דקא מנטר כריא דפירי\u0004 \u0005[שהוא שומר כרי,\u0006 ערימה, \u0005של פירות],\u0006 שמצד צרכי השמירה יכול לקבוע סוכתו שם, שהרי שומר רק במקום מצומצם אבל אין יכול לקיים \"תשבו כעין תדורו\".","נאמר במשנה כי \u0003חולים ומשמשיהם\u0004 פטורים מן הסוכה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חולה שאמרו\u0004 שפטור מן הסוכה \u0003לא\u0004 דווקא \u0003חולה שיש בו סכנה\u0004 (סכנת נפשות), \u0003אלא אפילו חולה שאין בו סכנה.\u0004 ו\u0003אפילו\u0004 זה ש\u0003חש\u0004 \u0005[סובל]\u0006 \u0003בעיניו, ואפילו\u0004 ה\u0003חש בראשו. אמר רבן שמעון בן גמליאל: פעם אחת חשתי בעיני בקיסרי והתיר ר' יוסי בריבי\u0004 (הגדול החשוב), הוא ר' יוסי בן חלפתא, \u0003לישן אני ומשמשי\u0004 מ\u0003חוץ לסוכה.\u0004","מעין זה מסופר: \u0003רב שרא\u0004 \u0005[התיר]\u0006 \u0003לרב אחא ברדלא למגנא בכילתא\u0004 \u0005[לישון בתוך כילה]\u0006 \u0003בסוכה,\u0004 אף שגבוהה הכילה עשרה טפחים ויותר והריהו כאילו ישן בתוך בית בסוכה ואינו יוצא חובת סוכה — \u0003משום בקי\u0004 \u0005[הזבובים\u0006 הנושכים\u0005].\u0006 \u0003רבא שרא ליה\u0004 \u0005[התיר לו]\u0006 \u0003לר' אחא בר אדא למיגנא בר ממטללתא\u0004 \u0005[לישון חוץ לסוכה],\u0006 \u0003משום סירחא דגרגישתא\u0004 \u0005[הסרחון של האדמה]\u0006 שבקרקע הסוכה.","ומעירים: \u0003רבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא:\u0004 ה\u0003מצטער,\u0004 כלומר: מי שהישיבה בסוכה גורמת לו צער ויסורים — \u0003פטור מן הסוכה.\u0004 ושואלים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003חולין ומשמשיהן פטורין מן הסוכה,\u0004 ונדייק: \u0003חולה — אין\u0004 \u0005[כן]\u0006 פטור, אבל \u0003מצטער — לא\u0004 פטור! ומשיבים, \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003חולה — הוא ומשמשיו פטורין,\u0004 אולם ה\u0003מצטער\u0004 שאינו חולה ממש \u0003— הוא פטור,\u0004 אולם \u0003משמשיו לא.\u0004","שנינו במשנה: \u0003אוכלים אכילת ארעי חוץ לסוכה.\u0004 ושואלים: \u0003וכמה היא אכילת ארעי? אמר רב יוסף:\u0004 פת כשיעור \u0003תרתי או תלת ביעי\u0004 \u0005[שתים או שלוש ביצים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא זימנין סגיאין סגי ליה לאיניש בהכי, והוה ליה\u0004 \u0005[והרי פעמים רבות די לו לאדם בכך, ו\u0006הרי \u0005היא לו]\u0006 כ\u0003סעודת קבע! אלא אמר אביי: כדטעים בר בי רב ועייל לכלה\u0004 \u0005[כ\u0006שיעור \u0005שטועם תלמיד מבית רב,\u0006 שבולע מעט אוכל, \u0005ונכנס ל\u0006שמוע \u0005את הדרשה],\u0006 ובדרך זו ודאי שאין אכילתו נחשבת כאכילת קבע.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אוכלין אכילת עראי חוץ לסוכה ואין ישנים שינת עראי חוץ לסוכה.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל, שהרי מצות אכילה חובה היא כמצות שינה בסוכה? \u0003אמר רב אשי:\u0004 איסור השינה מחוץ לסוכה ואפילו שנת ארעי \u0003גזרה\u0004 הוא \u0003שמא ירדם\u0004 וימשיך לישון שינת קבע גמורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003ישן אדם שינת עראי בתפילין, אבל לא שינת קבע,\u0004 אף כאן \u0003ליחוש\u0004 \u0005[שיחשוש]\u0006 \u0003שמא ירדם\u0004 ותמצא שנתו קבע! \u0003אמר רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רב עילאי:\u0004 לענין תפילין מדובר \u0003במוסר שינתו לאחרים.\u0004 כלומר: מבקש מאדם אחר שיעיר אותו לאחר זמן קצר.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב משרשיא: ערביך ערבא צריך\u0004 \u0005[הערב שלך צריך ערב]!\u0006 כלומר: ומי יבטיח לנו שאף הממונה על כך לא ירדם בינתיים, וישנו שניהם?! \u0003אלא אמר רבה בר בר חנה אמר ר' יוחנן: במניח ראשו בין ברכיו עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שבמצב כזה אינו יכול לישון שינת קבע, אלא לנמנם בלבד. \u0003רבא אמר:\u0004 טעם איסור שינת ארעי בסוכה אינו משום חשש לשינת קבע, אלא משום שבכלל \u0003אין קבע לשינה,\u0004 שכל שינה נחשבת כקבע ולכן אסרו עליו לישון שינה כלשהי מחוץ לסוכה. ולענין תפילין יש לומר, שאין חוששים שמא ירדם.","ומעירים, \u0003תניא חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003ישן אדם בתפילין שינת עראי אבל לא שינת קבע, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003בין קבע בין עראי\u0004 יכול לישון. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 עוד ברייתא \u0005אחרת]:\u0006 אינו ישן \u0003לא קבע ולא עראי.\u0004 ומסבירים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 שיש ליישב: \u0003הא\u0004 \u0005[זו]\u0006 שאמרנו שאינו ישן אף שינת עראי — \u0003דנקיט להו בידיה\u0004 \u0005[שהוא מחזיק אותן,\u0006 את התפילין \u0005בידו]\u0006 אסור לו לישון כך אפילו שינת עראי, שמא יפלו מידו. \u0003הא\u0004 \u0005[זו]\u0006 שהתירו רק שינת עראי — \u0003דמנחי ברישיה\u0004 \u0005[שמונחים\u0006 התפילין \u0005על ראשו]\u0006 ולכן בשינת עראי אין לחשוש שמא יפיח ריח רע מתוכו או יטמא, ובשינת קבע יש לחשוש. \u0003הא\u0004 \u0005[זה]\u0006 שמותר לישון אף שינת קבע — \u0003דפריס סודר עלויה\u0004 \u0005[\u0006שחולץ אותן \u0005ופורס מטפחת עליהם]\u0006 וישן לצד התפילין.","ושואלים: \u0003וכמה\u0004 היא \u0003שינת עראי? תני\u0004 \u0005[שנה]\u0006 \u0003רמי בר יחזקאל:\u0004 זמן הדרוש \u0003כדי הלוך מאה אמה.\u0004 ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 ביחס לשיעור זה: \u0003הישן בתפילין ורואה קרי\u0004 בעוד התפילין עליו — \u0003אוחז ברצועה\u0004 של התפילין"],["\u0003ואינו אוחז בקציצה\u0004 בגוף התפילין עצמן, שלא יגע בהן בעודו טמא, אלו \u0003דברי ר' יעקב. וחכמים אומרים: ישן אדם בתפילין שינת עראי אבל לא שינת קבע,\u0004 וממילא אינו יכול להגיע לקרי. \u0003וכמה שינת עראי\u0004 — \u0003כדי הילוך מאה אמה.\u0004","אגב הדברים שנאמרו בשינת עראי, מביאים מה ש\u0003אמר רב: אסור לאדם לישן ביום יותר משינת סוס\u0004 והישן יותר מזה הרי הוא כמבטל תורה. \u0003וכמה\u0004 היא \u0003שינת הסוס\u0004 — \u0003שיתין נשמי\u0004 \u0005[שישים נשימות].\u0006","\u0003אמר אביי: שנתיה דמר\u0004 \u0005[שנתו של אדוני,\u0006 רבה\u0005]\u0006 היתה \u0003כ\u0004שנתו של \u0003רב, ורב\u0004 היה ישן \u0003כ\u0004שנתו של \u0003רבי\u0004 (ר' יהודה הנשיא), וזו של \u0003רבי\u0004 היתה \u0003כ\u0004של \u0003דוד\u0004 המלך, \u0003ו\u0004שנתו של \u0003דוד\u0004 היתה \u0003כדסוסיא\u0004 \u0005[כ\u0006שינת \u0005הסוס],\u0006 \u0003ודסוסיא\u0004 \u0005[ושל הסוס]\u0006 היא בת \u0003שיתין נשמי\u0004 \u0005[שישים נשימות].\u0006","מסופר: \u0003אביי הוה ניים כדמעייל\u0004 \u0005[היה ישן\u0006 ביום \u0005כ\u0006זמן \u0005הכניסה,\u0006 ההליכה\u0005]\u0006 בין \u0003פומבדיתא לבי כובי. קרי עליה\u0004 \u0005[היה קורא עליו]\u0006 \u0003רב יוסף\u0004 את הפסוק: \u0003\"עד מתי עצל תשכב מתי תקום משנתך\"\u0004 (משלי ו, ט), שראה בכך כבר ביטול זמן מיותר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הנכנס לישן ביום, רצה — חולץ\u0004 תפילין מעליו, \u0003רצה — מניח\u0004 אותן על ראשו. ההולך לישון \u0003בלילה\u0004 — \u0003חולץ\u0004 את התפילין \u0003ואינו מניח,\u0004 אלו \u0003דברי ר' נתן. ר' יוסי אומר: הילדים\u0004 (אנשים צעירים), \u0003לעולם חולצין ואינן מניחים\u0004 בשנתם, \u0003מפני שרגילין בטומאה.\u0004 שעלולים לבוא לידי קרי וכיוצא בו.","ושואלים: \u0003לימא קסבר\u0004 \u0005[האם נאמר שסבר]\u0006 \u0003ר' יוסי\u0004 ש\u0003בעל קרי אסור להניח תפילין? אמר אביי:\u0004 לא כן, אלא \u0003בילדים\u0004 (אנשים צעירים) \u0003ונשותיהן עמהן עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003שמא יבואו לידי הרגל דבר.\u0004 שעלולים הם לשכוח שהתפילין בראשם ויבואו כשעדיין התפילין בראשם לידי תשמיש, ודבר זה בודאי גנאי הוא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שכח\u0004 שהיו תפילין עליו \u0003ושמש מטתו בתפילין\u0004 — \u0003אינו אוחז לא ברצועה\u0004 של תפילין \u0003ולא בקציצה\u0004 (גוף התפילין), כדי להסירן מראשו, \u0003עד שיטול ידיו\u0004 תחילה ואז \u0003יטלם\u0004 מעליו \u0003מפני שהידים עסקניות הן\u0004 ויש לחשוש שנגעו במקום מטונף שבגוף, גם אם אינו זוכר בבירור שעשה כן.","בהמשך לאמור במשנה הקודמת בדין אכילה בסוכה מסופר: \u0003מעשה והביאו לו לרבן יוחנן בן זכאי לטעום את התבשיל, ולרבן גמליאל\u0004 הביאו \u0003שני כותבות\u0004 (תמרים) \u0003ודלי\u0004 (ספל) \u0003של מים. ואמרו\u0004 שניהם: \u0003העלום לסוכה\u0004 ושם נאכל.","ולעומת זאת מספרים סיפור מנוגד: \u0003וכשנתנו לו לר' צדוק אוכל\u0004 (פת) שיעור \u0003פחות מכביצה, נטלו במפה\u0004 משום נקיות. ולא נטל ידיו, משום שלדעתו אין צורך בנטילת ידים לאכילה של פחות מכביצה. \u0003ואכלו חוץ לסוכה, ולא בירך אחריו,\u0004 משום שלדעתו אין לברך אלא על שיעור המשביע (שנאמר: \"ואכלת ושבעת וברכת\") ואין בפחות מכביצה כדי שביעה. וכאשר יבואר שכל אלה עשה כדין.","על המעשה הראשון המסופר במשנה תוהים: וכי מביאים \u0003מעשה לסתור?!\u0004 שהרי במשנה הקודמת שנינו שמותר לאכול ארעי חוץ לסוכה, וכאן מביאים מעשה שממנו למדים לכאורה שאין אוכלים כלל חוץ לסוכה! ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך יש לשנותה],\u0006 שצריך להבינה כאילו היו בה דברי ההשלמה הבאים: \u0003אם בא להחמיר על עצמו\u0004 שלא לאכול כלל מחוץ לסוכה — \u0003מחמיר, ולית ביה\u0004 \u0005[ואין בכך]\u0006 \u0003משום יוהרא,\u0004 שמראה שנוהג מנהג חסידות יוצא מגדר הרגיל. ומובא \u0003ומעשה נמי\u0004 \u0005[גם כן]\u0006 לראיה, ש\u0003הביאו לו לרבן יוחנן בן זכאי לטעום את התבשיל ולרבן גמליאל שני כותבות ודלי של מים\u0004 בחג הסוכות,"],["\u0003ואמרו: העלום לסוכה.\u0004","\u0003וכשנתנו לו לר' צדוק אוכל פחות מכביצה נטלו במפה, ואכלו חוץ לסוכה ולא בירך אחריו.\u0004 ומדייקים מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה זה אוכל בשיעור \u0003כביצה, בעי\u0004 \u0005[\u0006היה \u0005צריך]\u0006 לאכלו ב\u0003סוכה. לימא תיהוי תיובתיה\u0004 \u0005[\u0006שמא \u0005תאמר\u0006 ש\u0005תהא זו קושיה]\u0006 על שיטת \u0003רב יוסף ואביי\u0004 שאמרו (לעיל סוכה כו, א) שכשיעור זה מותר לו לאדם לאכול עראי חוץ לסוכה! ומשיבים: מכאן אין להוכיח, כי \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003פחות מכביצה נטילה\u0004 לידים \u0003וברכה\u0004 (ברכת המזון) \u0003לא בעי\u0004 \u0005[צריך],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 שיעור \u0003כביצה בעי\u0004 \u0005[צריך]\u0006 \u0003נטילה וברכה,\u0004 ומשום כך סיפר את המעשה כך, אבל לענין סוכה אין ללמוד מכאן, ושמא אף בשיעור כביצה אינו חייב בסוכה.","\u0003ר' אליעזר אומר: ארבע עשרה סעודות חייב אדם לאכול בסוכה\u0004 בשבעת ימי חג הסוכות, \u0003אחת ביום ואחת בלילה. וחכמים אומרים: אין לדבר קצבה,\u0004 ויכול לאכול כמה שרוצה או שלא לאכול כלל, \u0003חוץ מלילי יום טוב הראשון של חג בלבד\u0004 שמצוה היא לאכול אז בסוכה.","\u0003ועוד אמר ר' אליעזר: מי שלא אכל בלילי יום טוב הראשון\u0004 של חג — \u0003ישלים\u0004 סעודה \u0003בלילי יום טוב האחרון של חג\u0004 בשמיני עצרת, אף שאינו אוכל בסוכה. \u0003וחכמים אומרים: אין לדבר תשלומין, ועל זה\u0004 וכיוצא בזה שביטל מצות עשה שאין לה תיקון \u0003נאמר: \"מעות לא יוכל לתקן וחסרון לא יוכל להמנות\"\u0004 (קהלת א, טו).","שואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' אליעזר\u0004 המחייב לאכול בסוכה? ומשיבים: לדעתו מה שנאמר \u0003\"\u0004בסוכות \u0003תשבו\"\u0004 (ויקרא כג מב), ואמרו חכמים שתהא ישיבה זו הוא \u0003כעין תדורו,\u0004 כדרך שנוהג אדם בדירתו הקבועה. \u0003מה דירה\u0004 אדם אוכל כרגיל סעודה \u0003אחת ביום ו\u0004סעודה \u0003אחת בלילה, אף סוכה\u0004 — סעודה \u0003אחת ביום ואחת בלילה.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה טעמם? לדעתם סוכה היא \u0003כדירה, מה דירה אי בעי אכיל אי בעי לא אכיל\u0004 \u0005[אם רוצה אוכל אם רוצה אינו אוכל],\u0006 \u0003אף סוכה נמי\u0004 \u0005[גם כן]\u0006 \u0003אי בעי אכיל אי בעי לא אכיל\u0004 \u0005[אם רוצה אוכל אם רוצה אינו אוכל].\u0006","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו לילי יום טוב הראשון נמי\u0004 \u0005[גם כן]\u0006 אם לא ירצה לא יאכל!","\u0003אמר ר' יוחנן משום ר' שמעון בן יהוצדק: נאמר כאן \u0004בסכות: \u0003\"חמשה עשר\"\u0004 (\"בחמישה עשר יום לחודש השביעי הזה חג הסוכות שבעת ימים לה'\". ויקרא כג, לד), \u0003ונאמר: \"חמשה עשר\" בחג המצות\u0004 (\"ובחמישה עשר יום לחודש הזה חג המצות לה'\". ויקרא כג, ו), \u0003מה להלן\u0004 בחג המצות \u0003לילה ראשון חובה\u0004 היא לאכול מצות, \u0003מכאן ואילך רשות\u0004 ואם אינו רוצה אינו אוכל מצה (ובלבד שלא יאכל חמץ). \u0003אף כאן\u0004 בסוכה — \u0003לילה הראשון חובה\u0004 לאכול, \u0003מכאן ואילך רשות.\u0004","ושואלים: \u0003והתם מנא לן\u0004 \u0005[ושם מניין לנו]\u0006 שאכן יש בפסח חובה לאכול מצה בלילה הראשון? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"בערב תאכלו מצת\"\u0004 (שמות יב, יח), לומר: \u0003הכתוב קבעו חובה,\u0004 שבערב זה על כל פנים חייבים לאכול מצות.","שנינו במשנה כי \u0003עוד אמר ר' אליעזר,\u0004 שמשלים אדם את הסעודה שלא אכל ביום טוב ראשון ביום טוב אחרון. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אליעזר ארבע עשרה סעודות חייב אדם לאכל בסוכה אחת ביום ואחת בלילה\u0004 וכשאוכל סעודה נוספת בליל שמיני עצרת כהשלמה, הרי אינו אוכלה בסוכה שהרי אין חיוב סוכה אז! \u0003אמר\u0004 החכם \u0003בירא אמר ר' אמי: חזר בו ר' אליעזר\u0004 מדבריו וסבור הוא כשיטת חכמים שאין לדבר קיצבה ואוכל כפי רצונו, וכן אם רוצה בכך יכול אף שלא לאכול כלל, פרט לסעודת ליל יום טוב הראשון של החג, מחמת שמחת החג, ואם לא קיים סעודה זו, יכול לדעתו (בניגוד לדעת חכמים) להשלימה ביום טוב האחרון.","ושואלים: \u0003משלים במאי\u0004 \u0005[במה]\u0006 את מה שהחסיר מסעודות החג? \u0003אילימא בריפתא\u0004 \u0005[אם תאמר\u0006 שמשלים \u0005בפת],\u0006 הלא \u0003סעודה דיומיה קא אכיל\u0004 \u0005[סעודת היום הוא אוכל]\u0006 ואם כן, במה ניכר שמשלים את הסעודה שהחסיר? \u0003אלא, מאי\u0004 \u0005[מה]\u0006 פירוש \u0003ישלים\u0004 שאמרו — \u0003ישלים במיני תרגימא,\u0004 שיוסיף מיני מעדנים מיוחדים שיהיו כהשלמה לסעודה שהחסיר. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אם השלים במיני תרגימא — יצא.\u0004","מסופר: \u0003שאל אפוטרופוס\u0004 (ממונה על נכסיו) \u0003של אגריפס המלך את ר' אליעזר: כגון אני, שאיני רגיל לאכול אלא סעודה אחת ביום\u0004 ולא יותר, \u0003מהו שאוכל סעודה אחת\u0004 בלבד בסוכה \u0003ואפטר? אמר לו\u0004 ר' אליעזר: \u0003בכל יום ויום אתה ממשיך\u0004 וטועם \u0003כמה\u0004 מיני \u0003פרפראות לכבוד עצמך,\u0004 כלומר: מתוך תיאבונך \u0003ועכשיו אי אתה ממשיך פרפרת אחת לכבוד קונך?\u0004","\u0003ועוד שאלו\u0004 אותו אפוטרופוס לר' אליעזר: \u0003כגון אני שיש לי שתי נשים, אחת בטבריא ואחת בציפורי, ויש לי שתי סוכות\u0004 בחג \u0003אחת בטבריא ואחת בציפורי, מהו שאצא מסוכה לסוכה ואפטר,\u0004 כלומר: המותר לי להיות מקצת החג בסוכה זו ומקצתה בסוכה זו? \u0003אמר לו\u0004 ר' אליעזר: \u0003לא! שאני אומר כל היוצא מסוכה לסוכה בטל מצותה של ראשונה.\u0004 שלדעתו חייב אדם לשבת בסוכה אחת כל שבעת הימים.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005];\u0006 \u0003ר' אליעזר אומר:\u0004"],["\u0003אין יוצאין מסוכה לסוכה,\u0004 אלא יושב בסוכה אחת כל החג כולו, \u0003ו\u0004אף \u0003אין עושים סוכה בחולו של מועד,\u0004 אם לא עשאה לפני החג. \u0003וחכמים אומרים: יוצאין מסוכה לסוכה, ועושין סוכה בחולו של מועד. ושוין\u0004 (ומסכימים) הכל, אף ר' אליעזר \u0003שאם נפלה\u0004 סוכתו העשויה מלפני החג, \u0003שחוזר ובונה בחולו של מועד.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר?\u0004 ומסבירים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"חג הסכת תעשה לך שבעת ימים\"\u0004 (דברים טז, יג), כלומר: \u0003עשה סוכה הראויה לשבעה\u0004 ימים. שאין סוכת מצוה אלא זו העשויה לשבעת ימים. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 כיצד מפרשים הם כתוב זה? לדעתם \u0003הכי קאמר רחמנא\u0004 \u0005[כך אמר,\u0006 התכוון \u0005הכתוב]:\u0006 אם לא עשית סוכה בערב החג — \u0003עשה סוכה בחג.\u0004 כלומר: חובת עשיית הסוכה עדיין קיימת כל שבעת ימי החג, שאם לא עשאה חייב לעשותה.","אמרנו: \u0003ושוין\u0004 חכמים ור' אליעזר בדעתם \u0003שאם נפלה\u0004 הסוכה שעשה לפני החג, \u0003שחוזר ובונה אותה בחולו של מועד.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 ומובן מאליו\u0005]\u0006 ומדוע איפוא לא יחזור ויבנה? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי לדעת ר' אליעזר \u0003האי אחריתי היא\u0004 \u0005[זו\u0006 שחזר ובנה \u0005אחרת היא]\u0006 \u0003ואינה\u0004 סוכה העשוייה \u0003לשבעה, קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף הוא מודה, שהיא נחשבת לאותה סוכה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005];\u0006 \u0003ר' אליעזר אומר: כשם שאין אדם יוצא ידי חובתו ביום טוב הראשון של חג בלולבו של חבירו, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולקחתם לכם ביום הראשון פרי עץ הדר כפת תמרים\"\u0004 (ויקרא כג, מ) ו\"לכם\" משמעו — \u0003משלכם\u0004 ולא של אחרים, \u0003כך אין אדם יוצא ידי חובתו בסוכתו של חבירו, דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"חג הסכת תעשה לך שבעת ימים\"\u0004 (דברים טז, יג), ו\"לך\" משמעו \u0003— משלך.\u0004","\u0003וחכמים אומרים: אף על פי שאמרו\u0004 ש\u0003אין אדם יוצא ידי חובתו ביום טוב הראשון בלולבו של חבירו, אבל יוצא\u0004 אדם \u0003ידי חובתו בסוכתו של חבירו, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כל האזרח בישראל ישבו בסכת\"\u0004 (ויקרא כג, מב), \u0003מלמד שכל ישראל ראויים לישב בסוכה אחת\u0004 ואם נחלק את שוויה של סוכה אחת בין כל ישראל, לא יהיה לאף אחד כדי פרוטה בה, ולכך אין להחשיבה כשל היחיד ואין זכות הישיבה בה נובעת אלא מתוך שהציבור משאילה לכל אחד לצורך קיום המצוה ונמצא שהוא מקיימה בשל הציבור. ומכאן שאין חובה שיקיים אדם מצות סוכה, בסוכה שהיא שלו דווקא.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003האי\u0004 \u0005[זה]\u0006 האמור בסוכות \u0003\"\u0004תעשה \u0003לך\"\u0004 שמשמע משלך, \u0003מאי דרשי ביה\u0004 \u0005[מה דורשים הם בו]?\u0006 ומשיבים: \u0003מיבעי ליה למעוטי\u0004 \u0005[צריכים הם\u0006 אותו \u0005כדי למעט]\u0006 סוכה \u0003גזולה,\u0004 שאם גזל סוכה אינו יוצא בה, \u0003אבל שאולה\u0004 הלא \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"כל האזרח\"\u0004, ללמד שיכול כל אחד מישראל, לקיים מצות סוכה בסוכה השאולה מן הציבור.","ושואלים: \u0003ו\u0004לשיטת \u0003ר' אליעזר, האי\u0004 \u0005[\u0006הריבוי \u0005הזה]\u0006 \u0003\"כל האזרח\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003מיבעיא ליה\u0004 \u0005[נצרך לו]\u0006 ללמד \u0003לגר שנתגייר בינתים\u0004 בתוך חג הסוכות \u0003וקטן שנתגדל בינתים\u0004 בתוך חג הסוכות, שחלה עליהם המצוה אף בתוך ימי הסוכות, והם שנתרבו במילים \"כל האזרח\". ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מנין להם הלכות אלה? ומשיבים: \u0003כיון\u0004 ש\u0003אמרו\u0004 חכמים: \u0003עושין סוכה בחולו של מועד,\u0004 ממילא \u0003לא איצטריך קרא\u0004 \u0005[הוצרך כתוב\u0006 מיוחד\u0005]\u0006 באלה, שהרי לשיטת חכמים מי שחלה עליו החובה עושה סוכה אפילו ליום אחד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בר' אלעאי שהלך\u0004 בערב סוכות כדי \u0003להקביל פני ר' אליעזר רבו בלוד ברגל\u0004 (בחג הראשון). \u0003אמר לו: אלעאי! אינך משובתי הרגל.\u0004 כלומר: לא קיימת מצות הרגל. \u0003שהיה ר' אליעזר אומר: משבח אני את העצלנין,\u0004 שאף על פי שכן דרכם בכל ימות השנה, מכל מקום יש לשבחם במיוחד על \u0003שאין יוצאין מבתיהן ברגל, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושמחת אתה וביתך\"\u0004 (דברים יד, כו) ו\"ביתו\" זו אשתו. ואם יוצא מביתו נמצא שאינו יכול לשמח אשתו כראוי.","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יצחק: מניין שחייב אדם להקביל פני רבו ברגל, שנאמר\u0004 ששאל בעל השונמית אותה: \u0003\"מדוע את הלכת אליו היום לא חדש ולא שבת\"\u0004 (מלכים ב' ד, כג), ו\u0003מכלל\u0004 הדברים אתה למד ש\u0003בחדש ו\u0004ב\u0003שבת מיחייב איניש לאקבולי אפיה רביה\u0004 \u0005[חייב אדם לקבל פני רבו]!\u0006 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שחייב אדם ללכת — \u0003דאזיל ואתי ביומיה\u0004 \u0005[שהולך ובא ביומו],\u0006 שבלילה יכול לשמח את אשתו, \u0003הא\u0004 \u0005[זה]\u0006 שאמרו שאין ללכת — \u0003דאזיל ולא אתי ביומיה\u0004 \u0005[שהולך ואינו חוזר ביומו],\u0006 שמותיר את אשתו לבד בלילה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בר' אליעזר ששבת בגליל העליון בסוכתו של יוחנן בר' אלעאי בקיסרי ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שלא בקיסרי היה הדבר אלא \u0003בקיסריון, והגיע חמה לסוכה\u0004 והיה קשה לשבת בה מפני החום. \u0003אמר לו\u0004 יוחנן: \u0003מהו שאפרוש עליה סדין,\u0004 המותר הדבר, שאינו אלא כתוספת על אהל ארעי בשבת או שיש בכך איסור? התעלם ר' אליעזר מן השאלה ו\u0003אמר לו: אין לך כל שבט ושבט מישראל שלא העמיד ממנו שופט.\u0004","בינתיים \u0003הגיע חמה לחצי סוכה, אמר לו\u0004 שוב בעל הבית: \u0003מהו שאפרוש עליה סדין?\u0004 המשיך ר' אליעזר להתעלם משאלותיו ו\u0003אמר לו\u0004 בענין אחר: \u0003אין לך כל שבט ושבט מישראל שלא יצאו ממנו נביאים,\u0004 ו\u0003שבט יהודה ובנימין\u0004 מיוחדים שהם \u0003העמידו מלכים על פי נביאים,\u0004 ששאול ודוד הומלכו על ידי הנביא שמואל. תוך מהלך הדברים \u0003הגיע חמה\u0004 כבר \u0003למרגלותיו של ר' אליעזר, נטל יוחנן סדין ופירש עליה,\u0004 על הסוכה, \u0003הפשיל ר' אליעזר טליתו לאחוריו ויצא,\u0004 מפני שלא רצה להתיר את הדבר. ומעירים: \u0003לא מפני שהפליגו בדברים,\u0004 כלומר: לא מפני שרצה להשתמט ממנו כדי שלא יצטרך להודות שאינו יודע, \u0003אלא מפני שלא אמר\u0004 ר' אליעזר \u0003דבר שלא שמע מפי רבו לעולם.\u0004","ולענייננו שואלים: \u0003והיכי עביד הכי\u0004 \u0005[איך עשה\u0006 ר' אליעזר \u0005כך]\u0006 ששבת מחוץ לעירו לוד (ראה סנהדרין לב, ב) בחג? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אליעזר\u0004 עצמו: \u0003אין יוצאין מסוכה לסוכה!\u0004 ומשיבים: \u0003רגל אחר הואי\u0004 \u0005[חג אחר היה זה]\u0006 ולא חג הסוכות, וישבו בסוכה מחמת האויר שבה.","ושואלים מצד אחר: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אליעזר: משבח אני את העצלנין שאין יוצאין מבתיהן ברגל,\u0004 ולא נתפרש איזה רגל, הרי שאף ברגל אחר אין ראוי לצאת! ומשיבים: לא היה זה כלל ברגל, אלא \u0003שבת\u0004 סתם \u0003הואי\u0004 \u0005[היתה זו]\u0006 והשאלה היתה רק משום חשש למלאכת \"בונה\" בשבת.","ושואלים: אם כן, \u0003ותיפשוט ליה מדידיה\u0004 \u0005[ותפתור לו\u0006 את הבעיה אם מותר או לא \u0005מ\u0006שיטת \u0005עצמו];\u0006 \u0003דתנן\u0004 \u0005[\u0006שכן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003פקק החלון\u0004 שהוא כעין תריס שנמצא על ארובה שבגג, \u0003ר' אליעזר אומר: בזמן שקשור\u0004 התריס בקיר או בגג \u0003ותלוי\u0004 שם תמיד — \u0003פוקקין בו,\u0004 כיון שמותקן לכך ואין בכך משום מלאכת \"בונה\", \u0003ואם לאו — אין פוקקין בו. וחכמים אומרים: בין כך ובין כך פוקקין\u0004 שהרי מותקן הוא לצורך זה."],["\u0003התם\u0004 \u0005[שם]\u0006 בפקק במעשה הסתימה \u0003הוא\u0004 ש\u0003מבטל\u0004 את הפקק לחלון ולכן הוא נחשב כחלק מן הבנין, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 שהוא \u0003לא מבטל\u0004 את הסדין לגבי הסוכה, שהרי סוף סוף ינטל מן הסוכה, ואינו נחשב כחלק ממנה — \u0003לא,\u0004 אין הדבר מותר.","כיון שהוזכרו כאן דרכי הנהגתו של ר' אליעזר, מביאים מעשה נוסף בדומה לזה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בר' אליעזר ששבת בגליל העליון, ושאלוהו שלשים הלכות בהלכות סוכה,\u0004 על \u0003שתים עשרה\u0004 מהן \u0003אמר להם: שמעתי\u0004 תשובה מרבותי ואמר מה ששמע, ועל \u0003שמונה עשרה\u0004 האחרות \u0003אמר להם: לא שמעתי. ר' יוסי בר' יהודה אומר: חילוף הדברים\u0004 היה; על \u0003שמונה עשר אמר להם: שמעתי\u0004 תשובה, ועל \u0003שתים עשרה אמר להם: לא שמעתי.\u0004","\u0003אמרו לו\u0004 בתמיהה: \u0003כל דבריך אינן אלא מפי השמועה!\u0004 ואינך אומר דבר משל עצמך?! \u0003אמר להם: הזקקתוני\u0004 עכשיו \u0003לומר דבר שלא שמעתי מפי רבותי\u0004 שאני צריך לספר לכם על מידותי והדברים שאני נוהג בהם; \u0003מימי לא קדמני אדם בבית המדרש\u0004 ואני בא תמיד ראשון, \u0003ולא ישנתי בבית המדרש לא שינת קבע ולא שינת עראי, ולא הנחתי אדם בבית המדרש ויצאתי\u0004 אלא נשארתי תמיד אחרון, \u0003ולא שחתי שיחת חולין,\u0004 אלא רק בדברים נחוצים או בדברי תורה, \u0003ולא אמרתי דבר שלא שמעתי מפי רבי מעולם.\u0004 ולכן לפי דרכו לא השיב על אותן שאלות שלא שמע תשובתן מפי רבו. כיון שהזכרנו מידותיו של ר' אליעזר מספרים בשבחם של חכמים אחרים, בדומה לאלה של ר' אליעזר.","\u0003אמרו עליו על רבן יוחנן בן זכאי\u0004 רבו של ר' אליעזר: \u0003מימיו לא שח שיחת חולין, ולא הלך ארבע אמות בלא\u0004 שעסק ב\u0003תורה ובלא\u0004 להניח \u0003תפילין\u0004 על ראשו, \u0003ולא קדמו אדם בבית המדרש, ולא ישן בבית המדרש לא שינת קבע ולא שינת עראי, ולא הרהר\u0004 בדברי תורה כשהיה מצוי \u0003במבואות המטונפות\u0004 שיש בזיון לתורה כשמהרהר שם בתורה, \u0003ולא הניח אדם\u0004 לבד \u0003בבית המדרש ויצא, ולא מצאו אדם יושב ודומם\u0004 ואינו עושה דבר \u0003אלא יושב ושונה, ולא פתח אדם\u0004 אחר את ה\u0003דלת לתלמידיו, אלא הוא בעצמו\u0004 ולא חשש לכבודו, אלא שמח לכבדם בכך, \u0003ולא אמר דבר שלא שמע מפי רבו לעולם, ולא אמר\u0004 לתלמידים: \u0003הגיע עת לעמוד מבית המדרש, חוץ מערבי פסחים,\u0004 שיש להזדרז להקריב קרבן פסח או לסדר את הפסח, וכן ב\u0003ערבי יום הכפורים,\u0004 שמצוה להרבות באכילה ושתיה ביום זה. לפני חשיכה \u0003וכן היה ר' אליעזר תלמידו נוהג אחריו.\u0004","ועוד מסופר בשבחם של חכמים; \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שמונים תלמידים היו לו להלל הזקן; שלשים מהם ראויים\u0004 היו \u0003שתשרה עליהן שכינה כמשה רבנו, ושלשים מהן ראויים\u0004 היו \u0003שתעמוד להם חמה כיהושע בן נון, עשרים בינונים,\u0004 בין זה לזה. \u0003גדול שבכולן\u0004 שבכל התלמידים היה \u0003יונתן בן עוזיאל, קטן שבכולן\u0004 בשנים היה \u0003רבן יוחנן בן זכאי.\u0004","מסופר: \u0003אמרו עליו על רבן יוחנן בן זכאי שלא הניח מקרא ומשנה, גמרא\u0004 (דקדוקי המשנה והסברתה) \u0003הלכות ואגדות, דקדוקי תורה ודקדוקי סופרים,\u0004 דרשות התורה בדבר \u0003קלים וחמורים וגזירות שוות,\u0004 חשבונות \u0003התקופות\u0004 (של לוח השנה) \u0003וגימטריאות\u0004 וכן דברים שבחכמת הנסתר: \u0003ושיחת מלאכי שרת, ושיחת שדים, ושיחת דקלים. משלות כובסין\u0004 שהם משלים עממיים שאפשר להשתמש בהם להסברת דברי תורה, וכן \u0003משלות שועלים,\u0004 ובכלל: \u0003דבר גדול ודבר וקטן.\u0004","ומסבירים: \u0003דבר גדול\u0004 — סודות \u0003מעשה מרכבה\u0004 (של הנהגת העולם העליונה), \u0003דבר קטן —\u0004 כגון ההלכות שאחר דורות נוסחו בתוך \u0003הויות\u0004 \u0005[בעיות]\u0006 של \u0003אביי ורבא. לקיים מה שנאמר: \"להנחיל אהבי יש ואצרתיהם אמלא\"\u0004 (משלי ח, כא) שהיה רבן יוחנן מלא וגדוש בכל דברי תורה וחכמה. ואם \u0003קטן שבכולן כך\u0004 היתה מדרגתו, \u0003גדול שבכולן על אחת כמה וכמה.\u0004 וכדי להסביר גדולתו מספרים: \u0003אמרו עליו על יונתן בן עוזיאל\u0004 גדול התלמידים, \u0003בשעה שיושב ועוסק בתורה\u0004 היתה קדושתו רבה כל כך שהיתה אש מלהטת סביבו עד ש\u0003כל עוף שפורח עליו מיד נשרף.\u0004","\u0003מי שהיה ראשו ורובו בסוכה ושלחנו\u0004 מצוי \u0003בתוך הבית\u0004 — \u0003בית שמאי פוסלין ובית הלל מכשירין. אמרו להם בית הלל לבית שמאי:\u0004 וכי \u0003לא כך היה מעשה; שהלכו זקני בית שמאי וזקני בית הלל לבקר את ר' יוחנן בן החורנית, ומצאוהו שהיה יושב ראשו ורובו בסוכה ושולחנו בתוך הבית, ולא אמרו לו דבר.\u0004 הרי שאף זקני בית שמאי הסכימו שמותר כן. \u0003אמר להם בית שמאי: משם\u0004 מביאים אתם \u0003ראיה?!\u0004 לא כך היה הדבר, אלא \u0003אף הם אמרו לו\u0004 כולם כאחד: \u0003אם כן היית נוהג, לא קיימת מצות סוכה מימיך.\u0004","ועוד הלכה אחרת בסוכה: \u0003נשים ועבדים וקטנים פטורין מן הסוכה. קטן שאינו צריך\u0004 עוד \u0003לאמו\u0004 ויכול להיות לבדו — \u0003חייב בסוכה. מעשה וילדה כלתו של שמאי הזקן\u0004 סמוך לסוכות \u0003ופיחת\u0004 (הוריד) שמאי \u0003את המעזיבה\u0004 (כיסוי הטיט שעל הגג) והשאיר שם רק את הקורות \u0003וסיכך על גבי המטה בשביל\u0004 ה\u0003קטן\u0004 שנולד.","על ההלכה ששנינו שנשים ועבדים וקטנים פטורים מן הסוכה, שואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]?\u0006 ומשיבים, \u0003דתנו רבנן\u0004 \u0005[ששנו\u0006 חכמים\u0005]:\u0006 נאמר: \"כל האזרח בישראל ישבו בסכת\" \u0005(ויקרא כג, מב)\u0006, ו\u0003\"אזרח\" — זה אזרח,\u0004 ומשמעו: כל אחד מבני ישראל, \u0003\"האזרח\"\u0004 בהדגשה שהוא האזרח המיוחד, משמעו — גברים בלבד, ואם כן בא \u0003להוציא את הנשים. \"כל\u0004 האזרח\" לשון \"כל\" — \u0003לרבות את הקטנים\u0004 היכולים לקיים מצוה זו, באה. ומבררים עתה את דברי הברייתא הזו.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003\"האזרח\" — להוציא את הנשים. למימרא\u0004 \u0005[האם לומר]\u0006 כי מובן מכאן שהמלה \u0003\"אזרח\"\u0004 בלבד \u0003בין נשים בין גברי משמע\u0004 \u0005[גברים משמעו]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 בענין יום הכיפורים; נאמר: \"בחודש השביעי בעשור לחודש תענו את נפשותיכם וכל מלאכה לא תעשו האזרח והגר הגר בתוככם\" (ויקרא טז, כט), ושנינו: \u0003\"האזרח\" — לרבות את הנשים האזרחיות,\u0004 כלומר: כל בנות ישראל, שאף הן \u0003חייבות בעינוי.\u0004 ומשם משמע להיפך, שהצורה \"האזרח\" (בתוספת \"ה\") לריבוי ולהוספה היא באה, \u0003אלמא\u0004 \u0005[מכאן]\u0006 שהמלה \u0003\"אזרח\"\u0004 בלבד ללא תוספת שהיא — \u0003גברי משמע\u0004 \u0005[גברים\u0006 בלבד \u0005משמעו]!\u0006 \u0003אמר רבה:\u0004 עיקרם של הדברים \u0003הלכתא נינהו\u0004 \u0005[הלכות\u0006 למשה מסיני \u0005הן]\u0006 \u0003ואסמכינהו רבנן אקראי\u0004 \u0005[והסמיכון חכמים על הכתובים]\u0006 לזכרון בלבד, ולכן אין לתמוה שהמדרשים חלוקים זה על זה.","ושואלים: \u0003הי קרא והי הלכתא\u0004 \u0005[איפה הוא הכתוב ואיפה היא ההלכה]?\u0006 כלומר: באיזה ענין אומרים אנו שהסבר זה נלמד מן הכתוב ממש, והיכן אומרים אנו שאין זה אלא הלכה הנסמכת על הכתוב? \u0003ותו\u0004 \u0005[ועוד]:\u0006 \u0003קרא\u0004 \u0005[כתוב]\u0006 \u0003למה לי והלכתא\u0004 \u0005[והלכה]\u0006 \u0003למה לי,\u0004 כלומר: לשם מה יש להביא את שניהם כדי ללמדני הלכות אלה? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003סוכה מצות עשה שהזמן גרמא\u0004 היא, ולפי הכלל המקובל כי \u0003כל מצות עשה שהזמן גרמא נשים פטורות,\u0004 אם כן אין צורך עוד בלימוד מיוחד כדי לפטור את הנשים ממצות סוכה.","וכן בחיובן בצום \u0003יום הכפורים\u0004 אין צורך לדרשה זו, כי מדברי \u0003רב יהודה אמר רב נפקא\u0004 \u0005[יוצא\u0006 הדבר\u0005],\u0006 שנשים חייבות. ש\u0003אמר רב יהודה אמר רב, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"איש או אשה\u0004 אשר יעשו מכל חטאת האדם למעול מעל בה' ואשמה הנפש ההיא\u0003\"\u0004 (במדבר ה, ו) —"],["\u0003השוה הכתוב אשה לאיש לכל עונשין שבתורה,\u0004 שלגבי עונשים ומצוות \"לא תעשה\", נשים ואנשים שוים, ומאחר ובמצוות יום הכיפורים יש גם \"לא תעשה\" וגם עונש (כרת), אם כן אף שהן בכלל מצוות עשה שהזמן גרמא, מכל מקום יש לחייב בהן את הנשים, ואם כן מה צורך בלימוד נוסף? \u0003אמר אביי: לעולם סוכה הלכתא\u0004 \u0005[הלכה]\u0006 למשה מסיני היא, ובכל זאת \u0003איצטריך\u0004 \u0005[הוצרכה]\u0006 הלכה זו. כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003\"תשבו\"\u0004 — הרי זה בא לומר שישיבתכם בסוכה תהא \u0003כעין תדורו,\u0004 ו\u0003מה דירה — איש ואשתו, אף סוכה\u0004 חייבים להיות \u0003איש ואשתו, קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין על הנשים חובה לשבת בסוכה.","\u0003רבא אמר\u0004 טעם אחר: \u0003איצטריך\u0004 \u0005[צריך],\u0006 \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003יליף\u0004 \u0005[ילמד]\u0006 גזירה שווה \u0003\"חמשה עשר\" \"חמשה עשר\" מחג המצות\u0004 (פסח); \u0003מה להלן\u0004 באכילת מצה בפסח \u0003נשים חייבות\u0004 אף שהיא מצות עשה שהזמן גרמא, \u0003אף כאן\u0004 במצות סוכה \u0003נשים חייבות — לכך קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שפטורות.","ושואלים: \u0003והשתא דאמרת\u0004 \u0005[ועכשיו שאומר אתה]\u0006 שפטור נשים ממצות \u0003סוכה הלכתא\u0004 \u0005[הלכה]\u0006 למשה מסיני היא, אם כן \u0003קרא\u0004 \u0005[הכתוב] \"\u0006האזרח\" \u0003למה לי\u0004 אותו? ומשיבים: כתוב זה בא בעצם כדי \u0003לרבות את הגרים.\u0004 כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003\"האזרח בישראל\"\u0004 ש\u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 הכוונה — \u0003ולא את הגרים,\u0004 שאינם אזרחי הארץ, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 על ידי תוספת זו, שאף הגרים חייבים בכך.","ולשאלה השניה ששאלנו בדבר \u0003יום הכפורים\u0004 שמדברי \u0003רב יהודה אמר רב נפקא\u0004 \u0005[יוצא\u0006 הדבר\u0005]\u0006 שהן חייבות בצום כבכל מצוות \"לא תעשה\" ומצוות שנאמר בהם עונש האמורות בתורה, משיבים: \u0003לא נצרכא אלא לתוספת עינוי,\u0004 שמוסיפים מערב יום הכיפורים מקצת זמן להתענות בו. \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ומיעט רחמנא\u0004 \u0005[ומיעטה התורה]\u0006 \u0003לתוספת עינוי מעונש ואזהרה,\u0004 שהרי מי שאינו מתענה בתוספת זו אינו עובר על מצות \"לא תעשה\" ואף אינו נענש על כך, שהרי אין מצות \"לא תעשה\" מפורשת שלא לאכול בזמן התוספת מחול על הקודש, ואם כן \u0003לא נתחייבו\u0004 \u0005[שלא יתחייבו]\u0006 \u0003נשים כלל\u0004 מלכתחילה לשמור תוספת זו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכיוון שחייבות בעיקר, חייבות אף בתוספת.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: נאמר \"כל האזרח\" ו\u0003\"כל\"\u0004 זה — \u0003לרבות את הקטנים\u0004 למצות סוכה הוא בא. ותוהים: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003נשים ועבדים וקטנים פטורין מן הסוכה!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 \u0003כאן\u0004 שאמרנו לרבות את הקטנים — מדובר \u0003בקטן שהגיע לחינוך\u0004 שהגיע לגיל כזה שחייבים ההורים לחנכו ולהרגילו במצוות, \u0003כאן\u0004 שפטורים — מדובר \u0003בקטן ש\u0004עדיין \u0003לא הגיע לחינוך.\u0004 ותוהים: הרי \u0003בקטן שהגיע לחינוך\u0004 כל עיקרו של החיוב \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003הוא\u0004 ומן התורה חייב במצוות רק מי שהגיע לבגרות! ומשיבים: מה שאמרנו שקטן חייב בסוכה הוא אכן רק \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 משום חינוך, \u0003וקרא\u0004 \u0005[והפסוק]\u0006 שהבאנו כראיה — \u0003אסמכתא בעלמא\u0004 \u0005[לסמך בלבד]\u0006 \u0003הוא,\u0004 לרמז על כך, אבל באמת אינו חיוב מן התורה.","שנינו במשנה כי \u0003קטן שאינו צריך לאמו\u0004 — חייב בסוכה. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא\u0006 בדיוק\u0005]\u0006 \u0003קטן שאינו צריך לאמו? אמרי דבי\u0004 \u0005[אמרו\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: כל\u0004 תינוק \u0003שנפנה\u0004 לעשות צרכיו \u0003ואין אמו מקנחתו\u0004 \u0005[מנגבת אותו]\u0006 ויכול לקנח את עצמו לבדו, הריהו נחשב כגדול לענין זה. \u0003ר' שמעון אומר: כל שנעור משנתו ואינו קורא \"אמא, אמא\"!\u0004 ותוהים: אפילו ילדים \u0003גדולים נמי\u0004 \u0005[גם כן]\u0006 \u0003קרו\u0004 \u0005[קוראים]\u0006 \u0003\"אמא,\u0004 אמא \u0003\"\u0004בקומם, ומה הוא איפוא הגבול? ומשיבים: לא, אין להבין כפי שאמרנו, \u0003אלא\u0004 כך יש לומר: \u0003כל שנעור ואינו קורא\u0004 וחוזר וקורא \u0003\"אמא, אמא\"\u0004 עד שתבוא אמו כדרך הקטן, אלא ילד גדול קורא פעם אחת ואם אין אמו באה, הריהו קם ודואג לעצמו.","מסופר במשנה \u0003מעשה\u0004 שכאשר \u0003ילדה כלתו\u0004 של שמאי הזקן, סיכך שמאי חלק מן הבית עבור התינוק שנולד. ותוהים: וכי מביאים במשנה \u0003מעשה לסתור\u0004 את ההלכה הקודמת בה, והרי נאמר מקודם כי הקטנים הצריכים לאמם פטורים ממצות סוכה? ומשיבים: \u0003חסורי מחסרא\u0004 \u0005[חסרה\u0006 משנתנו\u0005]\u0006 \u0003והכי קתני\u0004 \u0005[וכך היה\u0006 צריך \u0005לשנות]:\u0006 \u0003ושמאי מחמיר\u0004 אפילו בקטני קטנים, \u0003ומעשה נמי\u0004 \u0005[גם כן]\u0006 \u0003וילדה כלתו של שמאי הזקן ופיחת\u0004 (הוריד) שמאי \u0003את המעזיבה\u0004 (כיסוי הטיט שעל הגג) והשאיר שם רק את הקורות \u0003וסיכך על\u0004 גבי \u0003המטה בשביל\u0004 ה\u0003קטן\u0004 שנולד.","\u0003כל שבעת הימים\u0004 של חג הסוכות \u0003אדם עושה סוכתו קבע,\u0004 שתהא לו כבית דירתו העיקרי \u0003וביתו\u0004 כדירת \u0003עראי.\u0004 אם \u0003ירדו גשמים\u0004 בסוכה \u0003מאימתי מותר לפנות\u0004 ממנה — \u0003משתסרח המקפה\u0004 (תבשיל קפוי, שאינו רך ואינו מוצק), כלומר: משירדו גשמים עד כדי כך שהם מקלקלים את התבשיל הנאכל בסוכה. \u0003משלו\u0004 חכמים \u0003משל למה הדבר\u0004 הזה שנפטר אדם אז מן הסוכה \u0003דומה\u0004 — \u0003לעבד שבא למזוג כוס לרבו, ושפך לו קיתון על פניו\u0004 להראות לו שאינו רוצה בשימושו, ואף כאן הרי זה סימן שאין הקדוש ברוך הוא רוצה באותו אדם שיקיים מצות סוכה.","\u0003גמרא\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל שבעת הימים\u0004 של חג הסוכות \u0003אדם עושה סוכתו קבע וביתו עראי, כיצד\u0004 נוהג? \u0003היו לו כלים נאים — מעלן לסוכה\u0004 שבדרך כלל עשו אותה על הגג, היו לו \u0003מצעות נאות — מעלן לסוכה, אוכל ושותה ומטייל,\u0004 כלומר: נח לו \u0003בסוכה.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]?\u0006 ומסבירים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 מה שנאמר \u0003\"תשבו\"\u0004 — הרי זה בא לומר שישיבתכם בסוכה תהא \u0003כעין תדורו, מכאן אמרו: כל שבעת הימים, עושה אדם סוכתו קבע וביתו עראי. כיצד? היו לו כלים נאים — מעלן לסוכה, מצעות נאות — מעלן לסוכה, אוכל ושותה ומטייל בסוכה ומשנן בסוכה.\u0004","על האמור כי משנן בסוכה תוהים: \u0003איני\u0004 \u0005[כן הוא]?!\u0006 \u0003והא אמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: מקרא ומתנא\u0004 \u0005[לקרות\u0006 בתורה \u0005ולשנות\u0006 במשנה\u0005]\u0006 \u0003במטללתא\u0004 \u0005[בסוכה],\u0006 אבל \u0003ותנוי\u0004 \u0005[ועיון\u0006 במשנה\u0005]\u0006 צריך להיות \u0003בר ממטללתא\u0004 \u0005[מחוץ לסוכה].\u0006 משמע שאין אדם משנן בסוכה! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שמשנן בסוכה — הרי זה \u0003במגרס\u0004 \u0005[בגרסה,\u0006 לצורך בקיאות ושינון בלבד\u0005],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמשנן במקום שנוח לו — \u0003בעיוני\u0004 \u0005[בעיון\u0006 בדבר\u0005],\u0006 שצריך לשהות במקום נוח שאין בו הפרעה, ויוכל לעיין כראוי."],["\u0003כי הא\u0004 \u0005[כמו זו]\u0006 של \u0003רבא ורמי בר חמא, כי הוו קיימי מקמיה\u0004 \u0005[כאשר היו קמים מלפני]\u0006 \u0003רב חסדא\u0004 אחרי שלימדם הלכה, \u0003מרהטי בגמרא בהדי הדדי\u0004 \u0005[היו עוברים במהירות בשמועה,\u0006 בלימוד \u0005יחד]\u0006 כדי לחזור על לימודם, \u0003והדר מעייני בסברא\u0004 \u0005[[אחר כך היו שבים ומעיינים בסברה\u0006 שבדבר\u0005].\u0006 הרי שאף בתלמוד יש לחלק בין לימוד בקיאות ולימוד לעיון.","לענין דירה בסוכה \u0003אמר רבא: מאני משתיא\u0004 \u0005[כלי שתיה]\u0006 כגון כוסות, שהם כרגיל נקיות — מכניסים \u0003במטללתא\u0004 \u0005[בסוכה]\u0006 עצמה. \u0003מאני מיכלא\u0004 \u0005[כלי אוכל]\u0006 לאחר שאכלו בהם — צריך להוציאם \u0003בר ממטללתא\u0004 \u0005[מחוץ לסוכה].\u0006 אולם \u0003חצבא ושחיל\u0004 \u0005[כד חרס וכד עץ]\u0006 העשויים לשאיבת מים ואינם נאים — \u0003בר ממטללתא\u0004 \u0005[מחוץ לסוכה].\u0006 \u0003ושרגא\u0004 \u0005[ונר]\u0006 — \u0003במטללתא\u0004 \u0005[ב\u0006תוך \u0005הסוכה],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003בר ממטללתא\u0004 \u0005[מחוץ לסוכה].\u0006 ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין חלוקות]\u0006 הלשונות; אלא \u0003הא\u0004 \u0005[זו]\u0006 שאמרנו בתוך הסוכה, מדובר \u0003בסוכה גדולה\u0004 שאין הנר וריחו מפריעים, \u0003הא\u0004 \u0005[זו]\u0006 שאמרנו שמקום הנר הוא מחוץ לסוכה, מדובר \u0003בסוכה קטנה,\u0004 שראוי שיהא הנר מבחוץ כדי שלא יסריחנה.","שנינו במשנה שאם \u0003ירדו גשמים\u0004 בסוכה עד כדי שתסרח המקפה — מותר לצאת ממנה. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: \u0003משתסרח המקפא של גריסין,\u0004 ובה משערים.","מסופר: \u0003אביי הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003רב יוסף במטללתא\u0004 \u0005[בסוכה],\u0006 \u0003נשב זיקא וקא מייתי ציבותא\u0004 \u0005[נשבה הרוח והביאה קיסמים דקים]\u0006 מן הסכך ונשרו על המאכל, \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב יוסף: פנו לי\u0004 את \u0003מאני מהכא\u0004 \u0005[כלי מכאן],\u0006 שאינני יכול לאכול כאן, אלא אצא ואוכל בביתי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003משתסרח המקפה,\u0004 ובודאי לא הגיעו הדברים עד כדי כך! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לדידי\u0004 \u0005[לי],\u0006 \u0003כיון דאנינא דעתאי\u0004 \u0005[שאנינה,\u0006 מפונקת, \u0005דעתי] —\u0006 \u0003כמי\u0004 \u0005[כאילו]\u0006 \u0003שתסרח המקפה דמי\u0004 \u0005[נחשב]\u0006 \u0003לי\u0004 אפילו בלכלוך מעט, ולכן אינני צריך לשבת שם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003היה אוכל בסוכה וירדו גשמים וירד\u0004 מן הסוכה ואכל בביתו — \u0003אין\u0004 אנו \u0003מטריחין אותו לעלות\u0004 חזרה לסוכה מיד כשפסקו הגשמים, \u0003עד שיגמור סעודתו.\u0004 וכן אם \u0003היה ישן\u0004 בסוכה \u0003תחת הסוכה\u0004 (הסכך) \u0003וירדו גשמים וירד\u0004 לישון בביתו — \u0003אין מטריחין אותו לעלות\u0004 חזרה לסוכה כדי לסיים את שנתו, \u0003עד שיאור.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים כיצד היתה הגירסה המדוייקת בברייתא זו, האם שנינו \u0003\"עד שיעור\"\u0004 ב\"ע\", כלומר: עד שיתעורר משנתו ואפילו היה זה באמצע הלילה, \u0003או עד שיאור\u0004 (יאיר) היום שלמחרת בעלות השחר? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר, ממה ששנינו במקום אחר: \u0003עד שיאור ויעלה עמוד השחר.\u0004 ויש לתמוה על הלשון: \u0003תרתי\u0004 \u0005[שנים]?!\u0006 כלומר: לכאורה הם שני מושגים סותרים, שהרי לשון \"יאור\" מורה על שהאיר המזרח ואילו \"יעלה עמוד השחר\" משמע קודם לכן! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 שכך יש לתקן: \u0003עד שיעור\u0004 \u0005[יתעורר]\u0006 \u0003ויעלה עמוד השחר.\u0004 ואם כן שתי הגירסות נכונות, כלומר: אין מעוררים אותו בתוך שנתו כדי שיחזור לישון בסוכה גם אם כבר עלה עמוד השחר, וגם אם מתעורר מעצמו באמצע הלילה אינו מחוייב לחזור לישון בסוכה עד שיעלה עמוד השחר.","שנינו במשנה: \u0003משל למה הדבר דומה,\u0004 לעבד המוזג לרבו כוס ושפך לו קיתון על פניו. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים ביחס לפירושו של משל זה: \u0003מי שפך למי?\u0004 לפי שלשון המשנה משתמעת לשני צדדים. ומשיבים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 \u0003דתניא\u0004 \u0005[\u0006ממה \u0005ששנינו\u0006 בברייתא\u0005]\u0006 בהרחבה: \u0003שפך לו רבו קיתון על פניו, ואמר לו: אי אפשי\u0004 \u0005[אינני רוצה]\u0006 \u0003בשמושך\u0004 שאתה משמש אותי.","כיון שהוזכר כאן ענין גשמים בחג שהם כסימן נזיפה משמים, מביאים כמה עניינים דומים; \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בזמן שהחמה לוקה — סימן רע\u0004 הוא \u0003לכל העולם כולו, משל למה הדבר דומה — למלך בשר ודם שעשה סעודה לעבדיו והניח פנס לפניהם, כעס עליהם ואמר לעבדו: טול פנס מלפניהם והושיבם בחושך:\u0004 כך ליקוי חמה (\"פנסו\" של העולם) הוא כסימן נזיפה לעולם.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005];\u0006 \u0003ר' מאיר אומר: כל זמן שמאורות\u0004 (השמש והירח) \u0003לוקין\u0004 — הרי זה \u0003סימן רע לשונאיהם של ישראל\u0004 (כלומר: לישראל, בלשון סגי נהור), \u0003מפני שמלומדין במכותיהן.\u0004 שכיון שרגילים ישראל ללקות ולסבול הרבה יסורים, מן הסתם כל מכה הבאה על העולם, כדי להלקות בה את ישראל היא באה. \u0003משל\u0004 הדבר \u0003לסופר\u0004 (למלמד תינוקות) \u0003שבא לבית הספר ורצועה בידו, מי\u0004 מן הילדים \u0003דואג — מי שרגיל ללקות בכל יום ויום הוא דואג.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת: \u0003בזמן שהחמה לוקה\u0004 — \u0003סימן רע\u0004 הוא \u0003לגויים, לבנה לוקה — סימן רע\u0004 הוא \u0003לשונאיהן של ישראל\u0004 (כלומר: לישראל), \u0003מפני שישראל מונין\u0004 את שנתם בעיקר \u0003ללבנה, וגויים לחמה. לוקה\u0004 הלבנה \u0003ב\u0004צד \u0003מזרח\u0004 — הרי זה \u0003סימן רע ליושבי\u0004 ארצות ה\u0003מזרח,\u0004 אם לקתה \u0003ב\u0004צד \u0003מערב\u0004 — הרי זה \u0003סימן רע ליושבי\u0004 ארצות ה\u0003מערב.\u0004 לקתה \u0003באמצע הרקיע\u0004 — הרי זה \u0003סימן רע לכל העולם כולו.\u0004","אם בשעת הליקוי \u0003פניו\u0004 של החמה \u0003דומין לדם\u0004 שצבעם אדום — הרי זה סימן כי \u0003חרב\u0004 (מלחמה) \u0003בא לעולם.\u0004 אם דומה הליקוי \u0003לשק\u0004 (העשוי משיער העז וצבעו נוטה לשחור) — סימן הוא ש\u0003חיצי רעב באין לעולם,\u0004 שהרעב משחיר פניהם של האנשים. דומה גם \u0003לזו\u0004 לדם, וגם \u0003לזו\u0004 לשק — הרי זה סימן ש\u0003חרב וחיצי רעב באין לעולם\u0004 יחד. \u0003לקה בכניסתו,\u0004 כלומר: סמוך לעלייתו — סימן הוא לכך שה\u0003פורענות שוהה לבוא\u0004 ולא תבוא מיד. לקתה החמה \u0003ביציאתו\u0004 סמוך לסוף היום — סימן הוא לכך שהפורענות \u0003ממהרת לבוא. ויש אומרים חילוף הדברים.\u0004 שליקוי בכניסתו מרמז שמיד באה הפורענות ולא תמתין וביציאתו הריהו מרמז כי שוהה היא לבוא.","ועוד אמרו: \u0003ואין לך כל אומה ואומה שלוקה, שאין אלהיה לוקה עמה, שנאמר: \"ובכל אלהי מצרים אעשה שפטים אני ה'\"\u0004 (שמות יב, יב). ומוסיפים: \u0003ובזמן שישראל עושין רצונו של מקום\u0004 הרי \u0003אין\u0004 הם \u0003מתיראין מכל אלו,\u0004 מהסימנים של ליקויי המאורות וכיוצא בהם. \u0003שנאמר: \"כה אמר ה' אל דרך הגוים אל תלמדו ומאתות השמים אל תחתו כי יחתו הגוים מהמה\"\u0004 (ירמיה י, ב) — \u0003גויים יחתו, ואין ישראל יחתו.\u0004 ומשמעות הפסוק לפי זה היא, \u0003שאם \"אל דרך הגויים אל תלמדו\", שלא תעשו כמעשיהם — הרי \"מאותות השמים אל תחתו\", שאין לכם לחשוש מכך.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בשביל ארבעה דברים חמה לוקה: על אב בית דין שמת ואינו נספד כהלכה\u0004 וכאילו סופדים לו משמים, \u0003ועל נערה מאורסה שצעקה בעיר\u0004 על שאנסו אותה \u0003ואין מושיע לה, ועל משכב זכור, ועל שני אחין שנשפך דמן כאחד.\u0004","\u0003ובשביל ארבעה דברים מאורות\u0004 (ירח וכוכבים) \u0003לוקין: על כותבי פלסתר\u0004 (שטרות מזוייפים וכתבי מלשינות), \u0003ועל מעידי עדות שקר, ועל מגדלי בהמה דקה בארץ ישראל\u0004 במקום ישוב, \u0003ועל קוצצי אילנות טובות\u0004 היכולים לתת פרי.","ועוד: \u0003בשביל\u0004 וכעונש על \u0003ארבעה דברים נכסי בעלי בתים נמסרין למלכות: על\u0004 אותם אנשים \u0003משהי שטרות פרועים\u0004 (שנפרעו כבר) בבתיהם ואינם קורעים או מוסרים אותם ללווים, ועשוים להביא למכשול. \u0003ועל מלוי ברבית,\u0004"],["\u0003ועל\u0004 אלו \u0003שהיה ספק\u0004 (אפשרות) \u0003בידם למחות\u0004 בחוטאים \u0003ולא מיחו, ועל\u0004 אלו \u0003שפוסקים\u0004 מודיעים שנותנים \u0003צדקה\u0004 ועושים כן \u0003ברבים ו\u0004לבסוף \u0003אינן נותנין.\u0004","\u0003אמר רב: בשביל ארבעה דברים נכסי בעלי בתים יוצאין לטמיון\u0004 (לכלייה, לאבדון): \u0003על כובשי שכר שכיר\u0004 שאינן משלמים לו בזמנו ומלינים שכרו, \u0003ועל עושקי שכר שכיר\u0004 שאינם משלמים כל עיקר, \u0003ועל שפורקין עול\u0004 וחובות הציבור \u0003מעל צואריהן ונותנין על חבריהן, ועל גסות הרוח,\u0004 שמתוך עושרו הוא מתנהג בגאוה ומשתרר על הציבור. \u0003וגסות הרוח\u0004 — נענשים עליה \u0003כנגד כולן. אבל בענוים כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"וענוים יירשו ארץ והתענגו על רב שלום\"\u0004 (תהלים לז, יא).","","\u0003לולב הגזול\u0004 מאחרים, או לולב שהוא \u0003יבש\u0004 לגמרי, הרי זה \u0003פסול.\u0004 ואין להשתמש בו למצות ארבעת המינים. לולב \u0003של אשירה\u0004 של עץ שעובדים אותו כעבודה זרה, או לולב \u0003של עיר הנדחת,\u0004 שחובה לשרוף אותה ואת כל אשר בה — \u0003פסול. נקטם\u0004 (נחתך) \u0003ראשו\u0004 של הלולב או \u0003נפרצו\u0004 (נחתכו) \u0003עליו\u0004 משדרתו — הרי זה \u0003פסול. נפרדו עליו\u0004 ואינם צמודים לשדרתו, אבל לא נחתכו — הרי זה \u0003כשר. ר' יהודה אומר:\u0004 כל לולב \u0003יאגדנו מלמעלה\u0004 כדי שיהיו כל עליו צמודים לשדרתו. \u0003ציני\u0004 (דקלי) \u0003הר הברזל\u0004 אף שהיו שונים משאר דקלים, ועליהם קצרים ואינם מכסים את כל השדרה — הרי הם \u0003כשירים\u0004 ללולב. ומה שיעורו של לולב? \u0003לולב שיש בו\u0004 אורך \u0003שלשה טפחים כדי\u0004 השיעור \u0003לנענע בו\u0004 — הרי זה \u0003כשר\u0004 למצותו.","שנינו במשנה שלולב הגזול פסול. ושואלים: \u0003קא פסיק ותני\u0004 \u0005[פסק ושנה]\u0006 במשנה באופן כולל, \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היה זה \u0003ביום טוב ראשון\u0004 של חג שמצותו מן התורה, \u0003ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם היה זה \u0003ביום טוב שני,\u0004 כלומר: בתוך החג, שאין מצותו אלא מדברי סופרים, הרי","\u0003בשלמא\u0004 \u0005[נניח]\u0006 לולב \u0003יבש\u0004 שפסול, טעמו הוא כיון שנאמר בארבעת המינים לשון \"הדר\" — הרי שיהיו \u0003הדר בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003וליכא\u0004 \u0005[ואין\u0006 כאן\u0005],\u0006 שיבש אינו הדור. \u0003אלא\u0004 לולב \u0003הגזול, בשלמא\u0004 \u0005[נניח]\u0006 \u0003ביום טוב ראשון\u0004 מבינים אנו מדוע פסול \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \"ולקחתם לכם ביום הראשון\" (ויקרא כג, מ) ומשמע \u0003\"לכם\" — משלכם,\u0004 מרכושכם ולא מן הגזל. \u0003אלא ביום טוב שני\u0004 (שאר ימות החג) \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יוכלו לצאת בו ידי חובה? \u0003אמר ר' יוחנן משום ר' שמעון בן יוחאי:\u0004",""],["\u0003משום דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003מצוה הבאה בעבירה,\u0004 שמצוה זו מתקיימת בכוחה של עבירה או כתוצאה ממנה, וכבר \u0003נאמר: \"והבאתם גזול ואת הפסח ואת החולה\u0004 והבאתם את המנחה הארצה אותה מידכם אמר ה'\u0003\"\u0004 (מלאכי א, יג), ומן הכתוב נלמד: \u0003גזול דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003פסח, מה פסח\u0004 שבשל היותו בעל מום \u0003לית ליה תקנתא\u0004 \u0005[אין לו תקנה]\u0006 — \u0003אף\u0004 מה שהיה \u0003גזול, לית ליה תקנתא\u0004 \u0005[אין לו תקנה],\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003לפני יאוש\u0004 הבעלים מן הגזילה \u0003ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003לאחר יאוש\u0004 הבעלים.","ומסבירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לפני יאוש\u0004 ברור שאינו יכול להקריב — לפי שאינו שלו, שכן \u0003\"אדם כי יקריב מכם\u0004 קרבן לה'\u0003\"\u0004 (ויקרא א, ב) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 ו\"מכם\" הכוונה — משלכם, \u0003ו\u0004זה הגזול \u0003לאו דידיה\u0004 \u0005[ולא שלו]\u0006 \u0003הוא. אלא לאחר יאוש\u0004 — \u0003הא קנייה\u0004 \u0005[הרי קנה]\u0006 הגזלן את הבהמה \u0003ביאוש\u0004 הבעלים, ומאז גוף הבהמה שייך לו (אף שכמובן יצטרך לשלם עבורה לבעלים), וכיון שהבהמה שלו מדוע לא יוכל להקריבה? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דהוה ליה\u0004 \u0005[שהוא]\u0006 \u0003מצוה הבאה בעבירה,\u0004 וכיון שבראשונה הגיעה הבהמה לידו בעבירה, שוב אינו יכול לקיים בה מצוה.","כיוצא בזה \u0003אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחאי: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"כי אני ה' אהב משפט שנא גזל בעולה\"\u0004 (ישעיה סא, ח) — \u0003משל למלך בשר ודם שהיה עובר על בית המכס, אמר לעבדיו: תנו מכס למוכסים. אמרו לו: והלא כל המכס כולו שלך הוא\u0004 ואליך הוא מגיע בסופו של דבר, ומה טעם לתת מכס? \u0003אמר להם: ממני ילמדו כל עוברי דרכים ולא יבריחו עצמן מן המכס. אף הקדוש ברוך הוא אמר: \"אני ה' שנא גזל בעולה\",\u0004 שאף שכל העולם כולו שלו הוא ולגביו אין קנייני אדם מעלים ומורידים, \u0003ממני ילמדו בני ויבריחו עצמן מן הגזל,\u0004 שאף לצורך עצמם לא יגזלו.","\u0003אתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 בענין זה על ידי חכמים אחרים; \u0003אמר ר' אמי:\u0004 לולב \u0003יבש פסול — מפני שאין\u0004 בו \u0003הדר,\u0004 לולב \u0003גזול פסול — משום דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003מצוה הבאה בעבירה.\u0004","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 כל אותה שיטה שדנו בה אותה עד כאן על דעת \u0003ר' יצחק. שאמר ר' יצחק בר נחמני אמר שמואל: לא שנו\u0004 פסול זה בגזול, \u0003אלא ביום טוב ראשון\u0004 של חג, \u0003אבל ביום טוב שני\u0004 (שאר ימות החג), \u0003מתוך שיוצא\u0004 ידי חובתו \u0003ב\u0004לולב \u0003שאול,\u0004 שהרי לא מיעט הכתוב (\"לכם\" — משלכם) אלא ביום הראשון — \u0003יוצא נמי\u0004 \u0005[גם כן]\u0006 \u0003בגזול.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב נחמן בר יצחק\u0004 ממה ששנינו: \u0003לולב הגזול והיבש\u0004 — \u0003פסול,\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 לולב \u0003שאול — כשר.\u0004 ונברר: \u0003אימת\u0004 \u0005[אימתי]\u0006 שייך דין זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003ביום טוב ראשון — הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \"ולקחתם \u0003לכם\u0004 ביום הראשון\" וכוונתו: \u0003משלכם, והאי\u0004 \u0005[וזה]\u0006 הלולב השאול \u0003לאו דידיה\u0004 \u0005[לא שלו]\u0006 \u0003הוא\u0004 ובודאי אינו יכול לצאת בו ביום טוב ראשון. \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר \u0003ביום טוב שני, וקתני\u0004 \u0005[ושנינו]\u0006 באותו ענין כי ה\u0003גזול\u0004 — \u0003פסול,\u0004 היפך דברי שמואל!","\u0003רבא אמר\u0004 לתרץ כך: \u0003לעולם\u0004 אפשר לפרש שמדובר כאן אפילו \u0003ביום טוב ראשון, ולא מיבעיא קאמר\u0004 \u0005[ו\u0006בלשון \u0005לא נצרכה אמר]\u0006 כיצד? \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאינו יוצא בלולב \u0003שאול דלאו דידיה\u0004 \u0005[ש\u0006הרי \u0005לא שלו]\u0006 \u0003הוא\u0004 ושייך לאחר, \u0003אבל גזול, אימא\u0004 \u0005[אמור]:\u0006 \u0003סתם גזילה יאוש בעלים הוא, וכדידיה דמי\u0004 \u0005[וכשלו\u0006 הוא \u0005נחשב],\u0006 אף על פי שנעשתה בו עבירה, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבגזול אינו יוצא, ואין להוכיח איפוא מכאן דבר לענייננו.","אגב מה שאמרנו בענין פסול גזילה בארבעת המינים, מסופר: \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב הונא להני אוונכרי\u0004 \u0005[תגרים,\u0006 רוכלים שעסקו במסחר ארבעת המינים\u0005]:\u0006 \u0003כי זבניתו אסא\u0004 \u0005[כאשר קונים אתם הדסים]\u0006 \u0003מגויים\u0004 — \u0003לא תגזזו אתון\u0004 \u0005[אל תחתכו אתם]\u0006 את ההדסים מן העץ, \u0003אלא לגזזוה אינהו ויהבו לכו\u0004 \u0005[שיחתכו הם ויתנו לכם].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003סתם גויים גזלני ארעתא\u0004 \u0005[קרקע]\u0006 \u0003נינהו\u0004 \u0005[הם]\u0006"],["\u0003וקרקע אינה נגזלת.\u0004 שלעולם אין קרקע גזולה קנויה לגזלן אף לאחר יאוש, והיא נשארת בחזקת הבעלים, ואם כן יש חשש שמא הדסים אלה גזולים הם מישראל, \u0003הלכך לגזזוה אינהו\u0004 \u0005[שיגזזו הם]\u0006 התגרים את ההדסים, \u0003כי היכי דלהוי\u0004 \u0005[כדי שיהיה]\u0006 \u0003יאוש בעלים\u0004 מן ההדסים יעשה \u0003בידייהו דידהו\u0004 \u0005[בידיהם שלהם]\u0006 \u0003ושינוי רשות\u0004 על ידי קנייתם מהם ייעשה \u0003בידייכו\u0004 \u0005[בידיכם],\u0006 ועל ידי יאוש ושינוי רשות כבר נעשו ההדסים גופם כקנויים ואין עוד צד איסור בהם.","ושואלים: \u0003סוף סוף כי גזזו אוונכרי\u0004 \u0005[\u0006גם \u0005כאשר גוזזים התגרים]\u0006 את ההדסים, \u0003ליהוי\u0004 \u0005[שיהא]\u0006 \u0003יאוש בעלים בידייהו\u0004 \u0005[בידיהם]\u0006 \u0003ושנוי רשות בידן\u0004 \u0005[בידינו]\u0006 בידי הקונים מהם. ואם כן לשם מה הורה לתגרים שיעשו זאת הגויים, הרי אותה פעולה נעשית בין כה וכה במכירת ההדסים! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 לומר אלא \u0003בהושענא דאוונכרי גופייהו\u0004 \u0005[בהדסים של תגרי הדסים עצמם],\u0006 שכיון שאצלם אינם עוברים שוב לרשות אחרת — ראוי שייעשה הדבר על ידי גויים.","ושואלים: \u0003וליקניוה\u0004 \u0005[ושיקנו אותם]\u0006 על ידי \u0003שינוי מעשה,\u0004 שכיון שעושים בהם מעשה על ידי קשירתם עם המינים האחרים, הרי שינוי מעשה בחפץ יוצר זכות קנין לעושה השינוי, ואין בו עוד בעלות הבעלים הראשונים! ומשיבים: \u0003קא סבר\u0004 \u0005[סבר]\u0006 רב הונא \u0003לולב אין צריך אגד,\u0004 שאין מצוה לאגוד את ארבעת המינים ביחד, ודיו אם מחזיקם יחד בידו, ויתכן איפוא שלא יעשה במינים כל שינוי מעשה.","\u0003ואם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר,\u0004 אפשר להסביר אחרת; גם אם תאמר ש\u0003לולב צריך אגד,\u0004 מכל מקום \u0003שינוי החוזר לברייתו הוא,\u0004 שהרי שינוי זה על ידי הקשירה איננו משנה דבר בגוף ההדסים, וכאשר מתירים את האגד חוזר ההדס לכמות שהיה תחילה, וכלל הוא שכל \u0003שינוי החוזר לברייתו — לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003שינוי,\u0004 לענין זכות קנין בו.","ושואלים מצד אחר: \u0003וליקניוה\u0004 \u0005[ושיקנו אותם\u0006 אוונכרי\u0005]\u0006 את ההדסים על ידי \u0003שינוי השם\u0004 שנעשה בהם, \u0003דמעיקרא הוה ליה אסא\u0004 \u0005[שמתחילה היה זה\u0006 קרוי \u0005הדס\u0006 סתם\u0005]\u0006 \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 שמייחדים אותם לצורך המצוה"],["\u0003הושענא\u0004 שכך היו קוראים לארבעת המינים! ומשיבים: אין זה שינוי שם גמור, כי \u0003מעיקרא נמי לאסא\u0004 \u0005[מתחילה גם כן\u0006 לפעמים \u0005להדס]\u0006 \u0003\"הושענא\" קרו ליה\u0004 \u0005[קוראים לו],\u0006 אפילו כשהוא עדיין מחובר לעץ ואינו משמש למצוה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003סוכה גזולה, ו\u0004כן \u0003המסכך ברשות הרבים\u0004 שהוא כגוזל קרקע מן הרבים — \u0003ר' אליעזר פוסל, וחכמים מכשירין.\u0004","\u0003אמר רב נחמן: מחלוקת\u0004 זו היא דווקא \u0003כשתוקף\u0004 (מחזיק) \u0003את חבירו והוציאו מסוכתו\u0004 שבנה החבר והוא יושב בה, ובמקרה כזה פוסל ר' אליעזר. \u0003ור' אליעזר לטעמיה\u0004 \u0005[לשיטתו]\u0006 ש\u0003אמר: אין אדם יוצא ידי חובתו בסוכתו של חבירו\u0004 ולכן הדבר אסור בכל אופן. כיצד? \u0003אי\u0004 \u0005[אם]\u0006 נאמר ש\u0003קרקע נגזלת,\u0004 כלומר: שקרקע שנגזלה עומדת בחזקת הגזלן כדין מיטלטלים גזולים, אם כן — \u0003סוכה גזולה היא\u0004 שהרי נבנתה על קרקעו של אחר. \u0003ואי נמי\u0004 \u0005[ואם גם כן]\u0006 נאמר ש\u0003קרקע אינה נגזלת,\u0004 מכל מקום הלא \u0003סוכה שאולה היא,\u0004 ולדעתו אף סוכה שאולה פסולה.","\u0003ורבנן לטעמייהו\u0004 \u0005[וחכמים לשיטתם]\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 הם: \u0003אדם יוצא ידי חובתו בסוכתו של חבירו, וקרקע אינה נגזלת,\u0004 ואם כן גזילה אין כאן \u0003וסוכה שאולה היא,\u0004 ויוצא בה ידי חובתו, אף שעשה מעשה עוולה.","\u0003אבל\u0004 אם \u0003גזל עצים וסיכך בהן\u0004 — בזה לא נחלק ר' אליעזר, ול\u0003דברי הכל אין לו\u0004 לבעל העצים \u0003אלא דמי עצים\u0004 בלבד, וגוף העצים נקנה לגזלן, והסוכה אינה נחשבת כסוכה גזולה.","ושואלים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה מסקנה זו?","ומשיבים: \u0003מדקתני\u0004 \u0005[ממה ששנינו\u0006 שם\u0005]\u0006 \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003רשות הרבים\u0004 שה\u0003קרקע\u0004 שלה \u0003לאו דידיה הוא\u0004 \u0005[אינה שלו],\u0006 \u0003סוכה\u0004 גזולה שדובר בה \u0003נמי\u0004 \u0005[גם כן]\u0006 מדובר באופן ש\u0003לאו קרקע דידיה הוא\u0004 \u0005[שהקרקע אינה שלו]\u0006 ואותה הוא גזל, ואין מדובר בשגזל את גוף עצי הסוכה.","מסופר: \u0003ההיא סבתא דאתאי לקמיה\u0004 \u0005[זקנה אחת באה לפני]\u0006 \u0003רב נחמן, אמרה ליה\u0004 \u0005[אמרה לו]\u0006 לרב נחמן: \u0003ריש גלותא וכולהו רבנן דבי ריש גלותא\u0004 \u0005[ראש הגולה וכל החכמים שבבית ראש הגולה]\u0006 \u0003בסוכה גזולה הוו יתבי\u0004 \u0005[היו יושבים],\u0006 כי עבדי ראש הגולה גזלו ממנה את העצים ומהם בנו את הסוכה. \u0003צווחא\u0004 (צעקה) האשה \u0003ולא אשגח\u0004 \u0005[השגיח]\u0006 \u0003בה רב נחמן. אמרה ליה\u0004 \u0005[אמרה לו]\u0006 האשה: \u0003איתתא דהוה ליה לאבוהא תלת מאה ותמני סרי עבדי צווחא קמייכו ולא אשגחיתו בה\u0004 \u0005[אשה שהיו לו לאביה שלוש מאות ושמונה עשר עבדים צועקת לפניכם ואין אתם משגיחים בה]?!\u0006 כלומר: בת אברהם אבינו, שהיו לו עבדים כמנין זה, וצריך להתייחס אליה בכבוד. \u0003אמר להם רב נחמן\u0004 לחכמים שעמו: \u0003פעיתא\u0004 \u0005[צווחנית]\u0006 \u0003היא דא\u0004 \u0005[זו]\u0006 \u0003ואין לה אלא דמי עצים בלבד,\u0004 אבל גוף הסוכה כבר נקנתה לראש הגולה, אף על פי שהגיע לידו בגזילה.","\u0003אמר רבינא: האי כשורא דמטללתא\u0004 \u0005[קורה גדולה של סוכה]\u0006 ה\u0003גזולה, עבדי ליה רבנן תקנתא\u0004 \u0005[עשו לה חכמים תקנה]\u0006 שלא יצטרך להחזיר אותה עצמה לבעליה, \u0003משום תקנת מריש,\u0004 באותה תקנה שתיקנו חכמים (כדי להקל על התשובה) שהגזלן לא יחוייב להחזיר מריש (קורה) שבנה בתוך ביתו, אף שמעיקר הדין צריך היה להרוס את הבית ולהחזיר.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר, מובן מאליו\u0005],\u0006 שכן \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 קורה זו \u0003מ\u0004שאר \u0003עצים\u0004 שבסוכה? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003עצים שכיחי\u0004 \u0005[מצויים]\u0006 וניתן לקנותם ולכך מתייאש בעליהם מגוף העצים שיחזירום לו בעינם ומסתפק בתשלום בו יוכל לקנות אחרים תמורתם, \u0003אבל\u0004 קורה כגון \u0003האי\u0004 \u0005[זו]\u0006 \u0003לא שכיחא\u0004 \u0005[מצויה]\u0006 ולכן אין הבעלים מתיאשים מגופה, ואם כן \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ייחשב זה ליאוש, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף הקורה נקנית על ידי הגזלן ואינו צריך להחזירה בעינה, אלא משלם תמורתה.","ומעירים: \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 אמורים דווקא \u0003בגו\u0004 \u0005[בתוך]\u0006 \u0003שבעה\u0004 ימים של החג, שלא הצריכוהו לסתור סוכתו ולהחזיר את הקורה, \u0003אבל לבתר\u0004 \u0005[לאחר]\u0006 \u0003שבעה\u0004 ימים אלו — \u0003הדר בעיניה\u0004 \u0005[חוזרת היא בעינה].\u0006 \u0003ואי חברו בטינא\u0004 \u0005[ואם חיבר\u0006 את הקורה הזו \u0005בטיט]\u0006 והיא נעשית קבועה באותה סוכה, \u0003אפילו לאחר שבעה\u0004 ימים אלו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003יהיב ליה\u0004 \u0005[נותן לו]\u0006 לחבירו רק את \u0003דמי\u0004 הקורה ולא את הקורה עצמה, משום תקנת מריש.","\u0003תנא\u0004 \u0005[שנה\u0006 בתוספתא\u0005]:\u0006 לולב \u0003יבש\u0004 — \u0003פסול,\u0004 ו\u0003ר' יהודה מכשיר. אמר רבא: מחלוקת\u0004 זו היא \u0003בלולב\u0004 דווקא, \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 \u0003מקשינן\u0004 \u0005[משווים אנו]\u0006 \u0003לולב לאתרוג, מה אתרוג בעי\u0004 \u0005[צריך]\u0006 שיהיה \u0003הדר,\u0004 שהרי נאמר בו בפירוש: \"פרי עץ הדר\", \u0003אף לולב בעי\u0004 \u0005[צריך]\u0006 שיהא \u0003הדר. ור' יהודה סבר: לא מקשינן\u0004 \u0005[אין אנו משווים]\u0006 \u0003לולב לאתרוג. אבל באתרוג — דברי הכל הדר בעינן\u0004 \u0005[צריכים אנו]\u0006 ויבש פסול.","ושואלים: \u0003ובלולב לא בעי\u0004 \u0005[אינו צריך],\u0006 אין \u0003ר' יהודה\u0004 דורש שיהא \u0003\"הדר\"? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005],\u0006 \u0003ר' יהודה אומר\u0004 על לולב זה שנפרדו עליו: \u0003יאגדנו מלמעלה. מאי טעמא\u0004 \u0005[מה הטעם]\u0006 אמר כך — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דבעי\u0004 \u0005[שצריך]\u0006 שיהא \u0003הדר?\u0004","ודוחים: \u0003לא, כדקתני טעמא\u0004 \u0005[כמו ששנינו טעם\u0006 הדבר\u0005];\u0006 \u0003ר' יהודה אומר משום ר' טרפון:\u0004 נאמר בלולב \u0003\"כפת תמרים\"\u0004 ואנו דורשים כאילו היה כתוב \u0003\"כפות\",\u0004 שמצווה מיוחדת היא, ש\u0003אם היה\u0004 הלולב \u0003פרוד יכפתנו\u0004 (יקשרנו).","ועוד שואלים: \u0003ולא בעי\u0004 \u0005[ואין\u0006 ר' יהודה \u0005דורש שיהא\u0006 הלולב\u0005]\u0006 \u0003\"הדר\" והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין אוגדין את הלולב אלא במינו\u0004 במין הלולב ולא בדבר אחר, אלו \u0003דברי ר' יהודה. מאי טעמא\u0004 \u0005[\u0006ו\u0005מה הטעם]\u0006 של ר' יהודה, \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דבעי\u0004 \u0005[ש\u0006הוא \u0005צריך]\u0006 שיהא \u0003\"הדר\"\u0004","ומשיבים: \u0003לא,\u0004 אין זה הטעם, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר רבא:\u0004 לדעת ר' יהודה \u0003אפילו\u0004 כורכו \u0003בסיב\u0004 הגדל סביב גזע הדקל, \u0003ואפילו בעיקרא דדיקלא\u0004 \u0005[בשורש הדקל]\u0006 הריהו כשר, אף שאין זה הדר. ושואלים: \u0003ואלא מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה התם\u0004 \u0005[שם]?\u0006 ומשיבים: \u0003דקא\u0004 \u0005[שהוא]\u0006 \u0003סבר\u0004 כי \u0003לולב צריך אגד,\u0004 שמעיקר המצוה הוא שיהא הלולב אגוד עם שאר המינים, \u0003ואי מייתי מינא אחרינא\u0004 \u0005[ואם\u0006 הוא מביא \u0005מין אחר]\u0006 שאינו ממין הלולב \u0003הוה להו\u0004 \u0005[הרי הם]\u0006 \u0003חמשה מינין\u0004 בלולב, ומוסיף על הכתוב בתורה.","ושואלים מצד אחר: \u0003ובאתרוג מי בעי\u0004 \u0005[האם צריך]\u0006 \u0003ר' יהודה\u0004 שיהא \u0003הדר? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ארבעה מינין שבלולב, כשם שאין פוחתין מהן — כך אין מוסיפין עליהן. לא מצא אתרוג\u0004 — \u0003לא יביא לא פריש\u0004 (חבוש) \u0003ולא רמון ולא\u0004 כל \u0003דבר אחר\u0004 במקומו. היו המינים \u0003כמושין\u0004 (יבשים מעט) — \u0003כשרין,\u0004 היו \u0003יבשין\u0004 — הרי הן \u0003פסולין. ר' יהודה אומר: אף יבשין\u0004 כשרים.","\u0003ואמר ר' יהודה: מעשה\u0004"],["\u0003בבני כרכין\u0004 שהיו רחוקים ממקומות גידול המינים, \u0003שהיו מורישין את לולביהן לבני בניהן\u0004 ובודאי התייבשו במשך הזמן! \u0003אמרו לו: משם ראיה? אין שעת הדחק ראיה\u0004 שאולי התירו בשעת הדחק, אבל לכתחילה אסור.","\u0003קתני מיהת\u0004 \u0005[שנינו מכל מקום]\u0006 ש\u0003ר' יהודה אומר: אף יבשין כשרין, מאי לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 כוונת דבריו על ה\u0003אתרוג\u0004 גם כן! הרי שהוא סובר שאין האתרוג צריך להיות הדר! ודוחים: \u0003לא,\u0004 הכוונה היא על ה\u0003לולב\u0004 דווקא.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: \u0003כשם שאין פוחתין מהן, כך אין מוסיפין עליהן.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 כיצד נוכל להתיר להוסיף מינים אחרים? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר];\u0006 \u0003הואיל ואמר ר' יהודה\u0004 כי \u0003לולב צריך אגד,\u0004 שמעיקר המצוה שיהיו המינים אגודים כאחד, \u0003ואי מייתי מינא אחרינא\u0004 \u0005[ואם יביא\u0006 עוד \u0005מין אחר],\u0006 נמצא כי \u0003האי לחודיה קאי והאי לחודיה קאי\u0004 \u0005[זה לבדו הוא עומד וזה לבדו הוא עומד]\u0006 והמין האחר נחשב כאילו לא היה שם כלל ואין בכך כל חיסרון, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא כן ואל לו להביא מין אחר.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: \u0003לא מצא אתרוג\u0004 — \u0003לא יביא לא רמון ולא פריש ולא\u0004 כל \u0003דבר אחר\u0004 במקומו. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003לייתי\u0004 \u0005[שיביא]\u0006 מינים אלה, \u0003כי היכי\u0004 \u0005[כדי]\u0006 \u0003שלא תשכח תורת אתרוג,\u0004 וישאר לפחות זכר מסויים שצריך דבר מעין אתרוג, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאסור, כי \u0003זימנין דנפיק חורבא מיניה, דאתי למסרך\u0004 \u0005[לפעמים שיוצא הפסד מכאן, שיבואו להמשך]\u0006 ולהשתמש באותו מין גם כשיהיה בידם אתרוג.","ומציעים: \u0003תא שמע:\u0004 \u0005[בוא ושמע]\u0006 ראיה אחרת לכך שאין ר' יהודה דורש הדר באתרוג, שהרי שנינו: \u0003אתרוג הישן\u0004 — \u0003פסול, ור' יהודה מכשיר.\u0004 הרי ברור שאין ר' יהודה מחייב הדר באתרוג ו\u0003תיובתא\u0004 \u0005[וקושיה חמורה]\u0006 היא על דברי \u0003רבא\u0004 ומסכמים: \u0003תיובתא\u0004 \u0005[\u0006אכן, \u0005קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","ושואלים: \u0003ולא בעי\u0004 \u0005[מצריך]\u0006 ר' יהודה שיהא האתרוג \u0003הדר? והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 האתרוג \u0003הירוק ככרתי\u0004 (כצמח הכרישין) \u0003ר' מאיר מכשיר ור' יהודה פוסל.\u0004 ומציעים: \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דבעי\u0004 \u0005[ש\u0006הוא \u0005מצריך]\u0006 שיהא האתרוג \u0003הדר?\u0004 ודוחים: \u0003לא\u0004 זה הטעם, אלא \u0003משום\u0004 שבאתרוג ירוק עדיין \u0003לא גמר פירא\u0004 \u0005[נגמר הפרי]\u0006 ואין ראוי לקיים את המצוה בפרי בוסר.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה מצד אחר: מהו \u0003שיעור אתרוג קטן,\u0004 כלומר: מהו השיעור הקטן ביותר של האתרוג? \u0003ר' מאיר אומר:\u0004 לא יהא קטן מ\u0003אגוז, ר' יהודה אומר כביצה.\u0004 ומציעים: \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דבעי\u0004 \u0005[ש\u0006ר' יהודה \u0005מצריך]\u0006 שיהא האתרוג \u0003הדר?\u0004 ודוחים: \u0003לא,\u0004 אף כאן הטעם הוא \u0003משום\u0004 שאתרוג קטן כל כך \u0003דלא גמר פירא\u0004 \u0005[שלא נגמר פריו]\u0006 ועדיין הוא בוסר.","\u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה ששנינו: מהו שיעורו של אתרוג \u0003גדו‍ל,\u0004 כלומר: מהו שיעורו המקסימלי של האתרוג? \u0003כדי ש\u0004יוכל ל\u0003אחוז שנים בידו אחת,\u0004 אלו \u0003דברי ר' יהודה. ר' יוסי אומר:\u0004 אין לכך שיעור, אלא \u0003אפילו\u0004 אתרוג שצריך להחזיק \u0003אחד בשתי ידיו\u0004 גם כן כשר. \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ר' יהודה, \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דבעי\u0004 \u0005[ש\u0006ר' יהודה \u0005מצריך]\u0006 שיהא האתרוג \u0003הדר?\u0004 ודוחים: \u0003לא,\u0004 הטעם הוא \u0003כיון\u0004 ש\u0003אמר רבה: לולב\u0004 צריך להחזיק ביד \u0003ימין ואתרוג בשמאל,\u0004 ורק כך יוצא ידי חובה, ואם האתרוג גדול מכדי להחזיקו ביד אחת \u0003זימנין דמחלפי ליה\u0004 \u0005[פעמים שיחליפו לו]\u0006 שימסרו לו אתרוג בימין ולולב בשמאל \u0003ואתי לאפוכינהו ואתי לאיפסולי\u0004 \u0005[ויבוא להפוך אותם\u0006 מיד ימין ליד שמאל \u0005ויבוא לפסול\u0006 את האתרוג\u0005],\u0006 שכיון שהאתרוג גדול מאוד אין לו מקום בידיו גם להחזיקו כראוי וגם ליטול את הלולב עמו, ויכולים הם ליפול מידיו ולהפסל.","ושואלים: \u0003ואלא לר' יהודה, הא כתיב\u0004 \u0005[הרי נאמר]\u0006 באתרוג במפורש \u0003\"הדר\"\u0004 (\"פרי עץ הדר\") וכיצד אפשר לומר שאינו צריך שיהא הדר?","ומשיבים שהוא מחזיק בשיטה כי \u0003ההוא\u0004 \u0005[\u0006הפסוק \u0005הזה]\u0006 כוונתו שיקח מאותו מין שהוא פרי \u0003הדר באילנו משנה לשנה\u0004 ואינו מתייבש ונובל בסוף העונה כרוב הפירות, והוא הוא האתרוג.","שנינו במשנה כי לולב \u0003של אשרה ושל עיר הנדחת\u0004 — פסול. ושואלים: וכי לולב \u0003של אשרה פסול? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: לולב של עבודה זרה\u0004 — מלכתחילה \u0003לא יטול, ואם נטל\u0004 — \u0003כשר.\u0004 משמע שלולב של אשירה כשר, אף אם בדיעבד!","ומסבירים: \u0003הכא\u0004 \u0005[כאן]\u0006 במשנה \u0003באשרה\u0004 כזו שאמר \u0003משה\u0004 בתורה \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שאין הכוונה לעץ הנטוע לכבוד עבודה זרה, אלא שהעץ עצמו נעבד כעבודה זרה, ועבודה זרה עצמה חובה לשרוף אותה, וכיון שכך רואים אנו את העץ כאילו היה שרוף כבר כעת, \u0003דכתותי מכתת שיעוריה\u0004 \u0005[שכתות\u0006 ושבור \u0005שיעורו]\u0006 ואין בו כדי השיעור למצוה.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 שכך יש לפרש מהות אשירה זו שבמשנה. \u0003דקתני דומיא\u0004 \u0005[ששנה\u0006 אותו \u0005בדומה]\u0006 ללולב של \u0003עיר הנדחת,\u0004 שאף שם הטעם משום שהוא עומד להשרף בכלל כל חפצי העיר. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שזה הטעם.","שנינו במשנה שלולב ש\u0003נקטם ראשו\u0004 — פסול. \u0003אמר רב הונא: לא שנו אלא נקטם,\u0004 כלומר: נחתך לגמרי, \u0003אבל\u0004 אם רק \u0003נסדק\u0004 ראשו — \u0003כשר.\u0004","ושואלים: ולולב ש\u0003נסדק כשר? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לולב כפוף\u0004 בראשו,"],["\u0003קווץ\u0004 (שיוצאים משדרתו כעין קוצים), \u0003סדוק,\u0004 או \u0003עקום\u0004 עד שהוא \u0003דומה למגל — פסול. חרות\u0004 שנעשה קשה כעץ — \u0003פסול. דומה לחרות,\u0004 שהתחיל להתקשות, אבל עדיין אינו כעץ — \u0003כשר.\u0004 הרי שלולב סדוק פסול! \u0003אמר רב פפא:\u0004 הכוונה בברייתא שהוא סדוק כל כך \u0003דעביד כהימנק\u0004 \u0005[שהוא עשוי כמזלג]\u0006 ששני החלקים נפרדים לגמרי זה מזה והוא נראה כבעל שתי שדרות.","שנינו בברייתא שם: \u0003עקום הדומה למגל\u0004 — פסול. \u0003אמר רבא: לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 שעקום \u0003לפניו\u0004 בצד שכנגד השדרה, \u0003אבל\u0004 אם עקום \u0003לאחריו\u0004 לצד השדרה — אין זה פסול, כי דרך \u0003ברייתיה\u0004 \u0005[ברייתו]\u0006 \u0003הוא,\u0004 וכך גדלים רוב הלולבים.","\u0003אמר רב נחמן:\u0004 היה עקום \u0003לצדדין\u0004 — הרי זה \u0003כ\u0004עקום \u0003לפניו דמי\u0004 \u0005[נחשב]\u0006 ופסול. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003כלאחריו דמי\u0004 \u0005[נחשב]\u0006 וכשר.","\u0003ואמר רבא: האי לולבא דסליק בחד הוצא\u0004 \u0005[לולב זה שגדל רק בעלה אחד],\u0006 כלומר: שהעלים גדלים רק מצד אחד של השדרה — \u0003בעל מום הוא, ופסול.\u0004","שנינו במשנה: \u0003נפרצו עליו\u0004 — פסול, נפרדו — כשר. \u0003אמר רב פפא: נפרצו\u0004 כוונתו שהעלים נפלו לגמרי מן השדרה והוא קושר אותם ללולב \u0003דעביד כי חופיא\u0004 \u0005[שעשוי\u0006 כמו \u0005מטאטא].\u0006 \u0003נפרדו\u0004 כוונתו — \u0003דאיפרוד אפרודי\u0004 \u0005[שנפרדו]\u0006 מן השדרה, ובולטים החוצה, אבל עדיין הם מחוברים אליה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: נחלקה התיומת,\u0004 העלה הכפול המרכזי בלולב \u0003מהו\u0004 הדין בו? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ש\u0003אמר ר' יוחנן אמר ר' יהושע בן לוי: ניטלה התיומת\u0004 מן הלולב — הרי זה \u0003פסול. מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003הוא הדין\u0004 ב\u0003נחלקה?\u0004 ודוחים: \u0003לא, ניטלה שאני\u0004 \u0005[שונה]\u0006 \u0003דהא חסר ליה\u0004 \u0005[שהרי חסר הוא],\u0006 ולולב חסר ודאי פסול. אבל אם עדיין היא במקומה אלא שנחלקה, אין זה פוסל בהכרח.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שכך היתה הלשון: \u0003אמר ר' יוחנן אמר ר' יהושע בן לוי: נחלקה התיומת — נעשה כמי שנטלה התיומת, ופסול.\u0004 ואם כן נפתרה הבעיה.","\u0003ר' יהודה אומר\u0004 במשנה כי אם היו העלים פרודים ראוי שיאגוד אותם. \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה אומר משום ר' טרפון;\u0004 נאמר: \u0003\"כפות תמרים\"\u0004 ואנו דורשים \u0003\"כפות\",\u0004 שיהיה הלולב כיחידה אחת, \u0003אם היה פרוד — יכפתנו\u0004 (יקשרנו) שיהא כאחד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ממאי\u0004 \u0005[ממה]\u0006 בעצם לומדים אנו \u0003דהאי\u0004 \u0005[שזה]\u0006 שנאמר \u0003\"כפות תמרים\" דלולבא\u0004 \u0005[של לולב]\u0006 \u0003הוא,\u0004 כפי שאנו נוהגים? \u0003אימא חרותא\u0004 \u0005[\u0006שמא \u0005אמור\u0006 שהוא \u0005ענף הדקל הקשה]?\u0006 ומשיבים: \u0003בעינא\u0004 \u0005[צריכים אנו]\u0006 שיהא \u0003כפות וליכא\u0004 \u0005[והרי אינו],\u0006 שכן העלים יוצאים בו לצדדים ואי אפשר לכפות אותם.","ושואלים: אם העיקר הוא שיהא הלולב כיחידה אחת \u0003ואימא אופתא\u0004 \u0005[ואמור\u0006 שיקחו את \u0005גזע הדקל]\u0006 שהוא ודאי \"כפות\"! ודוחים: כיון שנאמר \u0003\"כפות\"\u0004 — \u0003מכלל\u0004 הדברים למד אתה כי \u0003דאיכא\u0004 \u0005[שיש]\u0006 מצב שהוא \u0003פרוד, והאי\u0004 \u0005[וזה]\u0006 הרי \u0003כפות ועומד\u0004 הוא \u0003לעולם,\u0004 שאין בו מקום לפירוד.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהכוונה היא כאן ל\u0003כופרא\u0004 \u0005[ענף הדקל]\u0006 שלא נתקשה עדיין לגמרי ואפשר בדוחק לכפות אותו? \u0003אמר אביי: \"דרכיה דרכי נעם וכל נתיבתיה שלום\"\u0004 (משלי ג, ז) \u0003כתיב\u0004 \u0005[נאמר]\u0006 בשבחה של התורה, ובכופרא חלק מן העלים הם כקוצים חדים, ודוקרים ומזיקים, ובודאי לא ציותה התורה להשתמש באלה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא תוספאה\u0004 \u0005[\u0006העוסק \u0005בתוספתא]\u0006 \u0003לרבינא:\u0004 כיון שנאמר: \"כפות\" שהוא לשון רבים, אם כן \u0003ואימא תרתי כפי דתמרי\u0004 \u0005[ו\u0006שמא \u0005אמור\u0006 שיצטרכו ליטול \u0005שתי כפות תמרים,\u0006 שתי לולבים\u0005]\u0006 ואין די בלולב אחד למצוה? ענה לו: \u0003\"כפת\" כתיב\u0004 \u0005[נאמר]\u0006 בכתיב חסר, לומר שצריך רק אחד. ואם כן \u0003ואימא חדא\u0004 \u0005[ואמור\u0006 שיקחו רק עלה \u0005אחד]\u0006 ומשיבים: זה אינו נקרא כפות אלא \u0003לההוא\u0004 \u0005[לזה]\u0006 \u0003\"כף\" קרי ליה\u0004 \u0005[קורים לו]\u0006 ו\"כפת\" משמעו גם לשון רבים, כפות (עלים) הרבה יחד.","שנינו במשנה כי \u0003ציני הר הברזל,\u0004 שהם לולב שיש בו עלים מעטים מאד בשדרתו, ואין עליו צפופים כלולבים רגילים — \u0003כשרה. אמר אביי: לא שנו\u0004 שלולב כזה כשר \u0003אלא\u0004 כשיש בו עלים עד כי \u0003ראשו של\u0004 עלה \u0003זה מגיע לצד עיקרו של זה\u0004 הבא אחריו, \u0003אבל\u0004 אם \u0003אין ראשו של זה מגיע לצד עיקרו של זה,\u0004 שיש בו פחות עלים מזה — הרי זה \u0003פסול.\u0004","\u0003תניא נמי הכי\u0004 \u0005[שנויה גם כן כך\u0006 בברייתא\u0005]:\u0006 \u0003ציני הר הברזל — פסולה.\u0004 ולכאורה, \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו\u0005]\u0006 שהיא \u0003כשרה! אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003כאביי,\u0004 שיש לחלק לפי מספר העלים בלולב, ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך יש להבין."],["\u0003ואיכא דרמי ליה מירמא\u0004 \u0005[והיה שהשליך\u0006 את הדברים, שהראה סתירה\u0005];\u0006 מצד אחד \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 \u0003ציני הר הברזל\u0004 — \u0003כשר, והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בענין ציני הר הברזל: \u0003פסולה! אמר אביי: לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003כאן,\u0004 שנאמר שכשר — מדובר \u0003שראשו של\u0004 עלה \u0003זה מגיע לצד עיקרו של\u0004 עלה \u0003זה\u0004 הבא אחריו, \u0003כאן,\u0004 שנאמר שהוא פסול — מדובר \u0003שאין ראשו של זה מגיע לצד עיקרו של זה.\u0004 ומסבירים היכן היו מצויים דקלים אלה.","\u0003אמר ר' מריון אמר ר' יהושע בן לוי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שדבר זה \u0003תני\u0004 \u0005[שנה\u0006 בברייתא\u0005]\u0006 \u0003רבה בר מרי משום\u0004 \u0005[בשם]\u0006 \u0003רבן יוחנן בן זכאי: שתי תמרות\u0004 (עצי דקל) \u0003יש בגיא בן הנם\u0004 סמוך לירושלים, \u0003ועולה עשן מביניהם. וזהו\u0004 המקום \u0003ששנינו\u0004 במשנתנו בענין לולביו: \u0003ציני הר הברזל כשרות. ו\u0004מקום זה — \u0003זו היא פתחה של גיהנם.\u0004","שנינו במשנה שכל \u0003לולב שיש בו שלשה טפחים\u0004 כדי לנענע בו — כשר. \u0003אמר רב יהודה אמר שמואל: שיעור\u0004 אורכם המינימלי של \u0003הדס וערבה — שלשה\u0004 טפחים, ושיעור אורכו המינימלי של ה\u0003לולב — ארבעה\u0004 טפחים. והבדל טפח זה שביניהם — \u0003כדי שיהא\u0004 ה\u0003לולב יוצא מן ההדס טפח\u0004 אחד לפחות.","\u0003ור' פרנך אמר\u0004 בשם \u0003ר' יוחנן: שדרו של לולב, צריך שיצא מן ההדס טפח.\u0004 כלומר: שדרת הלולב צריכה להיות לפחות ארבעה טפחים, חוץ מאורך העלים.","ושואלים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003לולב שיש בו שלשה טפחים כדי לנענע בו כשר,\u0004 הרי שדי בשלושה טפחים בלבד, כולל העלים שמעל לשדרה! ומשיבים: \u0003אימא\u0004 \u0005[אמור],\u0006 ותקן הלשון: \u0003וכדי לנענע בו, כשר.\u0004 כלומר: עליו להיות באורך שלושה טפחים, וצריך עוד להוסיף כשיעור שיהיה בו כדי לנענע. \u0003מר כדאית ליה\u0004 \u0005[חכם זה\u0006 שמואל \u0005כמו שיש לו],\u0006 שטפח עודף זה יהיה נוסף על אורך כללי בן שלושה טפחים, \u0003ומר כדאית ליה\u0004 \u0005[וחכם זה,\u0006 ר' יוחנן, \u0005כמו שיש לו],\u0006 שצריך שטפח זה יהיה נוסף על אורך השדרה.","ומנסים להביא ראיות לשיטות, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה ששנינו: \u0003שיעור הדס וערבה\u0004 — \u0003שלשה\u0004 טפחים \u0003ו\u0004שיעור ה\u0003לולב\u0004 — \u0003ארבעה\u0004 טפחים. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003בהדי\u0004 \u0005[עם]\u0006 ה\u0003עלין,\u0004 וכדברי שמואל! ודוחים, \u0003לא,\u0004 שיעור הלולב ארבעה, \u0003לבד\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004ה\u0003עלין.\u0004","כיון שהובאה ברייתא זו דנים בה ל\u0003גופא\u0004 (בגופה), \u0003שיעור הדס וערבה\u0004 — \u0003שלשה\u0004 טפחים, \u0003ולולב\u0004 שיעורו \u0003ארבעה\u0004 טפחים. \u0003ר' טרפון אומר: באמה בת חמשה טפחים.\u0004 והבנו בכוונתו, שזהו האורך הדרוש להדס והערבה.","\u0003אמר רבא: שרא ליה מריה\u0004 \u0005[יסלח לו אדונו,\u0006 הקדוש ברוך הוא\u0005],\u0006 \u0003לר' טרפון\u0004 שכך החמיר עלינו; \u0003השתא\u0004 \u0005[עכשיו]\u0006 הדס \u0003עבות\u0004 כדינו בשיעור \u0003שלשה\u0004 טפחים \u0003לא משכחינן\u0004 \u0005[אין אנו מוצאים\u0006 בקלות\u0005],\u0006 הדס \u0003בת חמשה\u0004 טפחים \u0003מבעיא\u0004 \u0005[הוצרכה\u0006 לומר\u0005]\u0006 והרי הוא מחמיר עלינו מאד!","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר;\u0004 כך יש להבין, \u0003אמה בת ששה טפחים עשה אותה בת חמשה\u0004 שאמה רגילה יש בה שישה טפחים, וכוונתו של ר' טרפון היתה שיש לחלק את האמה לא לשישה טפחים, אלא לחמישה בלבד ונמצא כי באופן כזה תהא מידת הטפח גדולה יותר, \u0003צא מהן שלשה\u0004 מטפחים גדולים אלה \u0003להדס, והשאר\u0004 כלומר ארבעה טפחים בגודל זה \u0003ללולב.\u0004 ומחשבים: \u0003כמה הוו להו\u0004 \u0005[יהיו להם]\u0006 לפי זה שיעור ההדס והערבה באמה בינונית שהיא בת ששה טפחים — \u0003תלתא ותלתא חומשי\u0004 \u0005[שלושה\u0006 טפחים \u0005ושלוש חמישיות ה\u0006טפח\u0005].\u0006","אולם אם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003שמואל\u0004 על דברי \u0003שמואל\u0004 עצמו; \u0003הכא\u0004 \u0005[כאן]\u0006 שמענו ש\u0003אמר ר' יהודה אמר שמואל: שיעור הדס וערבה שלשה\u0004 טפחים, \u0003והתם\u0004 \u0005[ושם]\u0006 \u0003אמר רב הונא אמר שמואל: הלכה כר' טרפון,\u0004 והרי יש הבדל של שלוש חמישיות טפח ביניהם! ומשיבים: \u0003לא דק\u0004 \u0005[לא דקדק]\u0006 שמואל בדבריו כשאמר \"שלושה\". ותוהים: \u0003אימר דאמרינן לא דק\u0004 \u0005[אמור שאומרים אנו שלא דייק]\u0006 זהו דווקא כאשר הדבר נוטה בשל כך \u0003לחומרא\u0004 ומסר איפוא שיעור מקורב שיש בו להחמיר, אולם כשיטה הדבר בשל כך \u0003לקולא\u0004 \u0005[להקל],\u0006 \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003לא דק\u0004 \u0005[דייק]\u0006 והתיר מתוך אי-דיוק דברים אסורים?!","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 שיש להבין אחרת את דברי ר' טרפון: \u0003אמה בת חמשה טפחים עשה אותה ששה.\u0004 כלומר, האמה היסודית שמדבר בה ר' טרפון היא אמה בת חמישה טפחים רגילים (כלומר, קטנה בשישית מן האמה הרגילה) ואת האמה הקטנה הזו יש לחלק לשישה טפחים קטנים, ולפי טפחים אלה יש לחשב. \u0003צא מהן שלשה\u0004 טפחים כאלה \u0003להדס, והשאר\u0004 (ארבעה) \u0003ללולב. כמה הוי להו\u0004 \u0005[הן]\u0006 לפי החשבון \u0005—\u0006 \u0003תרי ופלגא\u0004 \u0005[שנים וחצי]\u0006 טפחים רגילים.","ומקשים: \u0003סוף סוף קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003שמואל\u0004 על דברי \u0003שמואל,\u0004 שפסק כר' טרפון שאורך ההדס והערבה שנים וחצי טפחים, ומצד אחר אמר שלושה! ומשיבים: \u0003לא דק\u0004 \u0005[דייק],\u0006 \u0003והיינו\u0004 \u0005[וזה]\u0006 ש\u0003לחומרא לא דק\u0004 \u0005[דייק].\u0006 ש\u0003אמר רב הונא אמר שמואל: הלכה כר' טרפון,\u0004 ולפי זה די לדעתו בשניים וחצי טפחים, וכשפסק ואמר שלושה, לא דקדק בשיעור.","\u0003הדס הגזול והיבש — פסול.\u0004 הדס \u0003של אשרה\u0004 (עץ שעובדים אותו לעבודה זרה) \u0003ושל עיר הנדחת — פסול. נקטם ראשו\u0004 של ההדס, או ש\u0003נפרצו\u0004 (נפרדו ממנו לגמרי) \u0003עליו, או שהיו ענביו\u0004 (פירותיו, שהם דומים לענבים) \u0003מרובות מעליו — פסול. ואם מיעטן\u0004 את הפירות הללו, ויש בו מעתה רוב עלים — הרי זה \u0003כשר,\u0004 אבל \u0003אין ממעטין\u0004 פירות אלה \u0003ביום טוב\u0004 עצמו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים];\u0006 נאמר: \u0003\"\u0004ו\u0003ענף עץ עבת\"\u0004 (ויקרא כג, מ), וכוונתו: עץ \u0003שענפיו חופין את עצו\u0004 שהעץ מכוסה בעלים, ואינו נראה. \u0003ואי זה הוא — הוי אומר זה הדס,\u0004 ומקשים: \u0003ואימא זיתא\u0004 \u0005[ואמור\u0006 שהוא עץ \u0005זית]\u0006 שגם הוא ענפיו חופים על עצו! ומשיבים: \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שהעלים יהיו כעין \u0003\"עבת\"\u0004 (שרשרת) \u0003וליכא\u0004 \u0005[ואין]\u0006 זה בזית.","ושואלים: \u0003ואימא דולבא\u0004 \u0005[ואמור\u0006 שהוא עץ \u0005הערמון],\u0006 שעליו עשויים כעין מקלעת! ודוחים: אף שעליו אכן עשויים כמקלעת, מכל מקום \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003ענפיו חופין את עצו וליכא\u0004 \u0005[ואין\u0006 כאן\u0005].\u0006","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שמא מדובר כאן בעץ ה\u0003הירדוף\u0004 שיש בו שני אלה! \u0003אמר אביי: \"דרכיה דרכי נעם\"\u0004 (משלי ג, יז) נאמר על התורה, \u0003וליכא\u0004 \u0005[ואין\u0006 כאן\u0005],\u0006 משום שההירדוף הוא צמח רעיל וגם ראשי עליו חדים ועשויים כקוצים ופוצעים את ידי האוחז בהם, ואין אם כן בקיום המצוה בהם משום \"דרכי נועם\". \u0003רבא אמר\u0004 מעין אותו טעם, \u0003מהכא\u0004 \u0005[מכאן]\u0006 מכתוב אחר, שנאמר: \u0003\"\u0004ו\u0003האמת והשלום אהבו\"\u0004 (זכריה ח, יט), ודבר המזיק אין בו משום אמת ושלום.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003קלוע כמין קליעה ודומה לשלשלת, זהו הדס\u0004 של מצוה. \u0003ר' אליעזר בן יעקב אומר\u0004 סימן אחר: נאמר: \u0003\"\u0004ו\u0003ענף עץ עבת\"\u0004 — \u0003עץ שטעם עצו\u0004 (ענפיו) \u0003ופריו שוה, הוי אומר זה הדס.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003עץ עבות — כשר, ושאינו עבות\u0004 — \u0003פסול,\u0004 אף על פי שהוא ממין הדס.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא\u0006 בדיוק\u0005]\u0006 \u0003עבות\u0004 זה? \u0003אמר רב יהודה: והוא דקיימי תלתא תלתא טרפי בקינא\u0004 \u0005[שנמצאים שלושה שלושה\u0006 עלים \u0005בקן],\u0006 שיוצאים שלושה עלים מכל עוקץ בענף, זה הוא הקרוי \"עבות\". \u0003רב כהנא אמר: אפילו\u0004 יוצאים \u0003תרי\u0004 \u0005[שנים]\u0006 היוצאים מעוקץ אחד בענף \u0003וחד\u0004 \u0005[ואחד]\u0006 אפילו מעוקץ שתחתיהם והוא חופה את השנים הללו, אף הוא קרוי עבות. מסופר: \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מהדר אתרי וחד\u0004 \u0005[היה מחזר על\u0006 הדס שהוא עשוי \u0005בשנים ואחד],\u0006 \u0003הואיל ונפיק מפומיה\u0004 \u0005[הואיל ויצא מפיו]\u0006 של \u0003רב כהנא\u0004 שאף הוא קרוי עבות וכשר, ומפני כבודו וחיבתו לרב כהנא ולתורתו היה מחזר דווקא אחריו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר בר אמימר לרב אשי: אבא\u0004 \u0005[אבי]\u0006 אמימר \u0003לההוא\u0004 \u0005[לאותו]\u0006 הדס העשוי שנים ואחד — \u0003הדס שוטה קרי ליה\u0004 \u0005[היה קורא לו].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נשרו רוב עליו\u0004 של ענף ההדס \u0003ונשתיירו בו מיעוט — כשר, ובלבד שתהא עבותו קיימת.\u0004","ותוהים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה],\u0006 כלומר: קיימת סתירה פנימית בביטוי זה; כי \u0003אמרת\u0004 מצד אחד שאם \u0003נשרו רוב עליו — כשר, והדר תני\u0004 \u0005[וחזר ושנה]\u0006 \u0003ובלבד שתהא עבותו קיימת.\u0004 והרי \u0003כיון דנתרי להו תרי\u0004 \u0005[שנושרים שנים]\u0006 מן העלים שהם רוב עליו, אם כן \u0003עבות היכי משכחת לה\u0004 \u0005[איך אתה מוצא בה]\u0006 עוד? הרי נשאר רק עלה אחד בלבד!","\u0003אמר אביי: משכחת לה\u0004 \u0005[\u0006יכול \u0005אתה למצוא\u0006 דבר \u0005זה]\u0006"],["\u0003באסא מצראה\u0004 \u0005[בהדס מצרי]\u0006 \u0003דקיימי\u0004 \u0005[שמצויים]\u0006 \u0003שבעה שבעה\u0004 עלים היוצאים \u0003בחד קינא\u0004 \u0005[בקן,\u0006 עוקץ \u0005אחד],\u0006 \u0003דכי נתרי\u0004 \u0005[ש\u0006אף \u0005כאשר\u0006 \u0005נושרים]\u0006 \u0003ארבעה\u0004 עלים שהם רוב עליו, עדיין \u0003פשו להו תלתא\u0004 \u0005[נשארים להם שלושה]\u0006 ונחשב הוא כעבות. \u0003אמר אביי:\u0004 ומכאן, מתירוץ זה נלמד, כי \u0003האי אסא מצראה\u0004 \u0005[זה ההדס המצרי]\u0006 \u0003כשר להושענא\u0004 לארבעת המינים.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הרי מין הדס הוא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003הואיל ואית ליה\u0004 \u0005[ויש לו]\u0006 \u0003שם לווי,\u0004 שאינו קרוי הדס סתם אלא הדס מצרי, \u0003לא מתכשר\u0004 \u0005[אינו כשר] —\u0006 \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין מקפידים בכך. ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור שכך הוא גם כן],\u0006 שכיון שיש לו שם לווי אינו הדס כשר! ומשיבים: \u0003\"עץ עבת\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 ולא נזכר שם \"הדס\", משמע שכל עץ שהוא \u0003מכל מקום\u0004 עץ עבות — כשר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יבשו רוב עליו ונשארו בו שלשה בדי עלין לחין — כשר. ואמר רב חסדא: ובראש כל אחד ואחד,\u0004 שעלים לחים הללו המכשירים בדי הדס אלה, צריך שישארו בראשו של כל בד. אבל אם נשארו באמצעיתו — אין זה הדר ופסול.","שנינו במשנה: הדס ש\u0003נקטם ראשו\u0004 פסול. \u0003תני\u0004 \u0005[שנה]\u0006 \u0003עולא בר חיננא: נקטם ראשו\u0004 של הדס \u0003ועלתה בו\u0004 במקום זה \u0003תמרה\u0004 גידול כעין פרי העפץ — \u0003כשר,\u0004 שהתמרה ממלאה את החלל ואינו נראה כקטום.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: נקטם ראשו\u0004 של ההדס \u0003מערב יום טוב, ועלתה בו תמרה ביום טוב\u0004 עצמו \u0003מהו\u0004 הדין? ודבר זה קשור בשאלה עקרונית רחבה: האם אומרים אנו כי \u0003יש דחוי אצל מצות או לא?\u0004 כלומר: האם אומרים שכיון שנדחה הדס זה ממצוותו בערב יום טוב הריהו דחוי כבר לעולם ואין לו הכשר, או שמא אין דחייה במצוות, ומאחר והתפתחו בו מאוחר יותר תנאי כשרות — כשר הוא.","ושואלים: \u0003ותפשוט ליה מהא דתנן\u0004 \u0005[ותפתור לו\u0006 בעיה זו \u0005מזו ששנינו\u0006 במשנה\u0005]:\u0006 מי ששחט חיה או עוף, וחובה עליו לכסות את דמה, אם \u0003כסהו\u0004 את הדם \u0003ונתגלה\u0004 אחר כך — \u0003פטור מלכסות\u0004 שנית. אבל אם \u0003כסהו הרוח\u0004 בלא שיעשה אדם בו דבר — \u0003חייב לכסות. ואמר רבה בר בר חנה אמר ר' יוחנן: לא שנו\u0004 שחייב לכסות, \u0003אלא\u0004 כ\u0003שחזר\u0004 הדם \u0003ונתגלה\u0004 אחר שכיסהו הרוח, \u0003אבל\u0004 אם \u0003לא חזר ונתגלה — פטור מלכסות.\u0004","\u0003והוינן בה\u0004 \u0005[והיינו\u0006 עוסקים ומתקשים \u0005בה]\u0006 בבעיה זו; \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003חזר ונתגלה אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב לכסות? הואיל ואדחי אדחי\u0004 \u0005[שנדחה נדחה]\u0006 לגמרי מן המצוה הזו לאחר שנתכסה הדם על ידי הרוח והוא נפטר, ושוב לא יתחייב בה!","\u0003ואמר רב פפא: זאת אומרת אין דחוי אצל מצות.\u0004 שאין אומרים בדבר מצוה שנפסל בזמנו מאיזשהו טעם, שהוא פסול לעולם. ואף על פי שיש בדיני הקרבנות פסול דיחוי כזה, אולם לגבי קיום המצוות אין דיחוי, ואם כן נפתרה משם שאלתו של ר' ירמיה!","ומשיבים: תשובתו של \u0003רב פפא גופא\u0004 \u0005[עצמו]\u0006 \u0003מיבעי ליה\u0004 \u0005[\u0006היא \u0005שהיתה מסופקת לו]\u0006 לר' ירמיה, האם \u0003מיפשיט פשיט ליה\u0004 \u0005[האם\u0006 האמנם \u0005פשוט לו]\u0006 לרב פפא ש\u0003אין\u0004 כלל \u0003דחוי אצל מצות, לא שנא לקולא\u0004 \u0005[אינו שונה\u0006 אם הדבר הוא \u0005להקל],\u0006 כגון בדין הדס קטום שצמחה תמרה במקום הקיטום, שהריהו כשר \u0003ולא שנא לחומרא\u0004 \u0005[\u0006או \u0005אינו שונה\u0006 אם הוא \u0005להחמיר],\u0006 כגון בדם שנתכסה על ידי הרוח ונתגלה, שיש לחייבו לכסות את הדם בשנית, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003ספוקי מספקא ליה\u0004 \u0005[מסופק לו]\u0006 לתנא זה המחייבו לכסות בשנית, ומשום כך \u0003לחומרא אמרינן\u0004 \u0005[\u0006במקום שהדבר הוא \u0005להחמיר אומרים אנו]\u0006 שאין דיחוי במצוה, ויחזור ויעשה. אולם \u0003לקולא לא אמרינן\u0004 \u0005[\u0006במקום שהדבר הוא \u0005להקל אין אנו אומרים].\u0006 שאלה זו לא נמצא לה פתרון, והושארה ב\u0003תיקו\u0004 \u0005[תעמוד\u0006 השאלה במקומה\u0005].\u0006","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם נאמר\u0006 שיש מחלוקת \u0005תנאים]\u0006 בשאלה אם יש דחוי אצל מצוות, כי שנינו בברייתא בנושא דומה: אם \u0003עבר ולקטן\u0004 את הענבות הפוסלות את ההדס ביום טוב עצמו — \u0003פסול\u0004 ההדס, אלו \u0003דברי ר' אלעזר בר' צדוק, וחכמים מכשירין.\u0004 ומסבירים \u0003סברוה\u0004 \u0005[סברו]\u0006 תחילה תלמידי החכמים שדנו בנושא זה כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל],\u0006 לדעת שני החולקים בברייתא זו, \u0003לולב אין צריך אגד\u0004 (קשירה), שקשירת המינים בלולב יחד אינה מעיקר המצוה. או \u0003ואם תמצי\u0004 (תמצא) מקום \u0003לומר\u0004 כי לולב \u0003צריך אגד,\u0004 מכל מקום \u0003לא ילפינן\u0004 \u0005[אין אנו למדים]\u0006 דין \u0003לולב מ\u0004דין \u0003סוכה, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה\u0004 בסוכה: \u0003\"תעשה\"\u0004 וכוונתו \u0003ולא מן העשוי,\u0004 כלומר, שאת הסוכה צריך לעשות על ידי מעשה בפועל, ולא להשתמש בסוכה שנוצרה מאליה.","ואם כן \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה נחלקו]\u0006 ר' אליעזר בר' צדוק וחכמים; \u0003דמאן דפסיל\u0004 \u0005[שמי שפסל]\u0006 \u0003סבר: אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003יש דחוי אצל מצות,\u0004 וכיון שנדחה הדס זה בגלל ענבות שבו — שוב אין לו תקנה במיעוטן. \u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003מכשיר סבר: לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003יש דחוי אצל מצות,\u0004 ואף שנדחה, אם מאוחר יותר תוקן — יש בכך כדי להכשיר את ההדס למצוה.","את ההצעה הזו דוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא לא אמרינן\u0004 \u0005[לדעת הכל אין אנו אומרים]\u0006 \u0003יש דחוי אצל מצות, והכא במילף\u0004 \u0005[וכאן בלימוד]\u0006 \u0003לולב מסוכה קא מיפלגי\u0004 \u0005[נחלקו];\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' אלעזר בר' צדוק\u0005]\u0006 \u0003סבר: ילפינן\u0004 \u0005[למדים אנו]\u0006 \u0003לולב מסוכה,\u0004 שכשם שסוכה צריכה להיבנות על ידי מעשה אדם מכוון אף לולב כן, וכיון שההדס הזה לא היה ראוי מתחילתו, והכשרתו היתה רק על ידי הסרת הפסול ממנו, נמצא שהוכשר לא על ידי עשיה בפועל, אלא מן העשוי, ולכן הוא פסול. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 חכמים\u0005]\u0006 \u0003סבר: לא ילפינן\u0004 \u0005[אין אנו למדים]\u0006 \u0003לולב מסוכה,\u0004 ולולב, אפילו מן העשוי — כשר.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 שאת המחלוקת הזו ניתן להסביר בצורה שונה; \u0003אי סבירא לן\u0004 \u0005[אם סבורים אנו]\u0006 ש\u0003לולב צריך אגד, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 \u0003לולב מסוכה,\u0004 שכן בלולב כמו בסוכה קיימת חובה כלשהי של עשייה וצריך שתהיה אף היא שלא מן העשוי\u0003.\u0004 אולם \u0003והכא\u0004 \u0005[וכאן]\u0006 בעצם השאלה אם \u0003לולב צריך אגד קא מיפלגי\u0004 \u0005[חלוקים הם]\u0006 \u0003ובפלוגתא דהני תנאי\u0004 \u0005[ובמחלוקת של התנאים הללו]\u0006 שנחלקו בבעיה זו בברייתא, \u0003דתניא,\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לולב, בין אגוד,\u0004 שמיניו קשורים זה בזה, \u0003בין שאינו אגוד — כשר, ר' יהודה אומר: אגוד\u0004 — \u0003כשר, שאינו אגוד\u0004 — \u0003פסול.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה,\u0004 מהיכן הוא לומד דין אגד בארבעת המינים? ומשיבים: \u0003יליף\u0004 \u0005[לומד הוא]\u0006 בגזירה שווה \u0003\"לקיחה\" \"לקיחה\" מאגודת אזוב: כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בארבעת המינים: \u0003\"ולקחתם לכם ביום הראשון\u0004 פרי עץ הדר וגו'\u0003\"\u0004 (ויקרא כג, מ), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בקרבן פסח: \u0003\"ולקחתם אגדת אזוב\"\u0004 (שמות יב, כב), \u0003מה להלן\u0004 בלקיחה האמורה בקרבן הפסח, המצוה באזוב היא \u0003באגודה\u0004 דווקא, \u0003אף כאן\u0004 בארבעת המינים — מצוותם \u0003באגודה\u0004 דווקא. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים? ומשיבים: \u0003לית להו\u0004 \u0005[אין להם\u0006 אינם מקבלים\u0005]\u0006 את הגזירה השווה \u0003\"לקיחה\" \"לקיחה\".\u0004","אגב כך שואלים: \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי שנה לדבר זה ששנו חכמים\u0006 בברייתא\u0005]\u0006 כי \u0003לולב מצוה לאוגדו, ואם לא אגדו — כשר. מני\u0004 \u0005[כ\u0006שיטת \u0005מי היא]\u0006 ברייתא זו? \u0003אי\u0004 \u0005[אם]\u0006 תאמר שכשיטת \u0003ר' יהודה\u0004 היא — \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא אגדו אמאי\u0004 \u0005[מדוע]\u0006 הוא \u0003כשר\u0004? והלא לדעתו חובה היא לאוגדו! \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהיא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003מאי\u0004 \u0005[מה,\u0006 איזו\u0005]\u0006 \u0003מצוה קא עביד\u0004 \u0005[הוא עושה]\u0006 באגודה זו? שהרי לדעתם אין כל צורך באגידת המינים! ומשיבים: \u0003לעולם\u0004 תפרש שברייתא זו היא כדעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 אולם גם הם מסכימים שיש \u0003מצוה\u0004 בדבר, \u0003משום \"זה אלי ואנוהו\"\u0004 (שמות טו, ב), שמשם למדנו שראוי שכל דבר הנעשה לשם ה', יהיה נאה (\"אנוהו\") ובודאי אגידת המינים יחד, הריהי נוי להם.","שנינו במשנה: \u0003או‍ שהיו ענביו\u0004 של ההדס \u0003מרובין\u0004 מעליו — פסול. \u0003אמר רב חסדא: דבר זה, רבינו הגדול\u0004 (רב), \u0003אמרו\u0004. והוא מוסיף בלשון ברכה: \u0003והמקום\u0004 (הקדוש ברוך הוא) \u0003יהיה בעזרו: לא שנו אלא\u0004 אם היו הענבות \u0003במקום אחד, אבל בשנים או שלשה מקומות\u0004 שאינם כולם כאחת — \u0003כשר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרב חסדא:"],["\u0003שנים ושלשה מקומות הוי\u0004 \u0005[הרי הוא]\u0006 \u0003מנומר\u0004 בצבעים במקומות שונים ובודאי אין זה \"הדר\" \u0003ופסול\u0004 הוא.","\u0003אלא\u0004 יש לתקן גירסה זו שגרסנו, ו\u0003אי אתמר הכי אתמר\u0004 \u0005[אם נאמר\u0006 דבר זה \u0005כך נאמר]:\u0006 \u0003או שהיו ענביו מרובין מעליו\u0004 — \u0003פסול.\u0004 ועוד \u0003אמר רב חסדא: דבר זה רבינו הגדול אמרו, והמקום\u0004 (הקדוש ברוך הוא) \u0003יהיה בעזרו; לא שנו\u0004 שפסול \u0003אלא\u0004 כש\u0003ענביו\u0004 היו כבר \u0003שחורות\u0004 (בשילות) ונבדלות הרבה מן העלים ולכך הריהו נראה כמנומר. \u0003אבל\u0004 כש\u0003ענביו\u0004 עדיין \u0003ירוקות\u0004 — \u0003מיני\u0004 \u0005[כמין]\u0006 ה\u0003הדס הוא,\u0004 שצבעו דומה לעלי ההדס ואינו נראה בשלהם כמנומר, לכן הוא \u0003כשר.\u0004","על כך \u0003אמר רב פפא:\u0004 אם היו הענבות \u0003אדומות — כשחורות דמיין\u0004 \u0005[\u0006הן \u0005נחשבות],\u0006 שכן \u0003אמר ר' חנינא\u0004 בענין דם הנדה: \u0003האי\u0004 \u0005[זה]\u0006 שהוא עתה \u0003דם שחור,\u0004 בעצם דם \u0003אדום הוא\u0004 וטמא, \u0003אלא שלקה\u0004 (נעשה כהה), הרי שלעניינים שונים נחשבים האדום והשחור כשני גוונים של צבע אחד.","שנינו במשנה ש\u0003אם מיעטן\u0004 את הענבות — \u0003כשר.\u0004 ושואלים: \u0003דמעטינהו אימת\u0004 \u0005[שמיעט אותן אימתי]?\u0006 \u0003אילימא מקמיה דלאגדיה\u0004 \u0005[אם תאמר\u0006 שמיעטן \u0005לפני שאגד]\u0006 את ההדס בין המינים — \u0003פשיטא\u0004 \u0005[פשוט\u0006 ומובן מאליו\u0005],\u0006 שהרי בשעה שמקיים בו את המצוה, עליו מרובין מענביו! \u0003אלא\u0004 יש לומר כי מיעטן \u0003לבתר דלאגדיה\u0004 \u0005[לאחר שאגד אותו]\u0006 כבר עם המינים, אם כן \u0003דחוי מעיקרא\u0004 \u0005[מתחילתו]\u0006 \u0003הוא,\u0004 שהרי בשעה שנאגד היה פסול, \u0003תפשוט מינה:\u0004 \u0005[תפתור מכאן]\u0006 את השאלה ששאלנו, ותאמר כי \u0003דחוי מעיקרא\u0004 \u0005[מתחילתו]\u0006 — \u0003לא הוי\u0004 \u0005[אינו\u0006 נקרא\u0005]\u0006 \u0003דחוי!\u0004","את ההצעה הזו דוחים: \u0003לעולם\u0004 תאמר כי מדובר כאן שמיעטן \u0003בתר דאגדיה\u0004 \u0005[לאחר שאגד אותו]\u0006 \u0003וקסבר\u0004 \u0005[וסבר]\u0006 אותו חכם, כי \u0003אגד\u0004 הלולב אינו נחשב כגמר המצוה אלא \u0003הזמנה\u0004 (הכנה) \u0003בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא,\u0004 שמכין את המינים למצוותם, \u0003והזמנה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כלום היא,\u0004 ולכן אפשר למעט ענביו גם לאחר שאגדו.","שנינו במשנה ש\u0003אין ממעטין\u0004 את ענבות ההדס \u0003ביום טוב.\u0004 ושואלים \u0003הא\u0004 \u0005[הרי\u0006 אם\u0005]\u0006 \u0003עבר\u0004 עבירה \u0003ולקטן\u0004 בכל זאת \u0003מאי\u0004 \u0005[מה]\u0006 יהיה דין ההדס? בודאי \u0003כשר\u0004 הוא, שהרי לא נאמרה בו לשון פסול. ונברר, \u0003דאשחור אימת\u0004 \u0005[שהשחירו\u0006 ענבות אלה בהדס \u0005מתי]?\u0006 \u0003אילימא דאשחור\u0004 \u0005[אם תאמר שהשחירו]\u0006 \u0003מאתמול,\u0004 מערב יום טוב, אם כן \u0003דחוי מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003הוא,\u0004 ואם כן \u0003תפשוט מינה\u0004 \u0005[תפתור מכאן]\u0006 כי \u0003דחוי מעיקרא\u0004 \u0005[מתחילתו]\u0006 — \u0003דלא הוי\u0004 \u0005[שאינו נחשב],\u0006 \u0003דחוי,\u0004","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 תאמר \u0003דאשחור\u0004 \u0005[שהשחירו]\u0006 \u0003ביום טוב\u0004 עצמו ועבר ומיעטן בו ביום, ש\u0003נראה ונדחה הוא\u0004 שהרי בתחילת היום היו הענבות עדיין ירוקות ואינם פוסלות, ולכך היה הוא איפוא ראוי ולאחר כך נדחה. ואם כן, \u0003שמעת מינה\u0004 \u0005[אתה שומע מכאן]\u0006 ופותר בעיה שלא נפתרה: ש\u0003נראה ונדחה\u0004 — \u0003חוזר ונראה\u0004 (נעשה ראוי), אם תוקן הפסול שבו!","ודוחים: \u0003לא, לעולם\u0004 תפרש \u0003דאשחור מעיקרא\u0004 \u0005[שהשחירו\u0006 הענבות \u0005מתחילה]\u0006 לפני החג, ו\u0003דחוי מעיקרא דלא הוי\u0004 \u0005[מתחילתו שאינו]\u0006 \u0003דחוי תפשוט מינה\u0004 \u0005[תפתור מכאן],\u0006 \u0003אבל\u0004 את הבעיה האם \u0003נראה ונדחה חוזר ונראה\u0004 או אינו חוזר ונראה, \u0003לא תפשוט\u0004 \u0005[תפתור]\u0006 ואין הוכחה ברורה מכאן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין ממעטין\u0004 את ענבות ההדס כדי להכשירו, \u0003ביום טוב. משום ר' אליעזר בר' שמעון אמרו: ממעטין.\u0004 ושואלים על ר' אלעזר: \u0003והא קא מתקן מנא\u0004 \u0005[והרי הוא מתקן כלי],\u0006 \u0003ביום טוב!\u0004 שהרי היה ההדס פסול ובכך הוא מכשירו למצוותו.","\u0003אמר רב אשי: כגון שלקטן\u0004 את הענבות \u0003לאכילה,\u0004 שהרי מותר לו ללקטן מענף קצוץ ולאכלן ביום טוב, ואמנם לא היה בדעתו להכשיר את ההדס. ועוד, \u0003ר' אליעזר בר' שמעון סבר לה כאבוה\u0004 \u0005[סבר כ\u0006שיטת \u0005אביו]\u0006 ר' שמעון ש\u0003אמר: דבר שאין מתכוין מותר.\u0004 כלומר: שאם עשה בשבת או ביום טוב מעשה מותר ואגב כך נעשתה גם מלאכה אסורה שאין מתכוון כלל לעשותה — אין בכך איסור. ואף כאן, כיון שאינו מתכוון להכשיר את הלולב, אלא לאכילת הענבות, אף שבמעשה זה עצמו הוכשר ההדס למצוותו, הרי זה מותר.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מודה ר' שמעון ב\"פסיק רישיה ולא ימות\",\u0004 כלומר: אף שאמר ר' שמעון שדבר שאין מתכוון מותר, לא אמר כן אלא כאשר המלאכה האסורה נעשתה במקרה, אבל אם מלאכה זו היא תוצאה הכרחית ממה שעושה (כפי שבחיתוך הראש התוצאה ההכרחית היא מוות) — אינו יכול לומר שלא התכוון לכך. ואף כאן במעשה לקיטת הענבות, מתכשר ההדס למצוותו!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 במקרה \u0003דאית ליה הושענא אחריתי\u0004 \u0005[שיש לו הדס אחר]\u0006 ואם כן אין כאן תוצאה הכרחית של תיקון כלי, כיוון שהכלי כלומר הלולב על מיניו, מתוקן הוא עבורו, ואכילת הענבות אינה בהכרח \"תיקון כלי\" ולכן אם עשה כן וממילא נתקן ההדס — אף הוא כשר למצוה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הותר אגדו\u0004 של הלולב והמינים האגודים אליו \u0003ביום טוב — אוגדן\u0004 את המינים, אבל לא בקשירה מורכבת כמקודם, אלא \u0003כאגודה של ירק\u0004 בכריכה בלבד. ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יעשה ככה? הרי יש אפשרות טובה יותר — \u0003ליענביה מיענב\u0004 \u0005[שיענוב\u0006 את המינים \u0005בעניבה]\u0006 שמותר לעשותה בשבת, ולא יעשה קשר! ומשיבים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו כ\u0006שיטת \u0005מי היא]\u0006 כשיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר: עניבה\u0004 — \u0003קשירה מעלייתא\u0004 \u0005[מעולה]\u0006 \u0003היא\u0004 ולכן אינו רשאי לעשות עניבה.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 סבור אתה כי ברייתא זו כשיטת \u0003ר' יהודה\u0004 היא, אם כן הרי לשיטתו, כפי שכבר נאמר, חובת אגידת הלולב ומיניו נלמדת ממעשה קרבן הפסח וכמעשה האגידה בענין הפסח צריכה להיות איפוא אף אגידת הלולב, ובודאי \u0003איגוד מעלייתא בעי\u0004 \u0005[אגד מעולה צריך]\u0006 עבור המינים. וקשירה זו כאגודת ירק אין בה מצוות ארבעת המינים כדינה! ומשיבים: \u0003האי תנא סבר לה כוותיה בחדא\u0004 \u0005[תנא זה\u0006 של הברייתא \u0005סבור הוא כמותו\u0006 כשיטת ר' יהודה \u0005ב\u0006דבר \u0005אחד],\u0006 שעניבה קרויה קשירה, \u0003ופליג עליה בחדא\u0004 \u0005[וחלק עליו ב\u0006דבר \u0005אחד],\u0006 שלדעתו חובת אגידת המינים אינה מדין תורה, אלא רק לנוי מצוה.","\u0003ערבה גזולה\u0004 או ה\u0003יבשה — פסולה,\u0004 וכן ערבה \u0003של אשירה\u0004 (שעץ הערבה נעבד לעבודה זרה) \u0003ושל עיר הנדחת — פסולה. נקטם ראשה\u0004 של הערבה או ש\u0003נפרצו עליה\u0004 ממנה, וכן עץ \u0003הצפצפה\u0004 שהיא מין הדומה לערבה, אבל אינו ערבה ממש — \u0003פסולה.\u0004 אולם ערבה \u0003כמושה\u0004 שמתחילים עליה ליבול ולהתייבש קצת או \u0003שנשרו מקצת עליה\u0004 ולא כולם, וכן ערבה שאינה צומחת על הנחל אלא ערבה \u0003של בעל\u0004 שצומחת בשדה שאינו מושקה על ידי אדם — הרי זו \u0003כשרה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 במדרש המקראות: \u0003\"ערבי נחל\"\u0004 שנאמר בכתוב, פירושו — מיני ערבה \u0003הגדילין על הנחל. דבר אחר: \"ערבי נחל\"\u0004 סימן הוא, \u0003ש\u0004ה\u0003עלה שלה,\u0004 של ערבה זו, \u0003משוך\u0004 (מוארך) \u0003כ\u0004דרך שה\u0003נחל\u0004 משוך ולא עגול.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 ממה שנאמר \u0003\"ערבי נחל\", אין לי אלא ערבי נחל\u0004 ממש, כלומר: רק אלה הצומחים על שפת הנחל, אולם ערבה \u0003של בעל\u0004 (שאין השדה בו היא צומחת מושקה בידי אדם), וזו הצומחת \u0003בהרים מנין\u0004 שאף היא כשרה למצוה מלכתחילה? \u0003תלמוד לומר: \"ערבי נחל\"\u0004 לשון רבים, ולא \"ערבת נחל\", לומר: ש\u0003מכל מקום\u0004 כשר."],["\u0003אבא שאול אומר:\u0004 לשון הריבוי \u0003\"ערבי\"\u0004 מורה על שיש כאן \u0003שתים,\u0004 והן שתי המצוות שבערבה; \u0003אחת\u0004 מצות ערבה שהיא חלק ממצות ה\u0003לולב, ואחת למקדש\u0004 שהיו מקיפים את המזבח בערבה בסוכות.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם דורשים כן, ערבה זו של \u0003מקדש מנא להו\u0004 \u0005[מניין להם]\u0006? ומשיבים: \u0003הלכתא גמירי להו\u0004 \u0005[\u0006ב\u0005הלכה\u0006 למשה מסיני \u0005למדים הם]\u0006 דבר זה, ולא מן הכתובים. ש\u0003אמר ר' אסי אמר ר' יוחנן,\u0004 שלוש הלכות אלה: \u0003עשר נטיעות,\u0004 כלומר, ההלכה ששדה בשטח של בית סאה (חמישים אמה על חמישים אמה), שיש בו עשר נטיעות (שתילים, עצים צעירים) המפוזרות בשוה בשדה, אף שמצוה מן התורה להוסיף מן החול על הקודש ונאסרה חרישת שדה שלושים יום קודם שנת השמיטה, מכל מקום בשטח כזה ובשיטת פיזור שווה של הנטיעות, מצטרפות כולן והותר לחרוש בשבילן את כל השדה עד ראש השנה. וכן, מצות \u0003ערבה\u0004 שבמקדש, \u0003ו\u0004מצות \u0003ניסוך המים\u0004 על המזבח בכל יום מימי חג הסוכות — שלוש הלכות אלה מקורן של ב\u0003הלכה למשה מסיני.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא נוספת: \u0003\"ערבי נחל\"\u0004 משמעו מן הערבות \u0003הגדילות על הנחל, פרט לצפצפה\u0004 שאינה צמח של נחל אלא היא \u0003גדילה בין ההרים. אמר ר' זירא: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המלמד על פסלותה של הצפצפה לארבעה מינים — שכתוכחה לעם ישראל, נאמר: \u0003\"קח על מים רבים צפצפה שמו\"\u0004 (יחזקאל יז, ה), ופירושו: שישראל נשתלו כערבה על מים רבים, ולבסוף נעשו כצפצפה. ומכאן שצפצפה אינה גדילה במקום מים רבים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לר' זירא: \u0003ודילמא פרושי קא מפרש\u0004 \u0005[ושמא פירוש הוא מפרש]\u0006 בפסוק זה, וכך יש להבין: \u0003\"קח על מים רבים\" ומאי ניהו\u0004 \u0005[ומה הוא\u0006 דבר זה\u0005] —\u0006 \u0003\"צפצפה\"!\u0004 ענה לו ר' זירא: לפי דבריך \u0003אם כן מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שמו\"?\u0004 אלא בהכרח יש להבין שהערבה נעשתה עכשיו כצפצפה. וכך פירושו של הפסוק ש\u0003אמר ר' אבהו, אמר הקדוש ברוך הוא: אני אמרתי שיהו ישראל לפני כ\"קח על מים רבים\" ומאי ניהו\u0004 \u0005[ומה הוא] —\u0006 זה \u0003ערבה, והן שמו עצמן כצפצפה שבהרים.\u0004","\u0003איכא דמתני לה להאי קרא אמתניתא\u0004 \u0005[יש ששונה את הפסוק הזה על הברייתא]\u0006 כחלק ממנה, שהברייתא מסתיימת בציטוט: \u0003\"קח על מים רבים צפצפה שמו\"\u0004 ולגירסה זו \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: ודלמא פרושי קא מפרש\u0004 \u0005[ושמא מפרש הוא]\u0006 בפסוק \u0003\"קח על מים רבים\"\u0004 כי \u0003מאי ניהו\u0004 \u0005[מה הוא]\u0006 — \u0003צפצפה!\u0004 ודוחים: \u0003אם כן מאי \"שמו\"\u0004 שנאמר בסופו של הפסוק? \u0003אמר ר' אבהו: אמר הקדוש ברוך הוא: אני אמרתי שיהו ישראל לפני כ\"קח על מים רבים\", ומאי ניהו\u0004 \u0005[ומהו] —\u0006 \u0003ערבה, והן שמו עצמן כצפצפה שבהרים.\u0004","בהגדרה מהם מאפייני הערבה לעומת עצים אחרים הדומים לה ועם כל זה אינם כשרים למצוה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אי זהו ערבה ואיזהו צפצפה? ערבה, קנה שלה\u0004 (הגבעול הצעיר שממנו יוצאים העלים) \u0003אדום, ועלה שלה משוך\u0004 (מאורך) \u0003ופיה\u0004 (שפת העלה) \u0003חלק.\u0004 ואילו \u0003צפצפה, קנה שלה לבן, ועלה שלה עגול, ופיה דומה למגל,\u0004 כלומר: משונן. ומקשים, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 אם היה העלה \u0003דומה למגל — כשר,\u0004 אולם אם היה \u0003דומה למסר\u0004 (למסור) שאין שיניו שוות בגודלן ובכוונן — הריהו \u0003פסול! אמר אביי: כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא,\u0004 הרי זה במין ערבה הקרוי \u0003חילפא גילא\u0004 שעליו משוננים שינון הדומה לשינון המגל, אבל כל שאר מיני הערבה, פיהם אכן חלק.","\u0003אמר אביי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003האי\u0004 \u0005[זו]\u0006 הערבה הקרויה \u0003חילפא גילא\u0004 — \u0003כשר להושענא\u0004 (לארבעת המינים). ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 מובן מאליו שכן הוא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003הואיל ואית ליה\u0004 \u0005[ויש לו]\u0006 לערבה זו \u0003שם לווי,\u0004 שאינה קרויה ערבה אלא \"ערבה (חילפא) גילא\" ולכך \u0003לא נתכשר\u0004 \u0005[תהיה כשרה],\u0006 \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף על פי כן כשרה היא.","ושואלים: ואכן, \u0003ואימא הכי נמי\u0004 \u0005[ואמור\u0006 ש\u0005כך הוא גם כן]\u0006 ותיפסל כיון שיש לה שם לואי! ומשיבים: \u0003\"ערבי נחל\" אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003מכל מקום,\u0004 שכל מין של ערבי נחל — כשר.","כיון שדובר בזיהוי הערבה והצפצפה מביאים מה ש\u0003אמר רב חסדא: הני תלת מילי אשתני שמייהו\u0004 \u0005[אלה השלושה דברים, השתנה שמם]\u0006 \u0003מכי\u0004 \u0005[מכאשר]\u0006 \u0003חרב בית המקדש, \"חלפתא\"\u0004 \u0005[צפצפה] —\u0006 \u0003\"ערבתא\"\u0004 \u0005[ערבה],\u0006 \u0003\"ערבתא\"\u0004 \u0005[ערבה]\u0006 — \u0003\"חלפתא\"\u0004 \u0005[צפצפה].\u0006 כלומר: מה שהיה קרוי פעם חלפתא שהוא הצפצפה, קרוי עכשיו ערבתא. ושואלים: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מכאן\u0006 להלכה\u0005]?\u0006 \u0003ללולב,\u0004 לדעת שהערבה הכשרה ללולב, אינה קרויה עוד חלפתא.","ועוד, מה שנקרא: \u0003\"שיפורא\"\u0004 \u0005[שופר] —\u0006 הוא הקרוי כעת \u0003\"חצוצרתא\"\u0004 \u0005[חצוצרה],\u0006 \u0003\"חצוצרתא\"\u0004 \u0005[חצוצרה] —\u0006 היא הקרויה כיום \u0003\"שיפורא\"\u0004 \u0005[שופר].\u0006 ושואלים: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה\u0006 להלכה\u0005]?\u0006 ומשיבים: \u0003לשופר של ראש השנה,\u0004 שיוצאים ידי חובת תקיעה דווקא בזה הקרוי חצוצרתא, ולא בשיפורא.","ועוד: מה שהיה נקרא \u0003\"פתורתא\"\u0004 \u0005[שולחן קטן]\u0006 — קוראים לו עכשיו \u0003\"פתורא\"\u0004 \u0005[שולחן\u0006 סתם\u0005],\u0006 ואילו מה שהיה נקרא \u0003\"פתורא\"\u0004 \u0005[שולחן\u0006 סתם\u0005]\u0006 — קוראים לו כיום \u0003\"פתורתא\"\u0004 \u0005[שולחן קטן].\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]\u0006 מהו ההבדל למעשה? \u0003למקח וממכר,\u0004 שאם קנה אדם בזמן הזה פתורא ידע שקונה שולחן קטן דווקא.","\u0003אמר אביי אף אני אומר\u0004 דבר נוסף שהשתנה שמו, \u0003\"בי כסי\"\u0004 \u0005[בית הכוסות]\u0006 — קרוי עכשיו \u0003\"הובלילא\"\u0004 \u0005[המסס],\u0006 \u0003\"הובלילא\"\u0004 \u0005[בית הכוסות]\u0006 הוא הקרוי עכשיו \u0003\"בי כסי\"\u0004 \u0005[המסס],\u0006 שהתהפך שמם של שני חלקי קיבה אלה.","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]\u0006 אם התהפך שמם? ומסבירים: לענין \u0003מחט הנמצא בעובי בית הכוסות\u0004 לאחר ששחטו את הבהמה. שמחט שלא ניקבה את בית הכוסות מצד לצד — אינה עושה את הבהמה טריפה, אולם אם היא מנקבת את ההמסס אף מצד אחד, הרי הבהמה טריפה, וראוי לכך לדעת בבירור מהו ההמסס ומהו בית הכוסות.","\u0003אמר רבא בר יוסף: אף אני אומר\u0004 דבר שהשתנה שמו, המקום שהיה קרוי \u0003\"בבל\",\u0004 קוראים לו עכשיו \u0003\"בורסיף\",\u0004 ול\u0003\"בורסיף\"\u0004 קוראים עכשיו \u0003\"בבל\",\u0004 ושואלים: \u0003למאי\u0004"],["\u0003נפקא מינה\u0004 \u0005[מה יוצא מכאן]\u0006 אם התהפך שמם? \u0003לגיטי נשים,\u0004 שיש לכתוב בגט את שמה של העיר שבה ניתן הגט, ויש לדעת איפוא מה שמה המדוייק והנכון.","\u0003ר' ישמעאל אומר:\u0004 מצות ארבעת המינים היא, שיטול \u0003שלשה הדסים ושתי ערבות, לולב אחד, ואתרוג אחד. ואפילו שנים\u0004 מן ההדסים \u0003קטומים\u0004 (קצוצים) בראשם, ובלבד ש\u0003אחד אינו קטום. ר' טרפון אומר: אפילו שלשתן קטומים. ר' עקיבא\u0004 חולק על עיקרו של הדין ו\u0003אומר: כשם שלולב אחד ואתרוג אחד\u0004 — \u0003כך הדס אחד וערבה אחת.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' ישמעאל אומר:\u0004 נאמר: \u0003\"פרי עץ הדר\"\u0004 — הרי זה \u0003אחד.\u0004 נאמר: \u0003\"כפת תמרים\"\u0004 — הרי זה \u0003אחד. \"ענף עץ עבת\"\u0004 — הרי \u0003שלשה,\u0004 שכן \"ענף\" מורה על אחד, \"עץ\" על השני ו\"עבת\" על השלישי. \u0003\"ערבי נחל\"\u0004 בלשון רבים — \u0003שתים. ואפילו שנים\u0004 מן ההדסים \u0003קטומים ואחד שאינו קטום. ר' טרפון אומר: שלשה\u0004 הדסים, \u0003ואפילו שלשתן קטומים. ר' עקיבא אומר: כשם שלולב אחד ואתרוג אחד, כך הדס אחד וערבה אחת,\u0004","\u0003אמר לו ר' אליעזר:\u0004 אי אפשר להשוות את המינים זה לזה. \u0003יכול יהא אתרוג עמהן\u0004 (עם שאר המינים) \u0003באגודה אחת? אמרת; וכי נאמר \"פרי עץ הדר וכפת תמרים\"\u0004 ב–ו' החיבור? \u0003והלא לא נאמר אלא \"כפת\u0004 תמרים \u0003\"\u0004משמע ש\"פרי עץ הדר\" ניטל לחוד ושאר המינים המחוברים בפסוק ב–ו' החיבור — יחד. \u0003ומנין שמעכבין זה את זה,\u0004 שאם חסר אחד מן המינים אין בכך קיום מצוה כלל? \u0003תלמוד לומר: \"ולקחתם\",\u0004 שנדרש כמו \"לקח תם\" — \u0003שתהא לקיחה תמה\u0004 בשלימות.","לגופם של הדברים שואלים: ולדעת \u0003ר' ישמעאל\u0004 הסובר כי שנים מבין שלושת ההדסים יכולים להיות קטומים, \u0003מה נפשך\u0004 \u0005[מה רצונך,\u0006 מה שיטתו\u0005]?\u0006 \u0003אי שלימין בעי\u0004 \u0005[אם שלמים מצריך\u0006 הוא\u0005]\u0006 וקטומים לדעתו אינם הדר — \u0003ליבעי נמי כולהו\u0004 \u0005[שיצטרך גם את כולם]\u0006 שיהיו שלמים ולא קטומים, \u0003אי לא בעי שלימין\u0004 \u0005[אם אינו צריך שלמים]\u0006 — \u0003אפילו חד נמי\u0004 \u0005[אחד\u0006 מהם \u0005גם כן]\u0006 \u0003לא\u0004 צריך שיהיה שלם ויהיו כולם קטומים, כדברי ר' טרפון! \u0003אמר\u0004 החכם \u0003ביראה אמר ר' אמי: חזר בו ר' ישמעאל\u0004 מתחילת דבריו, והוא מסכים שמעיקר המצוה צריך רק אחד והוא צריך להיות שלם והדור.","\u0003אמר רב יהודה אמר שמואל: הלכה כר' טרפון\u0004 שהקטומים כשרים, ולכתחילה ראוי שיהיו שלושה שלמים. ומעירים: \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003שמואל להנהו דמזבני אסא\u0004 \u0005[לאותם\u0006 אנשים \u0005שמוכרים הדסים]:\u0006 \u0003אשוו וזבינו\u0004 \u0005[השוו,\u0006 כלומר: אל תפקיעו את המחירים \u0005ומכרו]\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תעשו כן, \u0003דרישנא לכו\u0004 \u0005[אדרוש לכם\u0006 ברבים\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' טרפון\u0004 שאפשר לצאת ידי מצוה בקטומים, וממילא ירדו המחירים, לפי שמרובים הקטומים.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אמר להם כך? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום\u0004 ש\u0003מיקל\u0004 ר' טרפון, ולכן איים עליהם — \u0003ולידרוש להו\u0004 \u0005[ושידרוש להם]\u0006 \u0003כ\u0004דעת \u0003ר' עקיבא\u0004 ש\u0003מיקל טפי\u0004 \u0005[יותר]\u0006 ואינו מצריך אלא אחד! ומשיבים: אין הדבר כן, כי \u0003תלתא קטומי שכיחי\u0004 \u0005[שלושה קטומים מצויים],\u0006 ויש בכך איפוא איום על הסוחרים, אבל \u0003חד\u0004 \u0005[אחד]\u0006 \u0003ולא קטום לא שכיח\u0004 \u0005[מצוי]\u0006 והשיטה המקילה ביותר למעשה היא זו של ר' טרפון.","\u0003אתרוג הגזול\u0004 או \u0003היבש — פסול.\u0004 אתרוג \u0003של\u0004 עץ \u0003אשרה,\u0004 שעובדים אותו לעבודה זרה, או \u0003של עיר הנדחת — פסול.\u0004 אתרוג \u0003של ערלה — פסול,\u0004 שהרי האתרוג מין פרי הוא, ופירות האילנות טרם מלאות להם שלוש שנים קרויים \"ערלה\" ואסורים באכילה והנאה. אתרוג \u0003של תרומה טמאה — פסול.\u0004 אתרוג \u0003של תרומה טהורה — לא יטול\u0004 לכתחילה, \u0003ואם נטל\u0004 — הרי זה \u0003כשר\u0004 ויצא ידי חובתו. אתרוג \u0003של דמאי\u0004 שנקנה מעם הארץ ולא ברור אם הופרשו ממנו תרומות ומעשרות — \u0003בית שמאי פוסלין, ובית הלל מכשירין.\u0004 אתרוג \u0003של מעשר שני, בירושלים\u0004 שבה אוכלים פירות של מעשר שני — \u0003לא יטול, ואם נטל\u0004 — \u0003כשר.\u0004","\u0003עלתה חזזית\u0004 גידול כעין אבעבועות קטנות \u0003על רובו\u0004 של האתרוג, וכן אם \u0003נטלה פטמתו\u0004 (קצהו העליון), או \u0003נקלף\u0004 האתרוג, או \u0003נסדק,\u0004 או \u0003ניקב וחסר כל שהוא\u0004 — הרי זה \u0003פסול.\u0004 אולם אם \u0003עלתה חזזית על מיעוטו\u0004 בלבד, או ש\u0003נטל עוקצו\u0004 (קצהו התחתון שבו הוא מחובר לעץ), או ש\u0003ניקב\u0004 האתרוג אבל \u0003לא חסר כל שהוא\u0004 על ידי הנקיבה — \u0003כשר. אתרוג הכושי\u0004 שבא מארץ כוש וצבעו כהה ככושי — \u0003פסול, והירוק ככרתי\u0004 כצמח הכרישה — \u0003ר' מאיר מכשיר ור' יהודה פוסל. שיעור אתרוג הקטן\u0004 ביותר הכשר למצוה, \u0003ר' מאיר או‍מר: כאגוז\u0004 ולא פחות, \u0003ר' יהודה אומר כביצה. ובגדול\u0004 שאסור להשתמש בגדול יותר — \u0003כדי שיאחז שנים ביד.\u0004 אלו \u0003דברי ר' יהודה, ר' יוסי אומר:\u0004 אין שיעור עליון לגודלו, ו\u0003אפילו\u0004 האתרוג גדול עד שצריך לאחוז אתרוג \u0003אחד בשתי ידיו\u0004 — כשר."],["תנו רבנן \u0005[שנו חכמים];\u0006 נאמר: \u0003\"פרי עץ הדר\"\u0004 (ויקרא כג, מ), לומר: זהו \u0003עץ שטעם עצו\u0004 (הגזע) \u0003ו\u0004טעם \u0003פריו — שוה,\u0004 ואיזה עץ הוא — \u0003הוי אומר זה אתרוג,\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהוא עץ ה\u0003פלפלין,\u0004 שגם בו טעם העץ והפרי שוה. \u0003וכדתניא\u0004 \u0005[וכפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: ממשמע שנאמר\u0004 בענין ערלה \u0003\"\u0004וכי תבואו אל הארץ \u0003ונטעתם כל עץ\"\u0004 (ויקרא יט, כג) \u0003איני יודע שהוא עץ מאכל?\u0004 והלא נאמר שם \"וערלתם ערלתו את פריו\"! אלא \u0003מה תלמוד לומר \"עץ מאכל\",\u0004 ללמדך כי אף מין \u0003עץ שטעם עצו ופריו שוה,\u0004 שהעץ עצמו הוא המאכל, ומהו עץ זה — \u0003הוי אומר זה פלפלין. ללמדך שהפלפלין חייבין בערלה\u0004 ואין אומרים שהם מין ירק, למרות שאינו נראה כעץ גמור. ודרך אגב למדנו מכאן \u0003שאין ארץ ישראל חסרה כלום\u0004 שאפילו פלפלים גדלים בה, והוא \u0003שנאמר: \"\u0004ארץ אשר לא במסכנות תאכל בה לחם \u0003לא תחסר כל בה\"\u0004 (דברים ח, ט). מכל מקום, מנין לך שיש ליטול אתרוג למצוה, ואולי שיטול מפרי עץ הפלפלים?","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 לענין ארבעת המינים \u0003משום דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 למעשה ליטול פלפלים, כי \u0003היכי נעביד\u0004 \u0005[כיצד נעשה]?\u0006 \u0003ננקוט חדא\u0004 \u0005[נקח\u0006 פלפל \u0005אחד]\u0006 — \u0003לא מינכרא\u0004 \u0005[אינה ניכרת]\u0006 \u0003לקיחתה,\u0004 כיון שהוא קטן ביותר. \u0003ננקוט תרי\u0004 \u0005[ניקח שנים]\u0006 \u0003או תלתא\u0004 \u0005[שלושה] —\u0006 אולם \"פרי\" שמשמעו — \u0003אחד, אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003ולא שנים או שלשה פרות, הלכך\u0004 \u0005[על כן]\u0006 \u0003לא אפשר,\u0004 ואין אפוא לפרש ש\"פרי עץ הדר\" הוא פלפלים.","\u0003רבי אומר:\u0004 ראיה אחרת יש לדבר, \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"הדר\" אלא \"הדיר\"\u0004 במשמעות דיר כבשים, וכוונתו: \u0003מה דיר זה\u0004 של כבשים \u0003יש בו גדולים וקטנים, תמימים\u0004 (שלימים) \u0003ובעלי מומין\u0004 — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 בעץ זה של אתרוגים \u0003יש בו גדולים וקטנים תמימין ובעל מומין.\u0004 ותוהים: \u0003אטו\u0004 \u0005[וכי]\u0006 ב\u0003שאר\u0004 ה\u0003פרות לית בהו\u0004 \u0005[אין בהם]\u0006 \u0003גדולים וקטנים תמימין ובעלי מומין?! אלא הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך היתה כוונתו: כשם שבדיר הכבשים הגדולים והקטנים הם יחד, כך בעץ האתרוג \u0003עד שבאים הקטנים עדיין גדולים קיימים\u0004 ואינם נושרים כשאר פירות האילנות.","\u0003ר' אבהו אמר: אל תקרי \"הדר\" אלא \"הדר\",\u0004 כלומר: \u0003דבר שדר באילנו משנה לשנה,\u0004 שהאתרוג עשוי להשאר באילן יותר משנה אחת. \u0003בן עזאי אומר: אל תקרי \"הדר\" אלא \"אידור\", שכן בלשון יוונית קורין למים אידור, ואיזו היא\u0004 מין נטיעה \u0003שגדל על כל מים\u0004 ולאו דווקא בגידול בעל או שלחין — \u0003הוי אומר זה אתרוג.\u0004","שנינו במשנה שאתרוג \u0003של אשרה ושל עיר הנדחת\u0004 — \u0003פסול.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? ומסבירים: \u0003כיון\u0004 ש\u0003לשרפה קאי\u0004 \u0005[הוא עומד]\u0006 שהרי חייבים לשרוף אותו \u0005—\u0006 \u0003כתותי מיכתת שיעוריה\u0004 \u0005[כתות\u0006 ושבור \u0005שיעורו]\u0006 והוא נחשב, אף כשעדיין לא נשרף, כעפר בלבד.","שנינו שאתרוג \u0003של ערלה פסול.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003פליגי\u0004 \u0005[חלוקים]\u0006 \u0003בה\u0004 בשאלה זו \u0003ר' חייא בר אבין ור' אסי. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: לפי שאין בה היתר אכילה\u0004 ודבר האסור באכילה ואין בו משום \"לכם\" — אין לקיים בו גם מצוה זו. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: לפי שאין בה דין ממון,\u0004 שהרי פרי ערלה אסור בהנאה, ואינו שווה מאומה. וכיון שאין לו ערך, אינו מקיים בו \"ולקחתם לכם\" — משלכם.","כהקדמה לשאלה הבאה, מסבירים קודם כי \u0003קא סלקא דעתיה\u0004 \u0005[עלתה על דעתו]\u0006 של השואל כי \u0003מאן דבעי\u0004 \u0005[מי שמצריך]\u0006 \u0003היתר אכילה לא בעי\u0004 \u0005[אינו מצריך]\u0006 \u0003דין ממון, ומאן דבעי\u0004 \u0005[ומי שמצריך]\u0006 \u0003דין ממון לא בעי\u0004 \u0005[אינו מצריך]\u0006 \u0003היתר אכילה\u0004 ושתי השיטות חולקות לגמרי זו על זו, ועל כן הקשו: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו]: אתרוג \u0003של תרומה טמאה\u0004 — \u0003פסול,\u0004 ומעתה, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003לפי שאין בה היתר אכילה — שפיר\u0004 \u0005[יפה],\u0006 שהרי תרומה טמאה אסורה באכילה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003לפי שאין בה דין ממון אמאי\u0004 \u0005[מדוע]\u0006 אם כן אתרוג של תרומה טמאה פסול? \u0003הרי מסיקה תחת תבשילו,\u0004 שמותר לכהן ליהנות מן התרומה הטמאה, כגון לצורך הסקה בה, והרי שיש לו ערך ממוני!","\u0003אלא,\u0004 יש לבטל את ההשערה הראשונה ולומר: \u0003בהיתר אכילה כולי עלמא לא פליגי דבעינן\u0004 \u0005[הכל אינם חלוקים שצריך]\u0006 שיהא דווקא דבר המותר באכילה, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בדין ממון. מר\u0004 \u0005[חכם זה]\u0006 \u0003סבר\u0004 כי \u0003היתר אכילה בעינן\u0004 \u0005[צריכים אנו]\u0006 אבל \u0003דין ממון לא בעינן\u0004 \u0005[אין אנו צריכים],\u0006 \u0003ומר\u0004 \u0005[חכם זה]\u0006 \u0003סבר: דין ממון נמי בעינן\u0004 \u0005[גם כן צריכים אנו].\u0006 ושואלים: אם כן, לפי הבנה זו \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 הלכה למעשה?","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 בדין אתרוג \u0003מעשר שני בירושלים. ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' מאיר\u0004 הסבור שמעשר שני בירושלים נחשב כהקדש לשמים, והיתר אכילתו לבעלים הוא כדרך שמותר להם לאכול מן הקרבנות, אבל אין להם כל זכות ממונית אחרת בו. ומעתה, \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי הטעם הוא \u0003לפי שאין\u0004 לו \u0003בה היתר אכילה — הרי יש בה\u0004 במעשר שני \u0003היתר אכילה\u0004 וכשר הוא למצוה, אף שאכן אין בו דין ממון, אולם \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003לפי שאין בה דין ממון — מעשר שני ממון גבוה הוא\u0004 ואינו ממונו של בעל הבית ואין יוצא בו ידי חובתו.","ומעירים, כי מחלוקת זו שלא ידענו מתחילה מה היתה דעתו של כל אחד מן החולקים \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 ש\u0003ר' אסי\u0004 הוא זה ש\u0003אמר\u0004 את הטעם \u0003לפי שאין בה דין ממון.\u0004 ש\u0003אמר ר' אסי: אתרוג של מעשר שני לדברי ר' מאיר אין אדם יוצא בו ידי חובתו ביום טוב, לדברי חכמים אדם יוצא בו ידי חובתו ביום טוב.\u0004 והרי זה כפי שהסברנו בשיטה זו לענין חובת דין ממון באתרוג, ומסכמים: אכן \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שר' אסי הוא זה שסבר כן.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של הלכה זו שהזכרנו \u0003אמר ר' אסי: אתרוג של מעשר שני, לדברי ר' מאיר אין אדם יוצא בו ידי חובתו ביום טוב. לדברי חכמים אדם יוצא בו ידי חובתו ביום טוב.\u0004 ועוד, \u0003מצה של מעשר שני, לדברי ר' מאיר אין אדם יוצא בה ידי חובתו בפסח\u0004 לפי שאינו שלו, \u0003ולדברי חכמים אדם יוצא בה ידי חובתו בפסח.\u0004 וכן \u0003עיסה\u0004 (בצק) \u0003של מעשר שני, לדברי ר' מאיר פטורה מן החלה, לדברי חכמים חייבת בחלה.\u0004 שכל אלה נובעים מן המחלוקת בדבר הזכות הממונית והבעלות על מעשר שני.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב פפא: בשלמא\u0004 \u0005[נניח]\u0006 \u0003בעיסה,\u0004 הרי \u0003כתיב\u0004 \u0005[נאמר\u0006 שם\u0005]:\u0006 \u0003\"ראשית ערסתכם\u0004 חלה תרימו תרומה\u0003\"\u0004 (במדבר טו, כ) ו\"עריסותיכם\" משמע שלכם, ולכן אין מפרישים מממון ההקדש. \u0003אתרוג נמי\u0004 \u0005[גם כן]\u0006 — הרי \u0003כתיב\u0004 \u0005[נאמר\u0006 בו\u0005]:\u0006 \u0003\"לכם\",\u0004 ומשמעו \u0003משלכם. אלא מצה\u0004 מדוע לא יצא ידי חובה במצת מעשר שני? \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"מצתכם\"? אמר רבה בר שמואל, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב יימר בר שלמיא: אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 לגבי מצה בגזירה שווה של המילים \u0003\"לחם\" \"לחם\". כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 במצה \u0003\"לחם עני\"\u0004 (דברים טז, ג) \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006"],["\u0003\"והיה באכלכם מלחם הארץ\u0004 תרימו תרומה לה'\u0003\"\u0004 (במדבר טו, יט), \u0003מה להלן\u0004 בחלה \u0003משלכם ולא משל מעשר, אף כאן\u0004 במצה \u0003משלכם ולא משל מעשר.\u0004","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם לומר\u0006 שאפשר \u0005לסייע לו]\u0006 לר' אסי, ממה ששנינו בברייתא: \u0003עיסה של מעשר שני — פטורה מן החלה, דברי ר' מאיר. וחכמים אומרים: חייבת בחלה.\u0004 ההוכחה היא לכאורה מושלמת ולכן תוהים על הלשון שבה הוצעה, מדוע הציעו אותה בנוסח \u0003לימא מסייע ליה\u0004 \u0005[האם לומר\u0006 שאפשר \u0005לסייע לו],\u0006 הלא \u0003היא היא\u0004 ממש דברי ר' אסי!","\u0003אלא\u0004 כך יש להבין: האם אפשר להוכיח מכאן כי \u0003מדבהא פליגי בהא נמי פליגי\u0004 \u0005[מ\u0006כיון \u0005שבזה\u0006 בדין חלה \u0005חולקים,\u0006 אם כן \u0005בזו\u0006 במצה \u0005גם כן חלוקים],\u0006 \u0003או דלמא\u0004 \u0005[שמא],\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003עיסה\u0004 של חלה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ערסתכם\" \"ערסתכם\" תרי זימני\u0004 \u0005[שתי פעמים]\u0006 (במדבר טו, כ. ובמדבר טו, כא), ושמא יש בהדגשה יתירה זו כדי להצריך בעלות בענין חלה, ואין כן במצה של מעשר שני, ולכן אין להוכיח מכאן.","נאמר במשנה כי אתרוג \u0003של תרומה טמאה פסולה.\u0004 והטעם כפי שהסברנו — \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה היתר אכילה.\u0004","נאמר במשנה כי אתרוג \u0003של תרומה טהורה לא יטול,\u0004 ואם נטל — כשר. \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בבעיה זו החכמים \u0003ר' אמי ור' אסי, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מפני שמכשירה\u0004 לקבל טומאה. שקודם לכן היה האתרוג — ככל דבר מן הצומח שלא הורטב במים — בלתי ראוי לקבל טומאה (ראה ויקרא יא, לז-לח), וכיון שנוגע באתרוג בידים רטובות (שנרטבו בעת הוצאת המינים האחרים מן המים, בהם הם נשמרים כדי שלא יתייבשו), — בכך הוא מכשירו לקבל טומאה, ולכן אסרו ליטול אתרוג של תרומה שמא יטמא ויפסל מאכילה. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: מפני שמפסידה.\u0004 שעל ידי משמוש הידים באתרוג שוב אין קליפת האתרוג ראויה לאכילה, ונמצא מקלקל תרומה שהיתה ראויה לאכילה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]?\u0006 ומשיבים: \u0003כגון שקרא עליה שם,\u0004 כלומר: הקדיש את האתרוג לתרומה \u0003חוץ מקליפתה\u0004 ה\u0003חיצונה,\u0004 שקליפה זו לא הקדיש והתכוון שתשאר כחולין. ואז, \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003מפני שמכשירה — איכא\u0004 \u0005[יש]\u0006 איסור, שהרי מכשירה מכל מקום. ואילו \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003מפני שמפסידה\u0004 לתרומה — \u0003ליכא\u0004 \u0005[אין כאן]\u0006 צד איסור.","נאמר במשנה ש\u0003אם נטל\u0004 אתרוג תרומה טהורה — \u0003כשרה.\u0004 ומסבירים: כי \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהאיסור באלה הוא \u0003מפני שאין בה היתר אכילה — הרי יש בה היתר אכילה\u0004 בתרומה טהורה, ו\u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאמר]\u0006 \u0003לפי שאין בה דין ממון — הרי יש בה דין ממון.\u0004","שנינו במשנה כי אתרוג \u0003של דמאי\u0004 נחלקו בו בית שמאי ובית הלל, ולדעת בית הלל כשר. ושואלים: \u0003מאי טעמייהו\u0004 \u0005[מה טעמם]\u0006 של \u0003בית הלל?\u0004 שהרי יש בדמאי חשש שטבל הוא, ואסור באכילה! ומשיבים: \u0003כיון דאי בעי מפקר להו לנכסיה\u0004 \u0005[שאם ירצה יפקיר להם לנכסיו]\u0006 \u0003והוי\u0004 \u0005[וייעשה]\u0006 \u0003עני וחזי ליה\u0004 \u0005[ו\u0006אז \u0005יהיה ראוי לו]\u0006 לאכול מן הדמאי, כשאר עניים המותרים באכילת דמאי, לכן \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 כשאינו עני \u0003\"לכם\"\u0004 — משלכם \u0003קרינא ביה\u0004 \u0005[קוראים אנו בו],\u0006 שהרי יש בו אפשרות כלשהי להיתר אכילה. \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מאכילין\u0004 את \u0003העניים דמאי ואת אכסניא\u0004 (צבא המלך) \u0003דמאי.\u0004 הרי ראיה לשיטת בית הלל.","\u0003ובית שמאי\u0004 שלדעתם אין יוצאים באתרוג של דמאי, סוברים כי \u0003עני לא אכיל\u0004 \u0005[אוכל]\u0006 \u0003דמאי, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מאכילין\u0004 את \u0003העניים דמאי ואת האכסנאים\u0004 (צבא המלך) \u0003דמאי, ואמר רב הונא: תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]\u0006 ש\u0003בית שמאי אומרים: אין מאכילין את העניים ואת האכסנאים דמאי, ובית הלל אומרים: מאכילין את העניים דמאי ואת האכסנאים דמאי.\u0004 הרי שלשיטתם אין אפשרות כלשהי להיתר אכילה בדמאי ומובנת איפוא שיטתם.","שנינו במשנה שאתרוג \u0003של מעשר שני שבירושלים\u0004 לא יטול לכתחילה. ומסבירים: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 בענין תרומה \u0003מפני שמכשירה\u0004 להיטמא, \u0003הרי\u0004 אף כאן \u0003מכשירה\u0004 להטמא, \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003מפני שמפסידה\u0004 את הקליפה מאכילה — \u0003הרי\u0004 אף כאן \u0003מפסידה.\u0004","נאמר במשנה בענין אתרוג מעשר שני בירושלים, שאף שמן הדין לא יטלנו לכתחילה, מכל מקום \u0003אם נטל\u0004 — \u0003כשרה.\u0004 ומסבירים: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003מפני שאין בה היתר אכילה\u0004 — הרי הלכה זו היא ל\u0003דברי הכל,\u0004 שהרי כיון שהוא בירושלים הרי הותר לאכילה. ו\u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003לפי שאין בה דין ממון הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]\u0006 — שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 שלדעתם מעשר שני אינו נחשב כממון גבוה, ושלא כשיטת ר' מאיר.","שנינו במשנה שאם \u0003עלתה חזזית\u0004 על רובו של אתרוג הרי זה פסול. \u0003אמר רב חסדא: דבר זה רבינו הגדול,\u0004 (רב) \u0003אמרו, המקום\u0004 (הקדוש ברוך הוא) \u0003יהיה בעזרו.\u0004 וכך אמר: \u0003לא שנו\u0004 שפסול \u0003אלא\u0004 כשהיתה החזזית \u0003במקום אחד, אבל\u0004 היתה החזזית מפוזרת \u0003בשנים או שלשה מקומות — כשר. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אדרבה, בשנים ושלשה מקומות הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003כמנומר\u0004 ומכוער יותר \u0003ופסול\u0004 שהרי ודאי אינו הדר.","\u0003אלא\u0004 כך יש לתקן: \u0003אי אתמר אסיפא אתמר\u0004 \u0005[אם נאמרו\u0006 דברי רב \u0005על סופה\u0006 של המשנה \u0005נאמרו].\u0006 שאמרו אם עלתה חזזית \u0003על מיעוטו‍\u0004 — \u0003כשר. אמר רב חסדא: דבר זה רבינו הגדול אמרו והמקום יהיה בעזרו: לא שנו\u0004 שכשר \u0003אלא\u0004 כשעלתה חזזית \u0003במקום אחד, אבל\u0004 אם עלתה \u0003בשנים או שלשה מקומות,\u0004 אפילו על מיעוטו — \u0003הוה ליה\u0004 \u0005[הריהו]\u0006 \u0003כמנומר, ופסול. אמר רבא:\u0004 אם היתה החזזית \u0003על חוטמו\u0004 (בחלקו העליון של האתרוג), שהכל רואים אותו, והוא עיקר הדרו — \u0003אפילו במשהו נמי\u0004 \u0005[גם כן]\u0006 \u0003פסול.\u0004","שנינו במשנה: \u0003נטלה פטמתו\u0004 של האתרוג — פסול. \u0003תנא\u0004 \u0005[שנה]\u0006 החכם \u0003ר' יצחק בן אלעזר\u0004 בברייתא, \"נטלה פטמתו\" פירושו: \u0003נטלה בוכנתו\u0004 שהיא נראית כמו בוכנה והיא הגידול העצי בראשו של האתרוג.","שנינו במשנה כי אתרוג ש\u0003נקלף\u0004 — פסול. \u0003אמר רבא: האי אתרוגא דאגליד כאהינא סומקא\u0004 \u0005[אתרוג זה שהתקלף\u0006 כדרך שמתקלפת \u0005תמרה אדומה]\u0006 שהקליפה החיצונה הדקה בלבד ניטלת והשאר נשאר בשלימותו — \u0003כשר.\u0004 ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]\u0006 במפורש: \u0003נקלף\u0004 — \u0003פסול!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[אין זה קשה],\u0006"],["\u0003הא\u0004 \u0005[זה]\u0006 ששנינו כי נקלף פסול, זהו דווקא שנקלף \u0003בכולה,\u0004 ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר רבא כי כשנקלף כשר, זהו \u0003במקצתה,\u0004 אם נקלף כשר.","שנינו במשנה דין אתרוג ש\u0003נסדק\u0004 או \u0003ניקב. תני\u0004 \u0005[שנה]\u0006 \u0003עולא בר חנינא:\u0004 אם \u0003ניקב נקב מפולש\u0004 מקצה לקצה — נקב כזה פסול \u0003במשהו,\u0004 ואם ניקב נקב \u0003שאינו מפולש\u0004 — הרי זה פסול רק כשגודלו \u0003כ\u0004של \u0003איסר\u0004 (מטבע).","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: נולדו באתרוג סימני טריפה מהו?\u0004 כי כפי שנראה יש דמיון בין ההלכות שנאמרו באתרוג לבין כמה מדיני טריפה בעופות ובהמות, והבעיה היא האם קשר זה קיים גם בדינים שלא נאמרו במפורש באתרוג ונאמרו בטריפה. ושואלים: \u0003מאי קמיבעיא ליה\u0004 \u0005[מה נשאלה\u0006 נסתפקה \u0005לו]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 לענין אתרוג ש\u0003נקלף\u0004 שיש דין טריפה כזו בבהמה — הלא \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר, \u0003אי\u0004 \u0005[אם]\u0006 הכוונה היא לפסול \u0003נסדק,\u0004 שקיים בבהמה סוג טריפה כזה וכגון שנסדקה גרוגרתה — הלא \u0003תנינא\u0004 \u0005[שנינו].\u0006 \u0003אי\u0004 \u0005[אם]\u0006 הכוונה היא לפסול \u0003ניקב\u0004 ושכגון זה קיים בבהמה שניקב מוחה — הלא \u0003תנינא\u0004 \u0005[שנינו],\u0006 ואם כן במה נסתפק לו?","ומשיבים: \u0003כי קא מיבעיא ליה\u0004 \u0005[כאשר נסתפק לו]\u0006 היה זה בהלכה שאמר \u0003עולא\u0004 בשם \u0003ר' יוחנן: ריאה שנשפכה כקיתון,\u0004 כלומר: שפנים הריאה נימוח כולו עד שנעשה נוזלי — אין זו טריפה, והבהמה \u0003כשרה. ואמר רבא: והוא דקיימא סימפונהא\u0004 \u0005[ש\u0006עדיין \u0005קיימים הסימפונות]\u0006 צינורות הנשימה בתוך הריאה. ונדייק: \u0003הא לא קיימי סימפונהא\u0004 \u0005[הרי\u0006 אם \u0005לא קיימים הסימפונות] —\u0006 הרי זו \u0003טריפה.\u0004 והשאלה היתה איפוא: \u0003הכא\u0004 \u0005[כאן]\u0006 באתרוג אם נימוח חללו הפנימי, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003דלמא התם\u0004 \u0005[שמא שם]\u0006 \u0003הוא דלא שליט בה אוירא\u0004 \u0005[שאין האויר שולט בו],\u0006 שסגור מכל צד, ולכן \u0003הדר בריא\u0004 \u0005[חוזר\u0006 ו\u0005מבריא]\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 באתרוג \u0003דשליט\u0004 \u0005[ששולט]\u0006 \u0003בה אוירא\u0004 \u0005[אויר],\u0006 \u0003סרוחי מסרחת\u0004 \u0005[\u0006הרי \u0005היא מסרחת]\u0006 מחמת זה ומתקלקלת כולה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]?\u0006","ומתרצים, \u0003תא שמע:\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה, ממה ששנינו: \u0003אתרוג תפוח\u0004 שהתנפח או \u0003סרוח,\u0004 או \u0003כבוש\u0004 בחומץ או בחרדל, או \u0003שלוק\u0004 \u0005[מבושל],\u0006 אתרוג \u0003כושי\u0004 (שחור), אתרוג \u0003לבן,\u0004 אתרוג \u0003מנומר — פסול. אתרוג\u0004 שצורתו \u0003ככדור\u0004 — \u0003פסול, ויש אומרים: אף התיום\u0004 (שני אתרוגים הדבוקים יחד). \u0003אתרוג הבוסר\u0004 — \u0003ר' עקיבא פוסל וחכמים מכשירין. גדלו\u0004 את האתרוג \u0003ב\u0004תוך \u0003דפוס ועשאו\u0004 על ידי הדפוס \u0003כמין בריה אחרת\u0004 שאין לו עוד צורת אתרוג — הרי זה \u0003פסול,\u0004","\u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 ענין אתרוג ה\u0003תפוח\u0004 וכן ה\u0003סרוח, מאי לאו\u0004 \u0005[האם לא]\u0006 נפרש: \u0003תפוח\u0004 פירושו שנרקב \u0003מבחוץ, וסרוח\u0004 פירושו שנרקב \u0003מבפנים!\u0004 ודוחים: \u0003לא, אידי ואידי\u0004 \u0005[כאן וכאן]\u0006 בשנרקב \u0003מבחוץ, ולא קשיא\u0004 \u0005[ואין זה קשה]\u0006 שנראה שחוזר על אותו דין במילים שונות, כי \u0003הא דתפח אף על גב דלא סרח\u0004 \u0005[זה שהתנפח אף על פי שאינו מסריח]\u0006 והוא ה\"תפוח\", \u0003הא דסרח אף על גב דלא תפח\u0004 \u0005[\u0006ו\u0005זה שהסריח אף על פי שלא התנפח]\u0006 והוא הקרוי \"סרוח\".","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא שהבאנו: \u0003אתרוג כושי\u0004 — \u0003פסול.\u0004 ושואלים, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת: אתרוג \u0003כושי — כשר, דומה לכושי\u0004 — \u0003פסול! אמר אביי: כי תנן נמי מתניתין\u0004 \u0005[כאשר שנינו גם כן\u0006 ב\u0005משנתנו]\u0006 שפסול, לא בכושי שנינו כן, כי אם \u0003בדומה לכושי תנן\u0004 \u0005[שנינו\u0006 שם\u0005].\u0006 \u0003רבא אמר: לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא לן והא להו\u0004 \u0005[זה לנו וזה להם].\u0006 כלומר אנו בני בבל שקרובים אנחנו לארץ כוש ורוב אתרוגינו כהים, אין אתרוג כזה נחשב איפוא כשינוי וכשר. אבל בני ארץ ישראל הרחוקים מארץ כוש ואתרוגיהם בהירים, אתרוג כזה נחשב במקומם כשינוי ולכן הוא פסול.","עוד שנינו בברייתא זו: \u0003אתרוג הבוסר\u0004 — \u0003ר' עקיבא פוסל וחכמים מכשירין. אמר רבה: ר' עקיבא ור' שמעון אמרו דבר אחד,\u0004 שיש להם שיטה אחת. ומפרטים: \u0003ר' עקיבא — הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 לענין אתרוג שכל עוד לא נגמר בישולו, אינו נחשב עדיין כפרי ופסול. \u0003ר' שמעון מאי היא\u0004 \u0005[מה הוא]\u0006 הדבר שאמר? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' שמעון פוטר את האתרוגים בקוטנן\u0004 מלהפריש מהם מעשר. הרי שאף לשיטתו אתרוג שלא נגמר אינו נחשב כפרי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לא היא\u0004 ואין זו אותה שיטה, כי \u0003עד כאן לא\u0004 שמענו \u0003קאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' עקיבא הכא\u0004 \u0005[כאן]\u0006 ופסל אתרוג הבוסר, אלא משום \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שיהיה \u0003הדר וליכא\u0004 \u0005[ואין\u0006 בו\u0005]\u0006 מפני קטנותו או צבעו, \u0003אבל התם\u0004 \u0005[שם]\u0006 יתכן ש\u0003כרבנן סבירא ליה\u0004 \u0005[כ\u0006דעת \u0005חכמים סבור הוא],\u0006 שאפילו אתרוג בוסר חייב במעשרות.","ולהיפך, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר, כי \u0003עד כאן לא\u0004 שמענו \u0003קאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' שמעון התם\u0004 \u0005[שם]\u0006 כי אתרוג הבוסר פטור ממעשרות, \u0003אלא\u0004 משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עשר תעשר את כל תבואת זרעך\u0004 היוצא השדה שנה שנה\u0003\"\u0004 (דברים יד, כב), ולמד מכאן שחובת מעשר היא רק בתבואה בשלה \u0003כדרך שבני אדם מוציאין לזריעה,\u0004 ופרי בוסר שאינו ראוי לזריעה — אינו חייב במעשר. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בהכשר אתרוג למצוה שלא נתמעט אתרוג הבוסר בלשון הכתוב, יתכן ש\u0003כרבנן סבירא ליה\u0004 \u0005[כ\u0006דעת \u0005חכמים סבור הוא]\u0006 ומתיר אפילו באתרוג הבוסר."],["\u0003ותו לא מידי\u0004 \u0005[ועוד אין דבר].\u0006 כלומר: דבר זה אכן מבהיר באופן מוחלט כי אין דעת ר' עקיבא כדעת ר' שמעון, ולהיפך.","עוד שנינו בברייתא שם, שאם \u0003גדלו\u0004 את האתרוג \u0003בדפוס ועשאו כמין בריה אחרת\u0004 — \u0003פסול. אמר רבא: לא שנו\u0004 שפסול, \u0003אלא\u0004 שעשאו \u0003כמין בריה אחרת, אבל\u0004 אם עשאו שיהיה \u0003כברייתו — כשר.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 הלא \u0003כמין בריה אחרת תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 משמע שכברייתו — כשר! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא כגון \u0003דעבידא דפי דפי\u0004 \u0005[שעשאו\u0006 על ידי הדפוס שיהא \u0005שורות שורות]\u0006 ואינו כצורת אתרוג בדיוק, אולם כיון שצורתו הכללית כאתרוג, הרי זה כשר.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בדבר \u0003אתרוג שנקבוהו עכברים, אמר רב: אין זה הדר\u0004 ואין יוצאים בו. ותוהים: \u0003איני\u0004 \u0005[כן הוא?]!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' חנינא\u0004 היה \u0003מטביל בה,\u0004 כלומר: היה מטביל את האתרוג ואוכל ממנו \u0003ונפיק\u0004 \u0005[ויוצא]\u0006 \u0003בה,\u0004 כלומר: בשאריתו, לשם מצות אתרוג. ושואלים: \u0003ולר' חנינא\u0004 הרי \u0003קשיא מתניתין\u0004 \u0005[קשה משנתנו],\u0006 ששנינו בה שאתרוג חסר פסול!","ומסבירים \u0003בשלמא מתניתין\u0004 \u0005[נניח משנתנו]\u0006 \u0003לר' חנינא לא קשיא\u0004 \u0005[אינה קשה]\u0006 כל כך, שאפשר לתרץ: \u0003כאן\u0004 שאסרה המשנה חסר הרי זה \u0003ביום טוב ראשון\u0004 של חג הסוכות, שיש להקפיד בו ביותר, \u0003כאן\u0004 שמשמע ממנהגו של ר' חנינא שאף אתרוג החסר כשר, הרי זה \u0003ביום טוב שני,\u0004 כלומר: בשאר ימות החג. \u0003אלא לרב\u0004 שאמר כי בשנקבוהו עכברים פסול, \u0003קשיא\u0004 \u0005[קשה]\u0006 מה שעשה ר' חנינא! \u0003אמר לך רב\u0004 \u0005[\u0006יכול היה \u0005רב לומר לך]:\u0006 מכאן אין להקשות, כי \u0003שאני\u0004 \u0005[שונים]\u0006 ה\u0003עכברים דמאיסי\u0004 \u0005[שהם מאוסים]\u0006 ואף מה שהותירו נמאס ולכן הוא פסול, מה שאין כן בנשאר מאכילת אדם שאין הנותר נמאס ולכך הריהו כשר.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 בלשון אחרת, \u0003אמר רב:\u0004 אתרוג זה שנקבוהו עכברים — \u0003זה הדר.\u0004 כלומר, אינו יוצא מגדר הדר בשל כך. \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003ר' חנינא\u0004 היה \u0003מטביל בה,\u0004 כלומר: את אתרוגו והיה אוכל ממנו \u0003ונפיק בה\u0004 \u0005[ויוצא בו],\u0006 משמע שחיסרון אינו פוסל. ושואלים: \u0003ולר' חנינא קשיא מתניתין\u0004 \u0005[קשה משנתנו]!\u0006 ומתרצים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003כאן ביום טוב ראשון כאן ביום טוב שני.\u0004","במשנה הוזכרה מחלוקת ר' יהודה ור' מאיר בשיעורו של \u0003אתרוג קטן. אמר רפרם בר פפא: כמחלוקת כאן\u0004 — \u0003כך מחלוקת ב\u0004ענין \u0003אבנים מקורזלות. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בשבת שלש אבנים מקורזלות\u0004 (רכות, הראויות לכך) \u0003מותר להכניס\u0004 בשבת \u0003לבית הכסא\u0004 כדי לקנח בהן. שלמרות שאסור לטלטל אבנים בשבת, משום איסור מוקצה — מפני כבוד הבריות התירו חכמים. אלא נחלקו \u0003כמה שיעורן\u0004 של אבנים אלו? \u0003ר' מאיר אומר: כאגוז, ר' יהודה אומר: כביצה.\u0004 וכמובן שאין הדברים דומים בטעמם אבל יש דמיון בשיעורים שניתנו, והדבר יכול לשמש כסימן.","שנינו במשנה כי לדברי ר' יהודה שיעורו העליון של אתרוג \u0003גדול,\u0004 הוא \u0003כדי שיאחז\u0004 שני אתרוגים ביד. ולדברי ר' יוסי אין לו שיעור, וכשר אף זה שמחמת גודלו צריך לאוחזו בשתי ידיו. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יוסי: מעשה בר' עקיבא שבא לבית הכנסת ואתרוגו על כתפו\u0004 מרוב גודלו. ומכאן שמותר לצאת באתרוג גדול כל כך! \u0003אמר לו ר' יהודה: משם\u0004 מביא אתה \u0003ראיה? אף הם\u0004 חכמים שראוהו בכך \u0003אמרו לו: אין זה הדר.\u0004","\u0003אין אוגדין את הלולב אלא במינו,\u0004 כלומר, באחד מארבעת המינים שבלולב, אלו \u0003דברי ר' יהודה. ור' מאיר אומר: אפילו בחוט\u0004 או \u0003במשיחה\u0004 (בחבל מדידה) מותר. \u0003אמר ר' מאיר: מעשה באנשי ירושלים שהיו אוגדין את לולביהן בגימוניות\u0004 (טבעות) \u0003של זהב,\u0004 ומכאן ראיה שאין צריך לאוגדן דווקא במינן. \u0003אמרו לו: במינו היו אוגדין אותו מלמטה\u0004 תחת אותן הגימוניות, ואלה לא היו לשם אגד אלא לקישוט בלבד.","\u0003אמר רבא:\u0004 כשאמרו חכמים שאוגדים אותו במינו אין זה דווקא בחלק המשמש למצוה, כגון בעלי הלולב, אלא \u0003אפילו בסיב\u0004 הגדל סביב לדקל, ו\u0003אפילו בעיקרא דדיקלא\u0004 בחתיכה מגזעו של הדקל. \u0003ואמר רבא: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יהודה — קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003לולב צריך אגד\u0004 מן התורה, שאגידתו היא מעיקר מצותו \u0003ואי מייתי מינא אחרינא\u0004 \u0005[ואם מביא מין אחר]\u0006 לאגוד בו, אם כן \u0003הוה\u0004 \u0005[הרי הם]\u0006 \u0003חמשה מיני\u0004 \u0005[מינים]\u0006 ועובר משום \"בל תוסיף\".","\u0003ואמר רבא: מנא אמינא לה\u0004 \u0005[מנין אומר אני]\u0006 הלכה זו ש\u0003סיב ועיקרא דדיקלא\u0004 \u0005[ועיקר הדקל]\u0006 \u0003מינא דלולבא\u0004 \u0005[\u0006מ\u0005מין הלולב]\u0006 \u0003הוא\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005];\u0006 נאמר: \u0003\"בסכת תשבו\u0004 שבעת ימים\u0003\"\u0004 (ויקרא כג, מד), ופירשו: \u0003סוכה של כל דבר\u0004 ולא הקפיד הכתוב ממה יעשה את סככה, אלו \u0003דברי ר' מאיר. ר' יהודה אומר: אין סוכה נוהגת אלא בארבעה מינים שבלולב.\u0004 וטענתו: \u0003והדין\u0004 (והסברה) \u0003נותן\u0004 שכן הוא, שאפשר לומר קל וחומר: \u0003ומה לולב שאין נוהג\u0004 במצותו \u0003בלילות כבימים,\u0004 אלא מצוותו ביום בלבד, \u0003אינו נוהג אלא בארבעה מינין\u0004 בלבד, \u0003סוכה שנוהגת\u0004 מצותה \u0003בלילות כבימים — אינו דין שלא תהא אלא בארבעת מינין!\u0004","\u0003אמרו לו:\u0004 אין זה קל וחומר, כי \u0003כל דין\u0004 (קל וחומר) \u0003שאתה דן\u0004 אשר \u0003תחלתו\u0004 לכאורה \u0003להחמיר,\u0004 אבל \u0003סופו\u0004, כלומר: התוצאה המתבקשת ממנו, הריהי \u0003להקל — אינו דין.\u0004 שהרי בסופו של דבר במקום ללמוד להחמיר נמצאת מיקל ובטלת סברת עצמך."],["\u0003לא מצא ארבעת מינין\u0004 אלה כדי לסכך בהם סוכתו \u0003יהא יושב ובטל\u0004 ממצות סוכה, \u0003ו\u0004הלא \u0003התורה אמרה: \"בסכת תשבו שבעת ימים\"\u0004 ולא נתפרשו החומרים מהם היא צריכה להיעשות ומשמע שהיא \u0003סוכה של כל דבר.\u0004 ונמצא שהלימוד, שלימדת שלכאורה בא רק להוסיף חומרה יבוא לגרום ביטול מצוה. \u0003וכן בעזרא\u0004 הוא \u0003אומר: \"צאו ההר והביאו עלי זית ועלי עץ שמן ועלי הדס ועלי תמרים ועלי עץ עבת לעשת סכת ככתוב\"\u0004 (נחמיה ח, טו), ומכאן שאפשר להשתמש לצורך הסוכה גם בדברים שאינם מארבעת המינים!","\u0003ור' יהודה סבר,\u0004 כי \u0003הני\u0004 \u0005[אלה]\u0006 עלי זית ועץ שמן האמורים בספר עזרא — לא נצטוו להביאם אלא \u0003לדפנות\u0004 שמצד הדין יכולות הן להיעשות מכל חומר שהוא, ושאר המינים שנאמרו שם; \u0003עלי הדס ועלי תמרים ועלי עץ עבות,\u0004 שהם מארבעת המינים — נאמרו ביחס \u0003לסכך.\u0004 ולענייננו ברורה דעת ר' יהודה שאין מסככים אלא בארבעת המינים, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003מסככין בנסרין\u0004 (קורות עץ), אלו \u0003דברי ר' יהודה. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003סיב ועיקרא דדיקלא\u0004 \u0005[ועיקר הדקל]\u0006 \u0003מינא דלולבא\u0004 \u0005[\u0006מ\u0005מין הלולב]\u0006 \u0003הוא,\u0004 שהרי אין קורות בארבעת המינים הללו, אלא מגזע הדקל. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ותוהים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר\u0004 באמת \u0003ר' יהודה\u0004 כי \u0003בארבעה מינין אין\u0004 \u0005[כן]\u0006 מסככים בהם, אבל \u0003מידי אחרינא\u0004 \u0005[\u0006ב\u0005דבר אחר]\u0006 \u0003לא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003סיככה\u0004 את הסוכה \u0003בנסרים של ארז שיש בהן\u0004 ברוחבם \u0003ארבעה טפחים — דברי הכל פסולה,\u0004 שהיא כתקרת בית. \u0003אין בהן ארבעה טפחים — ר' מאיר פוסל, ור' יהודה מכשיר. ומודה ר' מאיר שאם יש בין נסר לנסר\u0004 חלל פנוי \u0003כמלא נסר\u0004 עצמו — \u0003שמניח פסל\u0004 (ענפים ועלים) \u0003ביניהן, וכשרה\u0004 על ידי סכך זה. על כל פנים רואים מכאן שלדעת ר' יהודה מסככים בנסרים של ארז ואין צריך שיהיה הסכך מארבעת המינים דווקא!","ומשיבים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"ארז\"\u0004 זה ששנינו — בעצם מין \u0003הדס\u0004 הוא. וכדברי \u0003רבה בר רב הונא,\u0004 ש\u0003אמר רבה בר רב הונא: אמרי בי\u0004 \u0005[אומרים\u0006 בני \u0005בית\u0006 מדרשו\u0005],\u0006 של \u0003רב: עשרה מיני ארזים הם, שנאמר: \"אתן במדבר ארז שיטה והדס\u0004 ועץ שמן אשים בערבה ברוש תדהר ותאשור יחדיו\" (ישעיהו מא, יט).","שנינו במשנה ש\u0003ר' מאיר אומר\u0004 כי יש להתיר לאגוד את המינים \u0003אפילו במשיחה. תניא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005],\u0006 \u0003אמר ר' מאיר: מעשה ביקירי ירושלים שהיו אוגדין את לולביהן בגימוניות\u0004 (טבעות) \u0003של זהב. אמרו לו: משם\u0004 מביא אתה \u0003ראיה?! במינו היו אוגדין אותו מלמטה\u0004 מתחת לגימוניות ואותן גימוניות לא היו אלא לנוי.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבה להנהו\u0004 \u0005[לאותם]\u0006 \u0003מגדלי הושענא דבי ריש גלותא\u0004 \u0005[קולעי,\u0006 אוגדי \u0005ארבעת המינים של\u0006 \u0005בית ראש הגולה]:\u0006 \u0003כי גדליתו הושענא דבי ריש גלותא\u0004 \u0005[כאשר אתם קולעים\u0006 אוגדים \u0005את ארבעת המינים של בית ראש הגולה],\u0006 \u0003שיירי ביה\u0004 \u0005[השאירו בו]\u0006 מקום \u0003בית יד\u0004 שאינו אגוד ואינו מקושט \u0003כי היכי דלא תיהוי\u0004 \u0005[כדי שלא תהיה]\u0006 \u0003חציצה\u0004 בין ידו של הנוטל לבין המינים עצמם.","\u0003רבא אמר:\u0004 אין צורך בכך, כי \u0003כל\u0004 דבר שעושים כדי \u0003לנאותו\u0004 — \u0003אינו חוצץ. ואמר רבה\u0004 מעין דבריו הקודמים: \u0003לא לינקיט איניש הושענא בסודרא\u0004 \u0005[לא יקח אדם את ארבעת המינים על ידי סודר],\u0006 משום \u0003דבעינא\u0004 \u0005[שצריכים אנו]\u0006 שתהא \u0003לקיחה תמה\u0004 (שלימה) \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי אינו נוטל את המינים עצמם ללא חציצה. \u0003ורבא אמר:\u0004 אין לחשוש לכך, כי \u0003לקיחה על ידי דבר אחר — שמה לקיחה.\u0004","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה\u0006 את הדעה הזו\u0005]\u0006 ש\u0003לקיחה על ידי דבר אחר — שמה לקיחה, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אזוב\u0004 שבו מזים ממי פרה אדומה על טמא מת כדי לטהרו, אם היה \u0003קצר\u0004 מכדי שיגיע לתחתית השפופרת המכילה את המים — \u0003מספקו\u0004 (מאריך אותו עד שיספיק) \u0003בחוט\u0004 או \u0003בכוש\u0004 (בפלך) שתוחב בו, \u0003וטובל\u0004 במים \u0003ועולה ואוחז באזוב\u0004 עצמו \u0003ומזה.\u0004 ולכאורה \u0003אמאי\u0004 \u0005[מדוע]\u0006 יכול הוא לעשות בדרך זו? והלא \u0003\"ולקח\u0004 אזוב \u0003וטבל\u0004 במים איש טהור והיזה\u0003\"\u0004 (במדבר יט, יח) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 ומשמע כי הטבילה במים צריכה להיות באותו אזוב שלקח! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003לקיחה על ידי דבר אחר שמה לקיחה.\u0004","את ההוכחה הזו דוחים: \u0003ממאי\u0004 \u0005[ממה\u0006 מוכיח אתה זאת]? \u0003דלמא שאני התם\u0004 \u0005[שמא שונה שם],\u0006 ש\u0003כיון דחבריה\u0004 \u0005[שחיבר]\u0006 בו את החוט חיבור קבוע \u0005—\u0006 \u0003כגופיה דמי\u0004 \u0005[הריהו כגופו],\u0006 אבל מה שאינו מחובר ואינו גופו אין לוקחים על ידו. \u0003אלא\u0004 יש לדחות הוכחה זו, ולהוכיח שלקיחה על ידי דבר אחר נחשבת כלקיחה \u0003מהכא\u0004 \u0005[מכאן];\u0006 ממה ששנינו: \u0003נפל\u0004 האפר של הפרה האדומה \u0003משפופרת\u0004 שהיה מצוי בה ל\u0003שוקת\u0004 שבה נמצאים המים החיים — הרי זה \u0003פסול,\u0004 משום שצריך שתהא הלקיחה והנתינה מרצונו ומדעתו."],["\u0003הא\u0004 \u0005[הרי]\u0006 אילו \u0003הפילו הוא\u0004 מדעתו - \u0003כשר. אמאי\u0004 \u0005[מדוע]?\u0006 הלא \u0003\"ולקחו... ונתן\"\u0004 (במדבר יט, יח) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 ולכאורה \"ונתן\" משמע בעצמו, \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תשמע מכאן]\u0006 כי \u0003לקיחה על ידי דבר אחר\u0004 כגון שפופרת — \u0003שמה לקיחה.\u0004","\u0003ו\u0004עוד \u0003אמר רבה\u0004 בדיני לולב: לאחר שאגד יחד את ההדסים והערבות, \u0003לא לדוץ איניש לולבא בהושענא\u0004 \u0005[אל ינעץ אדם את הלולב בתוך המינים\u0006 מלמעלה\u0005],\u0006 \u0003דדלמא נתרי טרפי\u0004 \u0005[ושמא ישרו העלים\u0006 אגב נעיצה זו\u0005]\u0006 \u0003והוי\u0004 \u0005[והרי\u0006 זו\u0005]\u0006 \u0003חציצה\u0004 בתוך המינים על ידי העלים התלושים. \u0003ורבא אמר:\u0004 אין לחשוש לכך, כי \u0003מין במינו אינו חוצץ.\u0004","ועוד \u0003אמר רבה:\u0004 אם הלולב ארוך מידי ורוצה לקצצו, \u0003לא ליגוז איניש לולבא בהושענא\u0004 \u0005[אל יקצוץ אדם את הלולב בתוך ארבעת המינים]\u0006 לאחר אגידה, שמא על ידי הקציצה \u0003דמשתיירי הוצא\u0004 \u0005[משתיירים עלי הלולב]\u0006 הקטועים בפנים, \u0003והוי\u0004 \u0005[והרי זו]\u0006 \u0003חציצה, ורבא אמר: מין במינו אינו חוצץ.\u0004","\u0003ואמר רבה: הדס של מצוה\u0004 — \u0003אסור להריח בו, אתרוג של מצוה\u0004 — \u0003מותר להריח בו.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003הדס דלריחא קאי\u0004 \u0005[ש\u0006עיקרו \u0005לריח\u0006 בלבד \u0005עומד],\u0006 \u0003כי אקצייה\u0004 \u0005[כאשר הקצה אותו]\u0006 למצוה — \u0003מריחא אקצייה\u0004 \u0005[מהרחה הקצה אותו],\u0006 שאין להשתמש בו עוד כדרכו אלא למצוה בלבד. ואילו \u0003אתרוג\u0004 שמעיקרו \u0003לאכילה קאי\u0004 \u0005[הוא עומד]\u0006 \u0003כי אקצייה\u0004 \u0005[כאשר הקצה אותו]\u0006 למצוה — \u0003מאכילה אקצייה\u0004 \u0005[הקצה אותו]\u0006 ולכן מותר להריח בו, שודאי לא התכוון גם להנאה צדדית זו.","וכגון זה \u0003אמר רבה: הדס\u0004 בכל שבת \u0003במחובר,\u0004 כלומר: בעודו צומח באילן — \u0003מותר להריח בו,\u0004 ואילו \u0003אתרוג במחובר\u0004 — \u0003אסור להריח בו.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003הדס\u0004 ש\u0003להריח קאי\u0004 \u0005[הוא עומד],\u0006 \u0003אי שרית ליה\u0004 \u0005[אם אתה מתיר לו]\u0006 להריחו בלבד — \u0003לא אתי למגזייה\u0004 \u0005[לא יבוא לגזוז אותו],\u0006 שכיון שמריחו אינו זקוק לו עוד. \u0003אתרוג\u0004 במחובר אסור להריחו, כיון ש\u0003לאכילה קאי\u0004 \u0005[הוא עומד]\u0006 ורגילים לקטוף אותו כדי לאוכלו \u0003ואי שרית ליה\u0004 \u0005[ואם אתה מתיר לו]\u0006 להריחו \u0003אתי למגזייה\u0004 \u0005[יבוא\u0006 מתוך שגרה \u0005לחתוך\u0006 אותו\u0005].\u0006","\u0003ואמר רבה: לולב\u0004 ומיניו — אוחז \u0003בימין והאתרוג\u0004 — \u0003בשמאל.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הוא עושה כן? \u0003הני תלתא מצות\u0004 \u0005[אלה\u0006 שלושה המינים הם \u0005שלוש מצות]\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 האתרוג הוא \u0003חדא מצוה\u0004 \u0005[מצוה אחת]\u0006 וראוי להעדיף שלוש מצות על מצוה אחת, ולכן יש לו לאוחזם בימין. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זריקא: מאי\u0004 [מה] \u0003טעם לא מברכינן\u0004 \u0005[אין אנו מברכים]\u0006 \u0003אלא\u0004 בלשון \u0003\"על נטילת לולב\"\u0004 ולא על נטילת המינים האחרים. אמר לו: \u0003הואיל וגבוה מכולן\u0004 וחשוב ובולט ביותר, הרי הולך כל האגד אחר שמו. ומקשים: אם רק זה הטעם; \u0003ולגבהיה לאתרוג ולבריך\u0004 \u0005[שיגביה את האחרוג\u0006 למעלה מן הלולב \u0005ויברך\u0006 בו\u0005]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זריקא: כוונתי היתה לומר: \u0003הואיל ובמינו גבוה מכולן\u0004 שעץ התמר גבוה מכל המינים האגודים יחד, הרי הוא הבולט שבהם וראוי שהברכה תיקרא על שמו.","\u0003והיכן היו מנענעין\u0004 את הלולב — בשעה שהיו אומרים ב\"הלל\" את הפסוק \u0003\"הודו לה'\u0004 כי טוב\u0003\"\u0004 (תהלים קיח, א) \u0003תחילה וסוף\u0004 המזמור (תהלים קיח, כט), ובפסוק \u0003\"אנא ה' הושיעה נא\"\u0004 (תהלים קיח, כד). אלו \u0003דברי בית הלל. ובית שמאי אומרים אף ב\"אנא ה' הצליחה נא\"\u0004 (תהלים קח, כד) היו מנענעין. \u0003אמר ר' עקיבא: צופה\u0004 (מביט) \u0003הייתי ברבן גמליאל ור' יהושע, שכל העם היו מנענעין את לולביהן והם לא נענעו אלא ב\"אנא ה' הושיעה נא\"\u0004 משמע שכך הלכה למעשה.","על סגנון המשנה תוהים: \u0003נענוע מאן דכר שמיה\u0004 \u0005[מי הזכיר את שמו]?\u0006 הרי לא הודיענו התנא קודם שיש חובה או מנהג של נענוע, וכבר מתחיל לדון מהיכן מנענעים, ולכאורה על מה נסמכים דברים אלה, ומה הקשר שלהם עם האמור קודם לכן? ומשיבים: \u0003התם קאי\u0004 \u0005[שם עומד,\u0006 מוסב\u0005]\u0006 הדבר, על מה שנאמר במשנה בראש הפרק (כט, ב): \u0003\"כל לולב שיש בו שלשה טפחים כדי לנענע בו\u0004 — \u0003כשר\",\u0004 שמשם רואים שיש מצוה בנענוע המינים, \u0003וקאמר\u0004 \u0005[ואמר]\u0006 כאן \u0003היכן מנענעין\u0004 נענוע זה שהוזכר שם.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת מנחות (סא, א): \u0003שתי הלחם ושני כבשי עצרת\u0004 שמביאים בחג השבועות \u0003כיצד הוא עושה\u0004 בהנפתם לפני המזבח? \u0003מניח שתי הלחם על גבי שני הכבשין ומניח ידו תחתיהן, ומניף ומוליך ומביא\u0004 לצדדים, ו\u0003מעלה ומוריד. שנאמר: \"אשר הונף ואשר הורם\"\u0004 (שמות כט, כז), משמע שיש גם תנופה לצדדים והרמה למעלה.","\u0003אמר ר' יוחנן: מוליך ומביא\u0004 לרמז שמקדישו \u0003למי שארבע רוחות שלו, מעלה ומוריד למי שהשמים והארץ שלו. במערבא מתנו הכי\u0004 \u0005[במערב,\u0006 בארץ ישראל, \u0005היו שונים כך]:\u0006 \u0003אמר ר' חמא בר עוקבא אמר ר' יוסי בר' חנינא: מוליך ומביא — כדי\u0004 לרמז בכך בקשה \u0003לעצור רוחות רעות\u0004 סופה וסערה הבאות מן הצדדים, \u0003מעלה ומוריד — כדי לעצור טללים\u0004 וגשמים \u0003רעים\u0004 הבאים מלמעלה. \u0003אמר ר' יוסי בר אבין ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' יוסי בר זבילא: זאת אומרת\u0004 מה שאמרנו שעל ידי התנופה וההרמה מונע רוחות וטללים רעים,"]]};
